            if (operator_tokens.end != operator_tokens.start + 3 or
                !first.matchesKeywordTag(.is) or
                !tokens[operator_tokens.start + 1].matchesKeywordTag(.distinct) or
                !tokens[operator_tokens.start + 2].matchesKeywordTag(.from))
