pub fn parseTargetOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    target_alias: []const u8,
) !void {
    while (true) {
        const field = if (parser.peekKind(tokens, pos.*, .identifier) and identifierContainsQualifier(tokens[pos.*].text)) blk: {
            const source = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
            defer plan_mod.freeQualifiedField(alloc, source);
            if (!std.mem.eql(u8, source.qualifier, target_alias)) return error.UnsupportedSqlShape;
            break :blk try alloc.dupe(u8, source.field);
        } else try parseIdentifierOwnedAlloc(alloc, tokens, pos);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        if (binder.relationalColumnForField(schema, field, null) == null) return error.InvalidSqlCatalog;
        var order: db_mod.types.RelationalRowsQueryOrder = .{ .field = field };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        field_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn validateDistinctOnOrder(
    distinct_on: []const db_mod.types.RelationalRowsExpression,
    order_by: []const db_mod.types.RelationalRowsQueryOrder,
) !void {
    if (order_by.len < distinct_on.len) return error.UnsupportedSqlShape;
    for (distinct_on, 0..) |expression, i| {
        const order = order_by[i];
        if (order.expression) |order_expression| {
            if (!expr_equal.relationalRowsExpressionEqual(order_expression, expression)) return error.UnsupportedSqlShape;
        } else {
            if (expression.kind != .field or expression.field_source != .row or !std.mem.eql(u8, order.field, expression.field)) return error.UnsupportedSqlShape;
        }
    }
}

pub fn parseOptionalDistinctOnAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    type_context: expr_type.RowExpressionTypeContext,
    row_expression_hooks: expr_row_parse.RowExpressionParserHooks,
    arithmetic_hooks: expr_row_parse.ArithmeticExpressionParserHooks,
    variadic_hooks: expr_row_parse.VariadicRowExpressionParserHooks,
) ![]const db_mod.types.RelationalRowsExpression {
    if (!parser.matchKeyword(tokens, pos, "distinct")) return &.{};
    if (!parser.matchKeyword(tokens, pos, "on")) return error.UnsupportedSqlShape;
    try parser.expectToken(tokens, pos, .lparen);
    var expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
    errdefer {
        freeExpressionSlice(alloc, expressions.items);
        expressions.deinit(alloc);
    }
    while (true) {
        const expression = try expr_row_parse.parseRowExpressionAlloc(
            alloc,
            tokens,
            pos,
            type_context,
            row_expression_hooks,
            arithmetic_hooks,
            variadic_hooks,
        );
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        _ = try type_context.rowExpressionOutputType(expression);
        try expressions.append(alloc, expression);
        expression_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    try parser.expectToken(tokens, pos, .rparen);
    if (expressions.items.len == 0) return error.UnsupportedSqlShape;
    return try expressions.toOwnedSlice(alloc);
}

pub const ParsedSystemTimeAsOf = struct {
    sequence: ?u64 = null,
    timestamp_ns: ?u64 = null,

    fn present(self: @This()) bool {
        return self.sequence != null or self.timestamp_ns != null;
    }
};

pub fn parseOptionalSystemTimeAsOf(tokens: []const Token, pos: *usize) !ParsedSystemTimeAsOf {
    const checkpoint = pos.*;
    if (!parser.matchKeyword(tokens, pos, "for")) return .{};
    if (!parser.matchKeyword(tokens, pos, "system_time")) {
        pos.* = checkpoint;
        return .{};
    }
    try parser.expectKeyword(tokens, pos, "as");
    try parser.expectKeyword(tokens, pos, "of");
    if (parser.matchToken(tokens, pos, .number)) |token| {
        if (std.mem.indexOfAny(u8, token.text, ".eE+-") != null) return error.UnsupportedSqlShape;
        return .{ .sequence = std.fmt.parseUnsigned(u64, token.text, 10) catch return error.UnsupportedSqlShape };
    }
    const timestamp_text = if (parser.matchToken(tokens, pos, .string)) |token| token.text else timestamp_text: {
        if (!parser.matchKeywordTag(tokens, pos, .date) and
            !parser.matchKeywordTag(tokens, pos, .timestamp) and
            !parser.matchKeywordTag(tokens, pos, .timestamptz)) return error.UnsupportedSqlShape;
        const token = parser.matchToken(tokens, pos, .string) orelse return error.UnsupportedSqlShape;
        break :timestamp_text token.text;
    };
    const parsed_timestamp_ns = try value_mod.parseSqlTimestampLiteralNs(timestamp_text);
    if (parsed_timestamp_ns < 0) return error.UnsupportedSqlShape;
    return .{ .timestamp_ns = @intCast(parsed_timestamp_ns) };
}

pub fn parseOptionalSystemTimeAsOfSequence(tokens: []const Token, pos: *usize) !?u64 {
    const parsed = try parseOptionalSystemTimeAsOf(tokens, pos);
    if (parsed.timestamp_ns != null) return error.UnsupportedSqlShape;
    return parsed.sequence;
}

pub fn parseOrderModifiers(
    tokens: []const Token,
    pos: *usize,
    order: *db_mod.types.RelationalRowsQueryOrder,
) !?bool {
    order.direction = if (parser.matchKeyword(tokens, pos, "using"))
        try parseOrderUsingDirection(tokens, pos)
    else if (parser.matchKeyword(tokens, pos, "desc"))
        .desc
    else blk: {
        _ = parser.matchKeyword(tokens, pos, "asc");
        break :blk .asc;
    };
    return if (parser.matchKeyword(tokens, pos, "nulls")) blk: {
        if (parser.matchKeyword(tokens, pos, "first")) break :blk true;
        try parser.expectKeyword(tokens, pos, "last");
        break :blk false;
    } else null;
}

pub fn parseOrderUsingDirection(
    tokens: []const Token,
    pos: *usize,
) !db_mod.types.RelationalRowsQueryOrderDirection {
    if (parser.matchToken(tokens, pos, .lt) != null or parser.matchToken(tokens, pos, .lte) != null) return .asc;
    if (parser.matchToken(tokens, pos, .gt) != null or parser.matchToken(tokens, pos, .gte) != null) return .desc;
    return error.UnsupportedSqlShape;
}

pub fn appendOrderWithNullPlacement(
    alloc: std.mem.Allocator,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    order: db_mod.types.RelationalRowsQueryOrder,
    explicit_nulls_first: ?bool,
) !void {
    if (explicit_nulls_first) |nulls_first| {
        if (order.null_test != null) return error.UnsupportedSqlShape;
        var null_order = try cloneOrderForNullTestAlloc(alloc, order);
        var null_order_transferred = false;
        errdefer if (!null_order_transferred) {
            if (null_order.field.len > 0) alloc.free(null_order.field);
            if (null_order.expression) |expression| freeExpression(alloc, expression);
            if (null_order.collation) |collation| alloc.free(collation);
        };
        null_order.direction = if (nulls_first) .desc else .asc;
        null_order.null_test = .is_null;
        try order_by.append(alloc, null_order);
        null_order_transferred = true;
    }
    try order_by.append(alloc, order);
}

pub fn cloneOrderForNullTestAlloc(
    alloc: std.mem.Allocator,
    order: db_mod.types.RelationalRowsQueryOrder,
) !db_mod.types.RelationalRowsQueryOrder {
    if (order.expression) |expression| {
        return .{ .expression = try cloneExpressionAlloc(alloc, expression) };
    }
    if (order.field.len == 0) return error.UnsupportedSqlShape;
    const field = try alloc.dupe(u8, order.field);
    errdefer alloc.free(field);
    const collation = if (order.collation) |value| try alloc.dupe(u8, value) else null;
    errdefer if (collation) |value| alloc.free(value);
    return .{
        .field = field,
        .collation = collation,
    };
}

fn aggregateSpecNameCollision(
    name: []const u8,
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
) bool {
    for (group_fields) |field| {
        if (std.mem.eql(u8, field, name)) return true;
    }
    for (group_expressions) |projection| {
        if (std.mem.eql(u8, projection.output, name)) return true;
    }
    for (aggregations) |aggregation| {
        if (std.mem.eql(u8, aggregation.name, name)) return true;
    }
    return false;
}

fn aggregateSpecNameCollidesWithGroupOutput(
    name: []const u8,
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
) bool {
    for (group_fields) |field| {
        if (std.mem.eql(u8, field, name)) return true;
    }
    for (group_expressions) |projection| {
        if (std.mem.eql(u8, projection.output, name)) return true;
    }
    return false;
}

fn allocateDisambiguatedAggregateSpecNameAlloc(
    alloc: std.mem.Allocator,
    name: []const u8,
    group_fields: []const []const u8,
    group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
) !?[]const u8 {
    if (!aggregateSpecNameCollision(name, group_fields, group_expressions, aggregations)) return null;

    var suffix: usize = 2;
    while (true) : (suffix += 1) {
        const candidate = try std.fmt.allocPrint(alloc, "{s}_{d}", .{ name, suffix });
        if (!aggregateSpecNameCollision(candidate, group_fields, group_expressions, aggregations)) return candidate;
        alloc.free(candidate);
    }
}

fn aggregateSpecWithName(
    spec: db_mod.types.RelationalRowsAggregateSpec,
    name: []const u8,
) db_mod.types.RelationalRowsAggregateSpec {
    return .{
        .name = name,
        .op = spec.op,
        .field = spec.field,
        .expression = spec.expression,
        .distinct = spec.distinct,
        .distinct_max_items = spec.distinct_max_items,
        .percentile = spec.percentile,
        .percentiles = spec.percentiles,
        .percentile_max_items = spec.percentile_max_items,
        .percentile_order = spec.percentile_order,
        .array_max_items = spec.array_max_items,
        .array_order_by = spec.array_order_by,
        .string_delimiter = spec.string_delimiter,
        .filter_predicates = spec.filter_predicates,
        .filter_array_any = spec.filter_array_any,
        .filter_array_contains = spec.filter_array_contains,
        .filter_array_eq = spec.filter_array_eq,
        .filter_in_predicates = spec.filter_in_predicates,
        .filter_json_contains = spec.filter_json_contains,
        .filter_json_path_eq = spec.filter_json_path_eq,
        .filter_json_path_exists = spec.filter_json_path_exists,
        .filter_text_patterns = spec.filter_text_patterns,
        .filter_expressions = spec.filter_expressions,
        .filter_expression_array_contains = spec.filter_expression_array_contains,
        .filter_any = spec.filter_any,
        .filter_not = spec.filter_not,
    };
}

pub fn parseAggregateSelectListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    function_bindings: expr_row_parse.SqlFunctionBindings,
    type_context: expr_type.RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    aggregate_spec_options: AggregateSpecParserOptions,
    select_item_options: SelectItemParserOptions,
) !plan_mod.AggregateSelectList {
    var group_fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (group_fields.items) |field| alloc.free(field);
        group_fields.deinit(alloc);
    }
    var group_expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
    errdefer {
        for (group_expressions.items) |projection| freeExpressionProjection(alloc, projection);
        group_expressions.deinit(alloc);
    }
    var aggregations = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAggregateSpec).empty;
    errdefer {
        plan_mod.freeAggregateSpecs(alloc, aggregations.items);
        aggregations.deinit(alloc);
    }
    var outputs = std.ArrayListUnmanaged(plan_mod.AggregateSelectOutputRef).empty;
    errdefer outputs.deinit(alloc);

    while (true) {
        const item_start = pos.*;
        const generated_item = try generatedProjectionItemAtStart(tokens, item_start, generated_read_ast);
        if (generated_item == null and generated_read_ast != null) return error.UnsupportedSqlShape;
        const generated_expression = if (generated_item) |item| item.expression else null;
        const generated_aggregate_op = if (generated_expression) |expression|
            try generatedAggregateOpForExpression(tokens, expression)
        else
            null;
        const parse_aggregate = if (generated_read_ast != null) blk: {
            if (nextIsAggregateFunction(tokens, pos.*) and generated_aggregate_op == null) return error.UnsupportedSqlShape;
            break :blk generated_aggregate_op != null;
        } else nextIsAggregateFunction(tokens, pos.*);

        if (parse_aggregate) {
            var spec_options = aggregate_spec_options;
            spec_options.generated_expression_ast = generated_expression;
            const parsed_spec = try parseAggregateSpecAlloc(
                alloc,
                tokens,
                pos,
                params,
                schema,
                type_context,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                spec_options,
            );
            var parsed_spec_transferred = false;
            errdefer if (!parsed_spec_transferred) plan_mod.freeAggregateSpec(alloc, parsed_spec);
            const maybe_spec_name = try allocateDisambiguatedAggregateSpecNameAlloc(
                alloc,
                parsed_spec.name,
                group_fields.items,
                group_expressions.items,
                aggregations.items,
            );
            var spec_name_transferred = false;
            errdefer if (!spec_name_transferred) {
                if (maybe_spec_name) |spec_name| alloc.free(spec_name);
            };
            const spec = if (maybe_spec_name) |spec_name| aggregateSpecWithName(parsed_spec, spec_name) else parsed_spec;
            parsed_spec_transferred = true;
            if (maybe_spec_name != null) {
                alloc.free(parsed_spec.name);
                spec_name_transferred = true;
            }
            var spec_transferred = false;
            errdefer if (!spec_transferred) plan_mod.freeAggregateSpec(alloc, spec);
            try validateGeneratedExpressionItemEnd(generated_item, pos.*);
            try outputs.append(alloc, .{ .kind = .aggregation, .index = aggregations.items.len });
            try aggregations.append(alloc, spec);
            spec_transferred = true;
        } else {
            var item_options = select_item_options;
            item_options.generated_expression_ast = generated_expression;
            const item = try parseSelectItemAlloc(
                alloc,
                tokens,
                pos,
                params,
                schema,
                function_bindings,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                field_source,
                type_context,
                item_options,
            );
            var item_transferred = false;
            errdefer if (!item_transferred) plan_mod.freeSelectItem(alloc, item);
            switch (item) {
                .field => |field| {
                    try outputs.append(alloc, .{ .kind = .group_field, .index = group_fields.items.len });
                    try group_fields.append(alloc, field);
                },
                .expression => |projection_value| {
                    item_transferred = true;
                    const projection = projection_value;
                    var projection_transferred = false;
                    errdefer if (!projection_transferred) freeExpressionProjection(alloc, projection);
                    try outputs.append(alloc, .{ .kind = .group_expression, .index = group_expressions.items.len });
                    try group_expressions.append(alloc, projection);
                    projection_transferred = true;
                },
                else => return error.UnsupportedSqlShape,
            }
            try validateGeneratedExpressionItemEnd(generated_item, pos.*);
            item_transferred = true;
        }
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    try expr_aggregate.validateSelectListOutputs(group_fields.items, group_expressions.items, aggregations.items);

    const owned_group_fields = try group_fields.toOwnedSlice(alloc);
    var group_fields_transferred = false;
    errdefer if (!group_fields_transferred) strings.freeStringSlice(alloc, owned_group_fields);
    const owned_group_expressions = try group_expressions.toOwnedSlice(alloc);
    var group_expressions_transferred = false;
    errdefer if (!group_expressions_transferred) {
        freeExpressionProjections(alloc, owned_group_expressions);
        if (owned_group_expressions.len > 0) alloc.free(owned_group_expressions);
    };
    const owned_aggregations = try aggregations.toOwnedSlice(alloc);
    var aggregations_transferred = false;
    errdefer if (!aggregations_transferred) {
        plan_mod.freeAggregateSpecs(alloc, owned_aggregations);
        if (owned_aggregations.len > 0) alloc.free(owned_aggregations);
    };
    const owned_outputs = try outputs.toOwnedSlice(alloc);
    var outputs_transferred = false;
    errdefer if (!outputs_transferred and owned_outputs.len > 0) alloc.free(owned_outputs);

    group_fields_transferred = true;
    group_expressions_transferred = true;
    aggregations_transferred = true;
    outputs_transferred = true;
    return .{
        .group_fields = owned_group_fields,
        .group_expressions = owned_group_expressions,
        .aggregations = owned_aggregations,
        .outputs = owned_outputs,
    };
}

pub fn parseOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    options: OrderByParserOptions,
) !void {
    return try parseOrderByWithExpressionHooksAlloc(
        alloc,
        tokens,
        pos,
        order_by,
        options.schema,
        options.function_bindings,
        options.field_expression_qualifiers,
        options.returning_expression_qualifiers,
        options.defer_row_expression_field_validation,
        options.type_context,
        options.order_expression_hooks,
        options.generated_read_ast,
        options.generated_order_items,
    );
}

pub fn parseOrderByWithExpressionHooksAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    schema: runtime_schema.TableSchema,
    function_bindings: expr_row_parse.SqlFunctionBindings,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    type_context: expr_type.RowExpressionTypeContext,
    hooks: OrderExpressionParserOptions,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    generated_order_items: ?*const generated_parser.GeneratedSqlListAst,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_item = if (generated_order_items) |items|
            try generatedExpressionListItemAtStart(tokens, item_start, items)
        else
            try generatedOrderItemAtStart(tokens, item_start, generated_read_ast);
        if (generated_item == null and (generated_read_ast != null or generated_order_items != null)) return error.UnsupportedSqlShape;
        const generated_expression = if (generated_item) |item| item.expression else null;
        var item_hooks = hooks;
        item_hooks.generated_expression_ast = generated_expression;
        var order = try parseOrderExpressionAlloc(
            alloc,
            tokens,
            pos,
            schema,
            function_bindings,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
            type_context,
            item_hooks,
        );
        var order_transferred = false;
        errdefer if (!order_transferred) {
            if (order.field.len > 0) alloc.free(order.field);
            if (order.expression) |expression| freeExpression(alloc, expression);
            if (order.collation) |collation| alloc.free(collation);
        };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try validateGeneratedExpressionItemEnd(generated_item, pos.*);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        order_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn parseSelectOutputOrderByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
    select: plan_mod.SelectList,
    options: OrderByParserOptions,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_item = try generatedOrderItemAtStart(tokens, item_start, options.generated_read_ast);
        if (generated_item == null and options.generated_read_ast != null) return error.UnsupportedSqlShape;
        const generated_expression = if (generated_item) |item| item.expression else null;
        var order_expression_hooks = options.order_expression_hooks;
        order_expression_hooks.generated_expression_ast = generated_expression;
        var order = if (parser.matchToken(tokens, pos, .number)) |token| blk: {
            try validateGeneratedSimpleOrderExpression(tokens, generated_expression);
            const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
            break :blk try expr_projection.selectOutputOrderByOrdinalAlloc(alloc, options.schema, select, ordinal);
        } else if (try expr_projection.parseSelectOutputOrderByNameMaybeAlloc(alloc, tokens, pos, options.schema, select)) |named_order| blk: {
            const order_candidate = named_order;
            var order_candidate_transferred = false;
            errdefer if (!order_candidate_transferred) {
                if (order_candidate.field.len > 0) alloc.free(order_candidate.field);
                if (order_candidate.expression) |expression| freeExpression(alloc, expression);
                if (order_candidate.collation) |collation| alloc.free(collation);
            };
            try validateGeneratedSimpleOrderExpression(tokens, generated_expression);
            order_candidate_transferred = true;
            break :blk order_candidate;
        } else try parseOrderExpressionAlloc(
            alloc,
            tokens,
            pos,
            options.schema,
            options.function_bindings,
            options.field_expression_qualifiers,
            options.returning_expression_qualifiers,
            options.defer_row_expression_field_validation,
            options.type_context,
            order_expression_hooks,
        );
        var order_transferred = false;
        errdefer if (!order_transferred) {
            if (order.field.len > 0) alloc.free(order.field);
            if (order.expression) |expression| freeExpression(alloc, expression);
            if (order.collation) |collation| alloc.free(collation);
        };
        const explicit_nulls_first = try parseOrderModifiers(tokens, pos, &order);
        try validateGeneratedExpressionItemEnd(generated_item, pos.*);
        try appendOrderWithNullPlacement(alloc, order_by, order, explicit_nulls_first);
        order_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

fn generatedWindowDefinitionPartitionTokens(options: WindowDefinitionParserOptions) ?generated_parser.GeneratedSqlTokenRange {
    if (options.generated_window_ast) |window| return window.partition_tokens;
    if (options.generated_over_expression_ast) |expression| return expression.over_partition_tokens;
    return null;
}

fn generatedWindowDefinitionPartitionItems(options: WindowDefinitionParserOptions) ?*const generated_parser.GeneratedSqlListAst {
    if (options.generated_window_ast) |window| return &window.partition_items;
    if (options.generated_over_expression_ast) |expression| return &expression.over_partition_items;
    return null;
}

fn generatedWindowDefinitionOrderTokens(options: WindowDefinitionParserOptions) ?generated_parser.GeneratedSqlTokenRange {
    if (options.generated_window_ast) |window| return window.order_tokens;
    if (options.generated_over_expression_ast) |expression| return expression.over_order_tokens;
    return null;
}

fn generatedWindowDefinitionOrderItems(options: WindowDefinitionParserOptions) ?*const generated_parser.GeneratedSqlListAst {
    if (options.generated_window_ast) |window| return &window.order_items;
    if (options.generated_over_expression_ast) |expression| return &expression.over_order_items;
    return null;
}

fn generatedWindowDefinitionFrameTokens(options: WindowDefinitionParserOptions) ?generated_parser.GeneratedSqlTokenRange {
    if (options.generated_window_ast) |window| return window.frame_tokens;
    if (options.generated_over_expression_ast) |expression| return expression.over_frame_tokens;
    return null;
}

fn generatedWindowDefinitionFrameUnit(options: WindowDefinitionParserOptions) ?generated_parser.GeneratedSqlWindowFrameUnit {
    if (options.generated_window_ast) |window| return window.frame_unit;
    if (options.generated_over_expression_ast) |expression| return expression.over_frame_unit;
    return null;
}

fn generatedWindowDefinitionFrameStartBound(options: WindowDefinitionParserOptions) ?generated_parser.GeneratedSqlWindowFrameBound {
    if (options.generated_window_ast) |window| return window.frame_start_bound;
    if (options.generated_over_expression_ast) |expression| return expression.over_frame_start_bound;
    return null;
}

fn generatedWindowDefinitionFrameEndBound(options: WindowDefinitionParserOptions) ?generated_parser.GeneratedSqlWindowFrameBound {
    if (options.generated_window_ast) |window| return window.frame_end_bound;
    if (options.generated_over_expression_ast) |expression| return expression.over_frame_end_bound;
    return null;
}

fn generatedWindowDefinitionFrameStartExpressionTokens(options: WindowDefinitionParserOptions) ?generated_parser.GeneratedSqlTokenRange {
    if (options.generated_window_ast) |window| return window.frame_start_expression_tokens;
    if (options.generated_over_expression_ast) |expression| return expression.over_frame_start_expression_tokens;
    return null;
}

fn generatedWindowDefinitionFrameEndExpressionTokens(options: WindowDefinitionParserOptions) ?generated_parser.GeneratedSqlTokenRange {
    if (options.generated_window_ast) |window| return window.frame_end_expression_tokens;
    if (options.generated_over_expression_ast) |expression| return expression.over_frame_end_expression_tokens;
    return null;
}

fn validateGeneratedWindowDefinitionFrameLayout(
    tokens: []const Token,
    range: generated_parser.GeneratedSqlTokenRange,
    options: WindowDefinitionParserOptions,
) !void {
    if (options.generated_window_ast) |window| {
        return try validateGeneratedWindowFrameClauseLayout(
            tokens,
            range,
            window.frame_start_expression_kind,
            window.frame_start_expression_tokens,
            window.frame_start_expression,
            window.frame_end_expression_kind,
            window.frame_end_expression_tokens,
            window.frame_end_expression,
        );
    }
    const expression = options.generated_over_expression_ast orelse return error.UnsupportedSqlShape;
    return try validateGeneratedWindowFrameClauseLayout(
        tokens,
        range,
        expression.over_frame_start_expression_kind,
        expression.over_frame_start_expression_tokens,
        expression.over_frame_start_expression,
        expression.over_frame_end_expression_kind,
        expression.over_frame_end_expression_tokens,
        expression.over_frame_end_expression,
    );
}

fn generatedWindowFrameUnit(
    unit: generated_parser.GeneratedSqlWindowFrameUnit,
) db_mod.types.RelationalRowsWindowFrameUnit {
    return switch (unit) {
        .rows => .rows,
        .range => .range,
    };
}

fn generatedWindowFrameBound(
    bound: generated_parser.GeneratedSqlWindowFrameBound,
) db_mod.types.RelationalRowsWindowFrameBound {
    return switch (bound) {
        .unbounded_preceding => .unbounded_preceding,
        .unbounded_following => .unbounded_following,
        .current_row => .current_row,
        .offset_preceding => .offset_preceding,
        .offset_following => .offset_following,
    };
}

fn generatedWindowFrameBoundOffset(
    tokens: []const Token,
    bound: generated_parser.GeneratedSqlWindowFrameBound,
    expression_tokens: ?generated_parser.GeneratedSqlTokenRange,
    params: []const value_mod.SqlValue,
) !u32 {
    return switch (bound) {
        .offset_preceding, .offset_following => blk: {
            const range = expression_tokens orelse return error.UnsupportedSqlShape;
            if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
            var cursor = range.start;
            const offset = try value_mod.parseSqlU32Value(tokens, &cursor, params);
            if (cursor != range.end or offset == 0) return error.UnsupportedSqlShape;
            break :blk offset;
        },
        else => {
            if (expression_tokens != null) return error.UnsupportedSqlShape;
            return 0;
        },
    };
}

fn validateGeneratedWindowDefinitionFrameSemantics(
    tokens: []const Token,
    params: []const value_mod.SqlValue,
    options: WindowDefinitionParserOptions,
    parsed_frame: db_mod.types.RelationalRowsWindowFrame,
) !void {
    const unit = generatedWindowDefinitionFrameUnit(options) orelse return error.UnsupportedSqlShape;
    const start_bound = generatedWindowDefinitionFrameStartBound(options) orelse return error.UnsupportedSqlShape;
    const end_bound = generatedWindowDefinitionFrameEndBound(options) orelse return error.UnsupportedSqlShape;
    const start_offset = try generatedWindowFrameBoundOffset(tokens, start_bound, generatedWindowDefinitionFrameStartExpressionTokens(options), params);
    const end_offset = try generatedWindowFrameBoundOffset(tokens, end_bound, generatedWindowDefinitionFrameEndExpressionTokens(options), params);
    if (generatedWindowFrameUnit(unit) != parsed_frame.unit or
        generatedWindowFrameBound(start_bound) != parsed_frame.start or
        start_offset != parsed_frame.start_offset or
        generatedWindowFrameBound(end_bound) != parsed_frame.end or
        end_offset != parsed_frame.end_offset)
        return error.UnsupportedSqlShape;
}

pub fn parseWindowPartitionByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    partition_by: *std.ArrayListUnmanaged([]const u8),
    options: WindowDefinitionParserOptions,
) !void {
    while (true) {
        const item_start = pos.*;
        const generated_items = generatedWindowDefinitionPartitionItems(options);
        const generated_item = if (generated_items) |items|
            try generatedExpressionListItemAtStart(tokens, item_start, items)
        else
            null;
        if (generated_item == null and generated_items != null) return error.UnsupportedSqlShape;
        const generated_expression = if (generated_item) |item| item.expression else null;
        try validateGeneratedSimpleGroupExpression(tokens, generated_expression);
        const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(
            alloc,
            tokens,
            pos,
            options.schema,
            options.field_expression_qualifiers,
            options.returning_expression_qualifiers,
            options.defer_row_expression_field_validation,
        );
        defer alloc.free(parsed_field);
        const field = try binder.normalizeRowExpressionFieldAlloc(alloc, options.schema, parsed_field, options.field_expression_qualifiers, options.returning_expression_qualifiers, options.defer_row_expression_field_validation);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        if (binder.relationalColumnForField(options.schema, field, null) == null) return error.InvalidSqlCatalog;
        try validateGeneratedExpressionItemEnd(generated_item, pos.*);
        try partition_by.append(alloc, field);
        field_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
        if (parser.peekKeyword(tokens, pos.*, "order")) return error.UnsupportedSqlShape;
    }
}

pub fn parseWindowDefinitionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    options: WindowDefinitionParserOptions,
) !plan_mod.NamedWindowDefinition {
    var partition_by = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (partition_by.items) |field| alloc.free(field);
        partition_by.deinit(alloc);
    }
    if (parser.matchKeyword(tokens, pos, "partition")) {
        try parser.expectKeyword(tokens, pos, "by");
        const generated_partition_end = if (generatedWindowDefinitionPartitionTokens(options)) |range| blk: {
            if (range.start != pos.*) return error.UnsupportedSqlShape;
            const items = generatedWindowDefinitionPartitionItems(options) orelse return error.UnsupportedSqlShape;
            try validateGeneratedExpressionListForClause(tokens, range, items.*);
            break :blk range.end;
        } else null;
        try parseWindowPartitionByAlloc(
            alloc,
            tokens,
            pos,
            &partition_by,
            options,
        );
        if (generated_partition_end) |end| {
            if (pos.* != end) return error.UnsupportedSqlShape;
        }
    } else if (generatedWindowDefinitionPartitionTokens(options) != null) {
        return error.UnsupportedSqlShape;
    }

    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }
    if (parser.matchKeyword(tokens, pos, "order")) {
        try parser.expectKeyword(tokens, pos, "by");
        const generated_order_items, const generated_order_end = if (generatedWindowDefinitionOrderTokens(options)) |range| blk: {
            if (range.start != pos.*) return error.UnsupportedSqlShape;
            const items = generatedWindowDefinitionOrderItems(options) orelse return error.UnsupportedSqlShape;
            try validateGeneratedOrderListForClause(tokens, range, items.*);
            break :blk .{ items, range.end };
        } else .{ null, null };
        try parseOrderByAlloc(
            alloc,
            tokens,
            pos,
            &order_by,
            .{
                .schema = options.schema,
                .function_bindings = options.function_bindings,
                .field_expression_qualifiers = options.field_expression_qualifiers,
                .returning_expression_qualifiers = options.returning_expression_qualifiers,
                .defer_row_expression_field_validation = options.defer_row_expression_field_validation,
                .type_context = options.type_context,
                .order_expression_hooks = options.order_expression_hooks,
                .generated_order_items = generated_order_items,
            },
        );
        if (generated_order_end) |end| {
            if (pos.* != end) return error.UnsupportedSqlShape;
        }
        if (order_by.items.len == 0) return error.UnsupportedSqlShape;
    } else if (generatedWindowDefinitionOrderTokens(options) != null) {
        return error.UnsupportedSqlShape;
    }

    const frame_start = pos.*;
    const frame = try expr_window.parseOptionalFrame(tokens, pos, params);
    if (options.generated_window_ast != null or options.generated_over_expression_ast != null) {
        if (frame != null) {
            const range = generatedWindowDefinitionFrameTokens(options) orelse return error.UnsupportedSqlShape;
            if (range.start != frame_start or range.end != pos.*) return error.UnsupportedSqlShape;
            try validateGeneratedWindowDefinitionFrameLayout(tokens, range, options);
            try validateGeneratedWindowDefinitionFrameSemantics(tokens, params, options, frame.?);
        } else if (generatedWindowDefinitionFrameTokens(options) != null) {
            return error.UnsupportedSqlShape;
        }
    }
    if (frame != null and order_by.items.len == 0) return error.UnsupportedSqlShape;
    if (frame) |parsed_frame| try expr_window.validateFrameForOrder(options.schema, options.type_context, parsed_frame, order_by.items);

    const owned_partition_by = try partition_by.toOwnedSlice(alloc);
    var partition_transferred = false;
    errdefer if (!partition_transferred) strings.freeStringSlice(alloc, owned_partition_by);
    const owned_order_by = try order_by.toOwnedSlice(alloc);
    var order_transferred = false;
    errdefer if (!order_transferred) {
        freeOrderBy(alloc, owned_order_by);
        if (owned_order_by.len > 0) alloc.free(owned_order_by);
    };

    partition_transferred = true;
    order_transferred = true;
    return .{
        .partition_by = owned_partition_by,
        .order_by = owned_order_by,
        .frame = frame,
    };
}

pub fn parseNamedWindowSpecsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    end: usize,
    params: []const value_mod.SqlValue,
    window_definition_options: WindowDefinitionParserOptions,
) ![]const plan_mod.NamedWindowSpec {
    var specs = std.ArrayListUnmanaged(plan_mod.NamedWindowSpec).empty;
    errdefer {
        for (specs.items) |spec| plan_mod.freeNamedWindowSpec(alloc, spec);
        specs.deinit(alloc);
    }

    var generated_index: usize = 0;
    while (true) {
        var spec_options = window_definition_options;
        if (window_definition_options.generated_window_items.len != 0) {
            if (generated_index >= window_definition_options.generated_window_items.len) return error.UnsupportedSqlShape;
            const generated_window = &window_definition_options.generated_window_items[generated_index];
            if (generated_window.tokens.start != pos.*) return error.UnsupportedSqlShape;
            spec_options.generated_window_ast = generated_window;
            spec_options.generated_window_items = &.{};
        }
        const spec_start = pos.*;
        const spec = try parseNamedWindowSpecAlloc(
            alloc,
            tokens,
            pos,
            params,
            specs.items,
            spec_options,
        );
        if (spec_options.generated_window_ast) |generated_window| {
            if (generated_window.tokens.start != spec_start or generated_window.tokens.end != pos.*) return error.UnsupportedSqlShape;
        }
        var spec_transferred = false;
        errdefer if (!spec_transferred) plan_mod.freeNamedWindowSpec(alloc, spec);
        try specs.append(alloc, spec);
        spec_transferred = true;
        generated_index += 1;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
        if (pos.* >= end) return error.UnsupportedSqlShape;
    }
    if (window_definition_options.generated_window_items.len != 0 and generated_index != window_definition_options.generated_window_items.len) return error.UnsupportedSqlShape;
    if (pos.* != end) return error.UnsupportedSqlShape;
    return try specs.toOwnedSlice(alloc);
}

pub fn parseTopLevelNamedWindowSpecsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: usize,
    params: []const value_mod.SqlValue,
    window_definition_options: WindowDefinitionParserOptions,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) ![]const plan_mod.NamedWindowSpec {
    const start = topLevelWindowClauseStart(tokens, pos) orelse return &.{};
    const end = topLevelWindowClauseEnd(tokens, start + 1);
    var window_pos: usize = start + 1;
    var generated_options = window_definition_options;
    if (generated_read_ast) |read| {
        const generated_end = try generatedWindowClauseEnd(tokens, start, window_pos, read);
        if (generated_end == null or generated_end.? != end) return error.UnsupportedSqlShape;
        generated_options.generated_window_items = read.window_items;
    }
    return try parseNamedWindowSpecsAlloc(
        alloc,
        tokens,
        &window_pos,
        end,
        params,
        generated_options,
    );
}

pub fn parseNamedWindowSpecAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    existing: []const plan_mod.NamedWindowSpec,
    window_definition_options: WindowDefinitionParserOptions,
) !plan_mod.NamedWindowSpec {
    const spec_start = pos.*;
    if (window_definition_options.generated_window_ast) |window| {
        if (window.tokens.start != spec_start or window.name_tokens.start != spec_start) return error.UnsupportedSqlShape;
    }
    const name = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
    if (window_definition_options.generated_window_ast) |window| {
        if (window.name_tokens.end != pos.*) return error.UnsupportedSqlShape;
    }
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(name);
    for (existing) |spec| {
        if (std.ascii.eqlIgnoreCase(spec.name, name)) return error.UnsupportedSqlShape;
    }

    try parser.expectKeyword(tokens, pos, "as");
    try parser.expectToken(tokens, pos, .lparen);
    if (window_definition_options.generated_window_ast) |window| {
        if (window.definition_tokens.start != pos.*) return error.UnsupportedSqlShape;
    }
    const definition = try parseWindowDefinitionAlloc(
        alloc,
        tokens,
        pos,
        params,
        window_definition_options,
    );
    var definition_transferred = false;
    errdefer if (!definition_transferred) plan_mod.freeNamedWindowDefinition(alloc, definition);
    if (window_definition_options.generated_window_ast) |window| {
        if (window.definition_tokens.end != pos.*) return error.UnsupportedSqlShape;
    }
    try parser.expectToken(tokens, pos, .rparen);
    if (window_definition_options.generated_window_ast) |window| {
        if (window.tokens.end != pos.*) return error.UnsupportedSqlShape;
    }

    name_transferred = true;
    definition_transferred = true;
    return .{
        .name = name,
        .partition_by = definition.partition_by,
        .order_by = definition.order_by,
        .frame = definition.frame,
    };
}

pub fn parseWindowDefinitionReferenceAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    named_window_specs: []const plan_mod.NamedWindowSpec,
    window_definition_options: WindowDefinitionParserOptions,
) !plan_mod.NamedWindowDefinition {
    if (parser.matchToken(tokens, pos, .lparen) != null) {
        const definition_start = pos.*;
        if (window_definition_options.generated_over_expression_ast) |expression| {
            if (expression.over_name_tokens != null) return error.UnsupportedSqlShape;
            if (expression.over_definition_tokens) |range| {
                if (range.start != definition_start) return error.UnsupportedSqlShape;
            } else if (expression.over_partition_tokens != null or expression.over_order_tokens != null or expression.over_frame_tokens != null) {
                return error.UnsupportedSqlShape;
            }
        }
        const definition = try parseWindowDefinitionAlloc(
            alloc,
            tokens,
            pos,
            params,
            window_definition_options,
        );
        errdefer plan_mod.freeNamedWindowDefinition(alloc, definition);
        if (window_definition_options.generated_over_expression_ast) |expression| {
            if (expression.over_definition_tokens) |range| {
                if (range.end != pos.*) return error.UnsupportedSqlShape;
            } else if (pos.* != definition_start) {
                return error.UnsupportedSqlShape;
            }
        }
        try parser.expectToken(tokens, pos, .rparen);
        return definition;
    }

    const name_start = pos.*;
    const name = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
    if (window_definition_options.generated_over_expression_ast) |expression| {
        const range = expression.over_name_tokens orelse return error.UnsupportedSqlShape;
        if (range.start != name_start or range.end != pos.*) return error.UnsupportedSqlShape;
    }
    defer alloc.free(name);
    for (named_window_specs) |spec| {
        if (std.ascii.eqlIgnoreCase(spec.name, name)) {
            return try plan_mod.cloneNamedWindowDefinitionAlloc(alloc, spec);
        }
    }
    return error.UnsupportedSqlShape;
}

pub fn topLevelWindowClauseStart(tokens: []const Token, pos: usize) ?usize {
    var depth: usize = 0;
    var i = pos;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => if (depth > 0) {
                depth -= 1;
            },
            .identifier => if (depth == 0 and token.matchesKeywordTag(.window)) return i,
            .semicolon => if (depth == 0) return null,
            else => {},
        }
    }
    return null;
}

pub fn topLevelWindowClauseEnd(tokens: []const Token, start: usize) usize {
    return parser.findTopLevelTailIndexToken(tokens, start, expr_token.sqlWindowTailClauseKeywordToken);
}

pub fn parseWindowSpecAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    type_context: expr_type.RowExpressionTypeContext,
    named_window_specs: []const plan_mod.NamedWindowSpec,
    window_definition_options: WindowDefinitionParserOptions,
    options: WindowSpecParserOptions,
) !db_mod.types.RelationalRowsWindowSpec {
    const function_start = pos.*;
    const generated_function = if (options.generated_expression_ast) |expression| blk: {
        const function = try generatedWindowFunctionForExpression(tokens, expression) orelse return error.UnsupportedSqlShape;
        const expression_tokens = expression.tokens orelse return error.UnsupportedSqlShape;
        if (expression_tokens.start != function_start) return error.UnsupportedSqlShape;
        break :blk function;
    } else null;
    const parsed_function = try expr_window.parseFunction(tokens, pos);
    const function = if (generated_function) |function| blk: {
        if (function != parsed_function) return error.UnsupportedSqlShape;
        break :blk function;
    } else parsed_function;
    try parser.expectToken(tokens, pos, .lparen);
    const argument_start = pos.*;
    const value_expression: ?db_mod.types.RelationalRowsExpression = switch (function) {
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile => null,
        .lag, .lead, .first_value, .last_value, .nth_value => try expr_row_parse.parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks),
        .count => if (parser.matchToken(tokens, pos, .star) != null) null else try expr_row_parse.parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks),
        .sum, .avg, .min, .max => try expr_row_parse.parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks),
        .bool_or, .bool_and => try expr_row_parse.parseBooleanRowExpressionAlloc(alloc, tokens, pos, type_context, options.boolean_hooks),
    };
    var value_expression_transferred = false;
    errdefer if (!value_expression_transferred) if (value_expression) |expression| freeExpression(alloc, expression);
    if (value_expression) |expression| {
        switch (function) {
            .sum, .avg => try type_context.validateNumericRowExpression(expression),
            .min, .max => try expr_type.validateAggregateMinMaxRowExpression(type_context, expression),
            .bool_or, .bool_and => try type_context.validateBooleanRowExpression(expression),
            else => {},
        }
    }

    const offset: u32 = switch (function) {
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .first_value, .last_value, .count, .sum, .avg, .min, .max, .bool_or, .bool_and => 1,
        .ntile => blk: {
            const parsed_offset = try value_mod.parseSqlU32Value(tokens, pos, params);
            if (parsed_offset == 0) return error.UnsupportedSqlShape;
            break :blk parsed_offset;
        },
        .nth_value => blk: {
            if (parser.matchToken(tokens, pos, .comma) == null) return error.UnsupportedSqlShape;
            const parsed_offset = try value_mod.parseSqlU32Value(tokens, pos, params);
            if (parsed_offset == 0) return error.UnsupportedSqlShape;
            break :blk parsed_offset;
        },
        .lag, .lead => if (parser.matchToken(tokens, pos, .comma) != null) blk: {
            const parsed_offset = try value_mod.parseSqlU32Value(tokens, pos, params);
            if (parsed_offset == 0) return error.UnsupportedSqlShape;
            break :blk parsed_offset;
        } else 1,
    };

    const default_json: []const u8 = switch (function) {
        .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile, .first_value, .last_value, .nth_value, .count, .sum, .avg, .min, .max, .bool_or, .bool_and => &.{},
        .lag, .lead => if (parser.matchToken(tokens, pos, .comma) != null)
            try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params)
        else
            &.{},
    };
    var default_transferred = false;
    errdefer if (!default_transferred) if (default_json.len > 0) alloc.free(default_json);
    const argument_end = pos.*;
    try parser.expectToken(tokens, pos, .rparen);
    try validateGeneratedWindowFunctionArgumentPayloads(
        tokens,
        function,
        function_start,
        argument_start,
        argument_end,
        options.generated_expression_ast,
    );
    const generated_filter_expression: ?*const generated_parser.GeneratedSqlExpressionAst = if (parser.peekKeyword(tokens, pos.*, "filter")) blk: {
        const generated_expression = options.generated_expression_ast orelse break :blk null;
        break :blk generated_expression.filter_expression;
    } else null;
    const filter = try parseAggregateFilterAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
        params,
        type_context,
        options.expression_alternatives,
        options.expression_conditions,
        options.fixed_binary,
        options.realtime_ns,
        generated_filter_expression,
    );
    var filter_transferred = false;
    errdefer if (!filter_transferred) expr_aggregate.freeFilter(alloc, filter);
    if (!expr_window.functionSupportsFilter(function) and !expr_aggregate.filterIsEmpty(filter)) return error.UnsupportedSqlShape;
    try parser.expectKeyword(tokens, pos, "over");
    const over_start = pos.* - 1;
    var generated_window_definition_options = window_definition_options;
    generated_window_definition_options.generated_over_expression_ast = options.generated_expression_ast;

    const definition = try parseWindowDefinitionReferenceAlloc(
        alloc,
        tokens,
        pos,
        params,
        named_window_specs,
        generated_window_definition_options,
    );
    var definition_transferred = false;
    errdefer if (!definition_transferred) plan_mod.freeNamedWindowDefinition(alloc, definition);
    if (definition.order_by.len == 0 and expr_window.functionRequiresOrder(function)) return error.UnsupportedSqlShape;
    try validateGeneratedWindowOverClauseForSpec(tokens, function, over_start, pos.*, options.generated_expression_ast);

    const output = try grammar.parseProjectionOutputOwnedAlloc(alloc, tokens, pos, expr_window.functionName(function));
    var output_transferred = false;
    errdefer if (!output_transferred) alloc.free(output);

    output_transferred = true;
    definition_transferred = true;
    value_expression_transferred = true;
    default_transferred = true;
    filter_transferred = true;
    return .{
        .output = output,
        .function = function,
        .partition_by = definition.partition_by,
        .order_by = definition.order_by,
        .value_expression = value_expression,
        .offset = offset,
        .default_json = default_json,
        .frame = definition.frame,
        .filter_predicates = filter.predicates,
        .filter_array_any = filter.array_any,
        .filter_array_contains = filter.array_contains,
        .filter_array_eq = filter.array_eq,
        .filter_in_predicates = filter.in_predicates,
        .filter_json_contains = filter.json_contains,
        .filter_json_path_eq = filter.json_path_eq,
        .filter_json_path_exists = filter.json_path_exists,
        .filter_text_patterns = filter.text_patterns,
        .filter_expressions = filter.expressions,
        .filter_expression_array_contains = filter.expression_array_contains,
        .filter_any = filter.any_groups,
        .filter_not = filter.not_groups,
    };
}

pub fn joinProjectionOutputIsUnique(select: []const db_mod.types.RelationalRowsJoinProjection, field: []const u8) bool {
    var matches: usize = 0;
    for (select) |projection| {
        if (std.mem.eql(u8, projection.output, field)) matches += 1;
    }
    return matches == 1;
}

pub fn joinOutputFieldByOrdinalAlloc(
    alloc: std.mem.Allocator,
    select: []const db_mod.types.RelationalRowsJoinProjection,
    ordinal: u32,
) ![]const u8 {
    if (ordinal == 0) return error.UnsupportedSqlShape;
    const index: usize = @intCast(ordinal - 1);
    if (index >= select.len) return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, select[index].output);
}

pub fn joinOutputColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    select: []const db_mod.types.RelationalRowsJoinProjection,
) ![]runtime_schema.RelationalColumn {
    if (select.len == 0) return &.{};
    const out = try alloc.alloc(runtime_schema.RelationalColumn, select.len);
    var initialized: usize = 0;
    errdefer {
        ddl_plan.clearDdlRelationalColumns(alloc, out[0..initialized]);
        alloc.free(out);
    }
    for (select) |projection| {
        if (expr_projection.outputColumnExists(out[0..initialized], projection.output)) return error.UnsupportedSqlShape;
        const column = binder.relationalColumnForField(schema, projection.field, null) orelse return error.InvalidSqlCatalog;
        out[initialized] = try expr_projection.projectedSourceColumnAlloc(alloc, projection.output, .{
            .name = column.name,
            .path = column.path,
            .field_type = column.field_type,
            .array_item_type = column.array_item_type,
            .nullable = true,
            .collation = column.collation,
        });
        initialized += 1;
    }
    return out;
}

pub fn identifierContainsQualifier(identifier: []const u8) bool {
    const dot = std.mem.indexOfScalar(u8, identifier, '.') orelse return false;
    return dot > 0 and dot + 1 < identifier.len;
}

pub fn tailMentionsAnyQualifierBeforeClose(
    tokens: []const Token,
    pos: usize,
    qualifiers: []const []const u8,
) bool {
    var depth: usize = 0;
    var i = pos;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
            },
            .identifier => {
                const dot = std.mem.indexOfScalar(u8, token.text, '.') orelse continue;
                const qualifier = token.text[0..dot];
                for (qualifiers) |candidate| {
                    if (std.mem.eql(u8, qualifier, candidate)) return true;
                }
            },
            else => {},
        }
    }
    return false;
}

const DirectGraphTableFunctionSource = struct {
    cte: db_mod.types.RelationalRowsCte,
    table_ref: plan_mod.TableAlias,
    function_start: usize,
    source_end: usize,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        var cte = self.cte;
        cte.deinit(alloc);
        plan_mod.freeTableAlias(alloc, self.table_ref);
        self.* = undefined;
    }
};

const GeneratedGraphTableFunctionSource = struct {
    antfly_item: generated_parser.GeneratedSqlAntflyTableFunctionAst,
    graph_item: generated_parser.GeneratedSqlGraphTableFunctionAst,
};

fn cloneTableAliasAlloc(alloc: std.mem.Allocator, value: plan_mod.TableAlias) !plan_mod.TableAlias {
    const name = try alloc.dupe(u8, value.name);
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(name);
    const alias = try alloc.dupe(u8, value.alias);
    var alias_transferred = false;
    errdefer if (!alias_transferred) alloc.free(alias);
    name_transferred = true;
    alias_transferred = true;
    return .{ .name = name, .alias = alias };
}

fn generatedGraphTableFunctionSourceAt(
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    function_start: usize,
) ?GeneratedGraphTableFunctionSource {
    const read = generated_read_ast orelse return null;
    for (read.source_graph_function_items) |graph_item| {
        if (graph_item.tokens.start != function_start) continue;
        for (read.source_antfly_function_items) |antfly_item| {
            if (antfly_item.tokens.start == graph_item.tokens.start and
                antfly_item.tokens.end == graph_item.tokens.end)
            {
                return .{
                    .antfly_item = antfly_item,
                    .graph_item = graph_item,
                };
            }
        }
    }
    return null;
}

fn parseGraphTableFunctionSourceAtAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    function_start: usize,
    default_alias: []const u8,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !?DirectGraphTableFunctionSource {
    if (function_start + 1 >= tokens.len) return null;
    if (tokens[function_start].kind != .identifier or tokens[function_start + 1].kind != .lparen) return null;
    const function = query_function.antflyQueryFunctionFromSqlToken(tokens[function_start]) orelse return null;
    switch (function) {
        .graph_traverse, .graph_neighbors, .graph_shortest_path, .graph_k_shortest_paths, .graph_match => {},
        .graph_metric, .graph_metric_rerank => {},
        else => return null,
    }
    const close_index = parser.findMatchingRParenIndex(tokens, function_start + 1) orelse return error.UnsupportedSqlShape;
    const function_end = close_index + 1;

    var alias_pos = function_end;
    const explicit_alias = parser.matchKeywordTag(tokens, &alias_pos, .as);
    const alias_source = if (explicit_alias) blk: {
        if (alias_pos >= tokens.len or tokens[alias_pos].kind != .identifier) return error.UnsupportedSqlShape;
        const alias = tokens[alias_pos].text;
        alias_pos += 1;
        break :blk alias;
    } else if (alias_pos < tokens.len and
        tokens[alias_pos].kind == .identifier and
        !plan_mod.selectSourceAliasTailKeyword(tokens[alias_pos]))
    blk: {
        const alias = tokens[alias_pos].text;
        alias_pos += 1;
        break :blk alias;
    } else default_alias;

    if (plan_mod.findCteByName(available_ctes, alias_source) != null) return error.UnsupportedSqlShape;

    const generated_source = generatedGraphTableFunctionSourceAt(generated_read_ast, function_start);
    if (generated_read_ast != null and generated_source == null) return error.UnsupportedSqlShape;

    const table_function = if (generated_source) |source|
        try query_function.lowerAntflyGraphTableFunctionGeneratedAstAlloc(alloc, tokens, source.antfly_item, source.graph_item)
    else table_function: {
        var wrapped = std.ArrayListUnmanaged(Token).empty;
        defer wrapped.deinit(alloc);
        try wrapped.append(alloc, .{ .kind = .identifier, .text = "select" });
        try wrapped.append(alloc, .{ .kind = .star, .text = "*" });
        try wrapped.append(alloc, .{ .kind = .identifier, .text = "from" });
        try wrapped.appendSlice(alloc, tokens[function_start..function_end]);
        break :table_function try query_function.lowerAntflyGraphTableFunctionTokensAlloc(alloc, wrapped.items);
    };
    var table_function_transferred = false;
    errdefer if (!table_function_transferred) {
        var owned = table_function;
        owned.deinit(alloc);
    };

    const cte_name = try alloc.dupe(u8, alias_source);
    var cte_name_transferred = false;
    errdefer if (!cte_name_transferred) alloc.free(cte_name);
    const table_name = try alloc.dupe(u8, alias_source);
    var table_name_transferred = false;
    errdefer if (!table_name_transferred) alloc.free(table_name);
    const table_alias = try alloc.dupe(u8, alias_source);
    var table_alias_transferred = false;
    errdefer if (!table_alias_transferred) alloc.free(table_alias);

    table_function_transferred = true;
    cte_name_transferred = true;
    table_name_transferred = true;
    table_alias_transferred = true;
    return .{
        .cte = .{
            .name = cte_name,
            .table_function = table_function,
        },
        .table_ref = .{
            .name = table_name,
            .alias = table_alias,
        },
        .function_start = function_start,
        .source_end = alias_pos,
    };
}

fn parseDirectGraphTableFunctionSourceAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    select_body_pos: usize,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !?DirectGraphTableFunctionSource {
    const from_index = parser.findTopLevelKeywordFromIndex(tokens, select_body_pos, "from") orelse return null;
    return try parseGraphTableFunctionSourceAtAlloc(alloc, tokens, from_index + 1, "__antfly_graph_table_function", available_ctes, generated_read_ast);
}

pub fn parseSelectAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: SelectParserOptions,
) !plan_mod.LoweredSelect {
    if (options.generated_read_ast) |read| try validateGeneratedReadAstPayloads(tokens, read.*);
    try parser.expectKeyword(tokens, pos, "select");

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var current_context = initial_context;

    var direct_graph_source = try parseDirectGraphTableFunctionSourceAlloc(alloc, tokens, pos.*, options.available_ctes, options.generated_read_ast);
    var direct_graph_source_transferred = false;
    defer if (!direct_graph_source_transferred) {
        if (direct_graph_source) |*source| source.deinit(alloc);
    };

    const inferred_table_ref = if (direct_graph_source) |source|
        try cloneTableAliasAlloc(alloc, source.table_ref)
    else if (try inferGeneratedTableAliasFromReadSourceAlloc(alloc, tokens, pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.inferSelectSourceAliasAlloc(alloc, tokens, pos.*);
    defer if (inferred_table_ref) |value| plan_mod.freeTableAlias(alloc, value);
    var inferred_qualifiers: [2][]const u8 = undefined;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (inferred_table_ref) |value| {
        inferred_qualifiers = .{ value.name, value.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
        if (direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, value.name) != null) {
            const ctes = if (direct_graph_source) |*source| source_ctes: {
                const implicit_ctes = [_]db_mod.types.RelationalRowsCte{source.cte};
                break :source_ctes implicit_ctes[0..];
            } else options.available_ctes;
            planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, initial_context.schema, ctes);
            current_context.schema = relational_rows.rowsPlannedCteSchema(planned_ctes, value.name) orelse return error.UnsupportedSqlShape;
            current_context.defer_row_expression_field_validation = true;
        }
        options.context_hooks.set_context(options.context_hooks.ptr, current_context);
    }

    const generated_distinct = try generatedDistinctClauseEnd(tokens, pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary);
    const distinct_on = try parseOptionalDistinctOnAlloc(
        alloc,
        tokens,
        pos,
        options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
        options.row_expression_hooks,
        options.arithmetic_hooks,
        options.variadic_hooks,
    );
    errdefer freeExpressionSlice(alloc, distinct_on);
    if (generated_distinct) |distinct| {
        if (distinct.kind != .distinct_on or pos.* != distinct.end) return error.UnsupportedSqlShape;
    } else if (distinct_on.len > 0 and options.generated_read_ast != null) {
        return error.UnsupportedSqlShape;
    }
    _ = parser.matchKeyword(tokens, pos, "all");

    const generated_projection_end = try generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary);
    const select = try parseSelectListAlloc(
        alloc,
        tokens,
        pos,
        .{
            .params = options.params,
            .output_schema = current_context.schema,
            .select_item_schema = current_context.schema,
            .function_bindings = options.function_bindings,
            .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
            .field_expression_qualifiers = current_context.field_expression_qualifiers,
            .returning_expression_qualifiers = current_context.returning_expression_qualifiers,
            .defer_row_expression_field_validation = current_context.defer_row_expression_field_validation,
            .field_source = options.field_source,
            .select_item_options = options.select_item_options,
            .generated_read_ast = options.generated_read_ast,
            .allow_generated_projection_fallback = options.allow_select_set_result_tail_boundary,
        },
    );
    errdefer strings.freeStringSlice(alloc, select.fields);
    errdefer plan_mod.freeJsonExtract(alloc, select.json_extract);
    errdefer plan_mod.freeArrayLengthProjections(alloc, select.array_length);
    errdefer plan_mod.freeCoalesceProjections(alloc, select.coalesce);
    errdefer plan_mod.freeFieldAliasProjections(alloc, select.field_aliases);
    errdefer freeExpressionProjections(alloc, select.expressions);
    defer if (select.outputs.len > 0) alloc.free(select.outputs);
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }

    try parser.expectKeyword(tokens, pos, "from");
    const source_start = pos.*;
    const generated_source_end = try generatedSourceClauseEnd(tokens, source_start, options.generated_read_ast, options.allow_select_set_result_tail_boundary);
    const table_ref = if (direct_graph_source) |source| table_ref: {
        if (pos.* != source.function_start) return error.UnsupportedSqlShape;
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generatedTableAliasFromReadSourceAlloc(alloc, tokens, pos, options.generated_read_ast, options.allow_select_set_result_tail_boundary)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    errdefer alloc.free(table_ref.name);
    defer alloc.free(table_ref.alias);
    if (inferred_table_ref) |value| {
        if (!std.mem.eql(u8, table_ref.name, value.name) or !std.mem.eql(u8, table_ref.alias, value.alias)) return error.UnsupportedSqlShape;
    } else {
        inferred_qualifiers = .{ table_ref.name, table_ref.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
    }
    try validateGeneratedSingleSourceAliasForParsedTable(tokens, options.generated_read_ast, source_start, pos.*);
    if (generated_source_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const source_is_cte = direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, table_ref.name) != null;
    if (source_is_cte) current_context.defer_row_expression_field_validation = true;
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);
    const system_time_as_of = try parseOptionalSystemTimeAsOf(tokens, pos);
    try validateGeneratedSystemTimeForParsedSource(tokens, options.generated_read_ast, source_start, generated_source_end orelse pos.*, pos.*, system_time_as_of);

    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var json_path_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate).empty;
    errdefer {
        freeJsonPathEq(alloc, json_path_eq.items);
        json_path_eq.deinit(alloc);
    }
    var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, json_contains.items);
        json_contains.deinit(alloc);
    }
    var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, json_path_exists.items);
        json_path_exists.deinit(alloc);
    }
    var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
    errdefer {
        freeArrayAny(alloc, array_any.items);
        array_any.deinit(alloc);
    }
    var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, array_contains.items);
        array_contains.deinit(alloc);
    }
    var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, array_eq.items);
        array_eq.deinit(alloc);
    }
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, in_predicates.items);
        in_predicates.deinit(alloc);
    }
    var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, text_patterns.items);
        text_patterns.deinit(alloc);
    }
    var or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, or_predicates.items);
        or_predicates.deinit(alloc);
    }
    var not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, not_predicates.items);
        not_predicates.deinit(alloc);
    }
    var access_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_or_predicates.items);
        access_or_predicates.deinit(alloc);
    }
    var access_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_not_predicates.items);
        access_not_predicates.deinit(alloc);
    }
    var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, expression_predicates.items);
        expression_predicates.deinit(alloc);
    }
    var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
        expression_or_predicates.deinit(alloc);
    }
    var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
        expression_not_predicates.deinit(alloc);
    }
    var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, expression_array_contains.items);
        expression_array_contains.deinit(alloc);
    }
    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }

    var row_claim: ?db_mod.types.RowClaimRequest = null;
    var limit: ?u32 = null;
    var offset: u32 = 0;

    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary);
            const generated_where_expression = try requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary, generated_where_end);
            const where_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try parseWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                where_context.schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                where_context.field_expression_qualifiers,
                where_context.returning_expression_qualifiers,
                where_context.defer_row_expression_field_validation,
                &predicates,
                &json_contains,
                &json_path_eq,
                &json_path_exists,
                &array_any,
                &array_contains,
                &array_eq,
                &in_predicates,
                &text_patterns,
                &or_predicates,
                &not_predicates,
                &access_or_predicates,
                &access_not_predicates,
                &expression_predicates,
                &expression_or_predicates,
                &expression_not_predicates,
                &expression_array_contains,
                options.realtime_ns,
                options.fixed_binary_hooks,
                options.bare_boolean_hooks,
                options.expression_alternatives_hooks,
                options.expression_condition_hooks,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (options.allow_select_set_result_tail_boundary and grammar.nextIsSelectSetResultTailKeyword(tokens, pos.*)) {
            break;
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            const order_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try parseSelectOutputOrderByAlloc(
                alloc,
                tokens,
                pos,
                &order_by,
                select,
                .{
                    .schema = order_context.schema,
                    .function_bindings = options.function_bindings,
                    .field_expression_qualifiers = order_context.field_expression_qualifiers,
                    .returning_expression_qualifiers = order_context.returning_expression_qualifiers,
                    .defer_row_expression_field_validation = order_context.defer_row_expression_field_validation,
                    .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                    .order_expression_hooks = options.order_expression_hooks,
                    .generated_read_ast = options.generated_read_ast,
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
            if (distinct_on.len > 0) try validateDistinctOnOrder(distinct_on, order_by.items);
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "for")) {
            const allowed_targets = [_][]const u8{ table_ref.name, table_ref.alias };
            const keyword_index = pos.* - 1;
            row_claim = if (try row_claim_mod.parseGeneratedReadRowClaimForClauseAlloc(alloc, tokens, keyword_index, pos, &allowed_targets, options.generated_read_ast)) |generated_claim|
                generated_claim
            else if (options.generated_read_ast != null)
                return error.UnsupportedSqlShape
            else
                row_claim_mod.sqlRowClaimForClause(try grammar.parseCheckedForRowClaimClauseAlloc(alloc, tokens, pos, &allowed_targets));
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else if (options.allow_select_set_boundary and grammar.nextIsSelectSetOperationKeyword(tokens, pos.*)) {
            break;
        } else if (nextIsUnsupportedQueryKeyword(tokens, pos.*)) {
            return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }
    if (distinct_on.len > 0) {
        if (row_claim != null) return error.UnsupportedSqlShape;
        if (order_by.items.len == 0) return error.UnsupportedSqlShape;
        try validateDistinctOnOrder(distinct_on, order_by.items);
    }
    const ctes = if (direct_graph_source) |*source| ctes: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsCte, 1);
        out[0] = source.cte;
        source.cte = .{ .name = "" };
        direct_graph_source_transferred = true;
        plan_mod.freeTableAlias(alloc, source.table_ref);
        source.table_ref = .{ .name = "", .alias = "" };
        break :ctes out;
    } else &.{};

    return .{
        .table_name = table_ref.name,
        .ctes = ctes,
        .query = .{
            .predicates = try predicates.toOwnedSlice(alloc),
            .array_any = try array_any.toOwnedSlice(alloc),
            .array_contains = try array_contains.toOwnedSlice(alloc),
            .array_eq = try array_eq.toOwnedSlice(alloc),
            .in_predicates = try in_predicates.toOwnedSlice(alloc),
            .json_contains = try json_contains.toOwnedSlice(alloc),
            .json_path_eq = try json_path_eq.toOwnedSlice(alloc),
            .json_path_exists = try json_path_exists.toOwnedSlice(alloc),
            .text_patterns = try text_patterns.toOwnedSlice(alloc),
            .or_predicates = try or_predicates.toOwnedSlice(alloc),
            .not_predicates = try not_predicates.toOwnedSlice(alloc),
            .access_or_predicates = try access_or_predicates.toOwnedSlice(alloc),
            .access_not_predicates = try access_not_predicates.toOwnedSlice(alloc),
            .expression_predicates = try expression_predicates.toOwnedSlice(alloc),
            .expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc),
            .expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc),
            .expression_array_contains = try expression_array_contains.toOwnedSlice(alloc),
            .select = select.fields,
            .json_extract = select.json_extract,
            .array_length = select.array_length,
            .coalesce = select.coalesce,
            .field_aliases = select.field_aliases,
            .expressions = select.expressions,
            .select_all = select.select_all,
            .distinct_on_expressions = distinct_on,
            .order_by = try order_by.toOwnedSlice(alloc),
            .row_claim = row_claim,
            .limit = limit,
            .offset = offset,
        },
        .select_outputs = try plan_mod.cloneSelectOutputsAlloc(alloc, select.outputs),
        .system_time_as_of_sequence = system_time_as_of.sequence,
        .system_time_as_of_timestamp_ns = system_time_as_of.timestamp_ns,
    };
}

pub fn parseAggregateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: AggregateParserOptions,
) !plan_mod.LoweredAggregate {
    if (options.generated_read_ast) |read| try validateGeneratedReadAstPayloads(tokens, read.*);
    try parser.expectKeyword(tokens, pos, "select");

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var current_context = initial_context;

    var direct_graph_source = try parseDirectGraphTableFunctionSourceAlloc(alloc, tokens, pos.*, options.available_ctes, options.generated_read_ast);
    var direct_graph_source_transferred = false;
    defer if (!direct_graph_source_transferred) {
        if (direct_graph_source) |*source| source.deinit(alloc);
    };

    const inferred_table_ref = if (direct_graph_source) |source|
        try cloneTableAliasAlloc(alloc, source.table_ref)
    else if (try inferGeneratedTableAliasFromReadSourceAlloc(alloc, tokens, pos.*, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.inferSelectSourceAliasAlloc(alloc, tokens, pos.*);
    defer if (inferred_table_ref) |value| plan_mod.freeTableAlias(alloc, value);
    var inferred_qualifiers: [2][]const u8 = undefined;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (inferred_table_ref) |value| {
        inferred_qualifiers = .{ value.name, value.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
        if (direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, value.name) != null) {
            const ctes = if (direct_graph_source) |*source| source_ctes: {
                const implicit_ctes = [_]db_mod.types.RelationalRowsCte{source.cte};
                break :source_ctes implicit_ctes[0..];
            } else options.available_ctes;
            planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, initial_context.schema, ctes);
            current_context.schema = relational_rows.rowsPlannedCteSchema(planned_ctes, value.name) orelse return error.UnsupportedSqlShape;
            current_context.defer_row_expression_field_validation = true;
        }
        options.context_hooks.set_context(options.context_hooks.ptr, current_context);
    }

    const generated_distinct = try generatedDistinctClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const select_distinct = parser.matchKeyword(tokens, pos, "distinct");
    if (select_distinct and parser.peekKeyword(tokens, pos.*, "on")) return error.UnsupportedSqlShape;
    if (generated_distinct) |distinct| {
        if (distinct.kind != .plain or pos.* != distinct.end) return error.UnsupportedSqlShape;
    } else if (select_distinct and options.generated_read_ast != null) {
        return error.UnsupportedSqlShape;
    }

    const select_context = options.context_hooks.get_context(options.context_hooks.ptr);
    const generated_projection_end = try generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const select = try parseAggregateSelectListAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        select_context.schema,
        options.function_bindings,
        options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
        select_context.field_expression_qualifiers,
        select_context.returning_expression_qualifiers,
        select_context.defer_row_expression_field_validation,
        options.field_source,
        options.generated_read_ast,
        options.aggregate_spec_options,
        options.select_item_options,
    );
    var select_group_expressions_transferred = false;
    defer {
        strings.freeStringSlice(alloc, select.group_fields);
        if (!select_group_expressions_transferred) freeExpressionProjections(alloc, select.group_expressions);
        if (select.outputs.len > 0) alloc.free(select.outputs);
    }
    errdefer {
        plan_mod.freeAggregateSpecs(alloc, select.aggregations);
        if (select.aggregations.len > 0) alloc.free(select.aggregations);
    }
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const distinct_group_only = select_distinct and select.aggregations.len == 0;
    if (distinct_group_only) {
        if (select.group_fields.len == 0 and select.group_expressions.len == 0) return error.UnsupportedSqlShape;
    } else if (select.aggregations.len == 0) return error.UnsupportedSqlShape;

    try parser.expectKeyword(tokens, pos, "from");
    const source_start = pos.*;
    const generated_source_end = try generatedSourceClauseEnd(tokens, source_start, options.generated_read_ast, false);
    const table_ref = if (direct_graph_source) |source| table_ref: {
        if (pos.* != source.function_start) return error.UnsupportedSqlShape;
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generatedTableAliasFromReadSourceAlloc(alloc, tokens, pos, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    errdefer alloc.free(table_ref.name);
    defer alloc.free(table_ref.alias);
    if (inferred_table_ref) |value| {
        if (!std.mem.eql(u8, table_ref.name, value.name) or !std.mem.eql(u8, table_ref.alias, value.alias)) return error.UnsupportedSqlShape;
    } else {
        inferred_qualifiers = .{ table_ref.name, table_ref.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
    }
    try validateGeneratedSingleSourceAliasForParsedTable(tokens, options.generated_read_ast, source_start, pos.*);
    if (generated_source_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const source_is_cte = direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, table_ref.name) != null;
    if (source_is_cte) current_context.defer_row_expression_field_validation = true;
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var json_path_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate).empty;
    errdefer {
        freeJsonPathEq(alloc, json_path_eq.items);
        json_path_eq.deinit(alloc);
    }
    var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, json_contains.items);
        json_contains.deinit(alloc);
    }
    var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, json_path_exists.items);
        json_path_exists.deinit(alloc);
    }
    var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
    errdefer {
        freeArrayAny(alloc, array_any.items);
        array_any.deinit(alloc);
    }
    var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, array_contains.items);
        array_contains.deinit(alloc);
    }
    var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, array_eq.items);
        array_eq.deinit(alloc);
    }
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, in_predicates.items);
        in_predicates.deinit(alloc);
    }
    var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, text_patterns.items);
        text_patterns.deinit(alloc);
    }
    var or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, or_predicates.items);
        or_predicates.deinit(alloc);
    }
    var not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, not_predicates.items);
        not_predicates.deinit(alloc);
    }
    var access_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_or_predicates.items);
        access_or_predicates.deinit(alloc);
    }
    var access_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_not_predicates.items);
        access_not_predicates.deinit(alloc);
    }
    var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, expression_predicates.items);
        expression_predicates.deinit(alloc);
    }
    var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
        expression_or_predicates.deinit(alloc);
    }
    var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
        expression_not_predicates.deinit(alloc);
    }
    var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, expression_array_contains.items);
        expression_array_contains.deinit(alloc);
    }
    var group_by = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (group_by.items) |field| alloc.free(field);
        group_by.deinit(alloc);
    }
    var group_expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
    defer {
        for (group_expressions.items) |projection| freeExpressionProjection(alloc, projection);
        group_expressions.deinit(alloc);
    }
    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }
    var having_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, having_predicates.items);
        having_predicates.deinit(alloc);
    }
    var having_expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, having_expressions.items);
        having_expressions.deinit(alloc);
    }
    var having_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, having_any.items);
        having_any.deinit(alloc);
    }
    var having_not = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, having_not.items);
        having_not.deinit(alloc);
    }

    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            const where_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try parseWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                where_context.schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                where_context.field_expression_qualifiers,
                where_context.returning_expression_qualifiers,
                where_context.defer_row_expression_field_validation,
                &predicates,
                &json_contains,
                &json_path_eq,
                &json_path_exists,
                &array_any,
                &array_contains,
                &array_eq,
                &in_predicates,
                &text_patterns,
                &or_predicates,
                &not_predicates,
                &access_or_predicates,
                &access_not_predicates,
                &expression_predicates,
                &expression_or_predicates,
                &expression_not_predicates,
                &expression_array_contains,
                options.realtime_ns,
                options.fixed_binary_hooks,
                options.bare_boolean_hooks,
                options.expression_alternatives_hooks,
                options.expression_condition_hooks,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "group")) {
            if (distinct_group_only) return error.UnsupportedSqlShape;
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_group_end = try generatedGroupClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            const group_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try parseAggregateGroupByAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                group_context.schema,
                options.function_bindings,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                group_context.field_expression_qualifiers,
                group_context.returning_expression_qualifiers,
                group_context.defer_row_expression_field_validation,
                options.field_source,
                &group_by,
                &group_expressions,
                select,
                options.select_item_options,
                options.generated_read_ast,
            );
            if (generated_group_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "having")) {
            if (distinct_group_only) return error.UnsupportedSqlShape;
            const keyword_index = pos.* - 1;
            const generated_having_end = try generatedHavingClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            const generated_having_expression: ?*const generated_parser.GeneratedSqlExpressionAst = if (generated_having_end != null) blk: {
                const generated_read = options.generated_read_ast orelse return error.UnsupportedSqlShape;
                break :blk &generated_read.having_expression;
            } else null;
            try parseAggregateHavingAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                options.context_hooks.get_context(options.context_hooks.ptr).schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                &having_predicates,
                &having_expressions,
                &having_any,
                &having_not,
                select.group_fields,
                select.group_expressions,
                select.aggregations,
                options.output_field_options,
                options.output_field_condition_options,
                .{
                    .context_hooks = options.context_hooks,
                    .case_expression_hooks = options.case_expression_hooks,
                },
                .{
                    .context_hooks = options.context_hooks,
                    .bare_boolean_hooks = options.bare_boolean_hooks,
                },
                generated_having_expression,
            );
            if (generated_having_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try parseAggregateOrderByAlloc(
                alloc,
                tokens,
                pos,
                options.context_hooks.get_context(options.context_hooks.ptr).schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                &order_by,
                select.group_fields,
                select.group_expressions,
                select.aggregations,
                options.output_field_options,
                blk: {
                    var order_options = options.output_order_expression_options;
                    order_options.generated_read_ast = options.generated_read_ast;
                    break :blk order_options;
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else if (nextIsUnsupportedQueryKeyword(tokens, pos.*)) {
            return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    if (distinct_group_only) {
        if (group_by.items.len != 0 or having_predicates.items.len != 0 or having_expressions.items.len != 0 or having_any.items.len != 0 or having_not.items.len != 0) return error.UnsupportedSqlShape;
    } else {
        try expr_aggregate.validateGroupBy(select.group_fields, select.group_expressions, group_by.items, group_expressions.items);
    }

    const owned_group_by = if (distinct_group_only)
        try strings.cloneStringSlice(alloc, select.group_fields)
    else
        try group_by.toOwnedSlice(alloc);
    var group_by_transferred = false;
    errdefer if (!group_by_transferred) strings.freeStringSlice(alloc, owned_group_by);
    const owned_group_expressions = select.group_expressions;

    const aggregate_request = db_mod.types.RelationalRowsAggregateRequest{
        .source = .{
            .predicates = try predicates.toOwnedSlice(alloc),
            .array_any = try array_any.toOwnedSlice(alloc),
            .array_contains = try array_contains.toOwnedSlice(alloc),
            .array_eq = try array_eq.toOwnedSlice(alloc),
            .in_predicates = try in_predicates.toOwnedSlice(alloc),
            .json_contains = try json_contains.toOwnedSlice(alloc),
            .json_path_eq = try json_path_eq.toOwnedSlice(alloc),
            .json_path_exists = try json_path_exists.toOwnedSlice(alloc),
            .text_patterns = try text_patterns.toOwnedSlice(alloc),
            .or_predicates = try or_predicates.toOwnedSlice(alloc),
            .not_predicates = try not_predicates.toOwnedSlice(alloc),
            .access_or_predicates = try access_or_predicates.toOwnedSlice(alloc),
            .access_not_predicates = try access_not_predicates.toOwnedSlice(alloc),
            .expression_predicates = try expression_predicates.toOwnedSlice(alloc),
            .expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc),
            .expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc),
            .expression_array_contains = try expression_array_contains.toOwnedSlice(alloc),
            .select_all = true,
        },
        .group_by = owned_group_by,
        .group_expressions = owned_group_expressions,
        .aggregations = select.aggregations,
        .having_predicates = try having_predicates.toOwnedSlice(alloc),
        .having_expressions = try having_expressions.toOwnedSlice(alloc),
        .having_any = try having_any.toOwnedSlice(alloc),
        .having_not = try having_not.toOwnedSlice(alloc),
        .order_by = try order_by.toOwnedSlice(alloc),
        .limit = limit,
        .offset = offset,
    };
    group_by_transferred = true;
    select_group_expressions_transferred = true;
    const ctes = if (direct_graph_source) |*source| ctes: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsCte, 1);
        out[0] = source.cte;
        source.cte = .{ .name = "" };
        direct_graph_source_transferred = true;
        plan_mod.freeTableAlias(alloc, source.table_ref);
        source.table_ref = .{ .name = "", .alias = "" };
        break :ctes out;
    } else &.{};

    return .{
        .table_name = table_ref.name,
        .ctes = ctes,
        .aggregate = aggregate_request,
    };
}

pub fn parseWindowSelectAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: WindowParserOptions,
) !plan_mod.LoweredWindowPlan {
    if (options.generated_read_ast) |read| try validateGeneratedReadAstPayloads(tokens, read.*);
    try parser.expectKeyword(tokens, pos, "select");

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var current_context = initial_context;

    var direct_graph_source = try parseDirectGraphTableFunctionSourceAlloc(alloc, tokens, pos.*, options.available_ctes, options.generated_read_ast);
    var direct_graph_source_transferred = false;
    defer if (!direct_graph_source_transferred) {
        if (direct_graph_source) |*source| source.deinit(alloc);
    };

    const inferred_table_ref = if (direct_graph_source) |source|
        try cloneTableAliasAlloc(alloc, source.table_ref)
    else if (try inferGeneratedTableAliasFromReadSourceAlloc(alloc, tokens, pos.*, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.inferSelectSourceAliasAlloc(alloc, tokens, pos.*);
    defer if (inferred_table_ref) |value| plan_mod.freeTableAlias(alloc, value);
    var inferred_qualifiers: [2][]const u8 = undefined;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (inferred_table_ref) |value| {
        inferred_qualifiers = .{ value.name, value.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
        if (direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, value.name) != null) {
            const ctes = if (direct_graph_source) |*source| source_ctes: {
                const implicit_ctes = [_]db_mod.types.RelationalRowsCte{source.cte};
                break :source_ctes implicit_ctes[0..];
            } else options.available_ctes;
            planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, initial_context.schema, ctes);
            current_context.schema = relational_rows.rowsPlannedCteSchema(planned_ctes, value.name) orelse return error.UnsupportedSqlShape;
            current_context.defer_row_expression_field_validation = true;
        }
        options.context_hooks.set_context(options.context_hooks.ptr, current_context);
    }

    const parsed_named_windows = try parseTopLevelNamedWindowSpecsAlloc(
        alloc,
        tokens,
        pos.*,
        options.params,
        .{
            .schema = current_context.schema,
            .field_expression_qualifiers = current_context.field_expression_qualifiers,
            .returning_expression_qualifiers = current_context.returning_expression_qualifiers,
            .defer_row_expression_field_validation = current_context.defer_row_expression_field_validation,
            .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
            .function_bindings = options.function_bindings,
            .order_expression_hooks = options.order_expression_hooks,
        },
        options.generated_read_ast,
    );
    defer plan_mod.freeNamedWindowSpecs(alloc, parsed_named_windows);
    const previous_named_window_specs = options.named_window_hooks.get_specs(options.named_window_hooks.ptr);
    options.named_window_hooks.set_specs(options.named_window_hooks.ptr, parsed_named_windows);
    defer options.named_window_hooks.set_specs(options.named_window_hooks.ptr, previous_named_window_specs);

    const generated_projection_end = try generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const select = try parseWindowSelectListAlloc(
        alloc,
        tokens,
        pos,
        .{
            .params = options.params,
            .schema = current_context.schema,
            .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
            .field_expression_qualifiers = current_context.field_expression_qualifiers,
            .returning_expression_qualifiers = current_context.returning_expression_qualifiers,
            .defer_row_expression_field_validation = current_context.defer_row_expression_field_validation,
            .named_window_specs = options.named_window_hooks.get_specs(options.named_window_hooks.ptr),
            .function_bindings = options.function_bindings,
            .order_expression_hooks = options.order_expression_hooks,
            .window_definition_options = .{
                .schema = current_context.schema,
                .field_expression_qualifiers = current_context.field_expression_qualifiers,
                .returning_expression_qualifiers = current_context.returning_expression_qualifiers,
                .defer_row_expression_field_validation = current_context.defer_row_expression_field_validation,
                .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                .function_bindings = options.function_bindings,
                .order_expression_hooks = options.order_expression_hooks,
            },
            .window_spec_options = options.window_spec_options,
            .generated_read_ast = options.generated_read_ast,
        },
    );
    defer if (select.outputs.len > 0) alloc.free(select.outputs);
    errdefer strings.freeStringSlice(alloc, select.fields);
    errdefer if (select.windows.len > 0) alloc.free(select.windows);
    errdefer plan_mod.freeWindowSpecs(alloc, select.windows);
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    if (select.windows.len == 0) return error.UnsupportedSqlShape;

    try parser.expectKeyword(tokens, pos, "from");
    const source_start = pos.*;
    const generated_source_end = try generatedSourceClauseEnd(tokens, source_start, options.generated_read_ast, false);
    const table_ref = if (direct_graph_source) |source| table_ref: {
        if (pos.* != source.function_start) return error.UnsupportedSqlShape;
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generatedTableAliasFromReadSourceAlloc(alloc, tokens, pos, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    errdefer alloc.free(table_ref.name);
    defer alloc.free(table_ref.alias);
    if (inferred_table_ref) |value| {
        if (!std.mem.eql(u8, table_ref.name, value.name) or !std.mem.eql(u8, table_ref.alias, value.alias)) return error.UnsupportedSqlShape;
    } else {
        inferred_qualifiers = .{ table_ref.name, table_ref.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
    }
    try validateGeneratedSingleSourceAliasForParsedTable(tokens, options.generated_read_ast, source_start, pos.*);
    if (generated_source_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const source_is_cte = direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, table_ref.name) != null;
    if (source_is_cte) current_context.defer_row_expression_field_validation = true;
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var json_path_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate).empty;
    errdefer {
        freeJsonPathEq(alloc, json_path_eq.items);
        json_path_eq.deinit(alloc);
    }
    var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, json_contains.items);
        json_contains.deinit(alloc);
    }
    var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, json_path_exists.items);
        json_path_exists.deinit(alloc);
    }
    var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
    errdefer {
        freeArrayAny(alloc, array_any.items);
        array_any.deinit(alloc);
    }
    var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, array_contains.items);
        array_contains.deinit(alloc);
    }
    var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, array_eq.items);
        array_eq.deinit(alloc);
    }
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, in_predicates.items);
        in_predicates.deinit(alloc);
    }
    var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, text_patterns.items);
        text_patterns.deinit(alloc);
    }
    var or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, or_predicates.items);
        or_predicates.deinit(alloc);
    }
    var not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, not_predicates.items);
        not_predicates.deinit(alloc);
    }
    var access_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_or_predicates.items);
        access_or_predicates.deinit(alloc);
    }
    var access_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_not_predicates.items);
        access_not_predicates.deinit(alloc);
    }
    var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, expression_predicates.items);
        expression_predicates.deinit(alloc);
    }
    var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
        expression_or_predicates.deinit(alloc);
    }
    var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
        expression_not_predicates.deinit(alloc);
    }
    var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, expression_array_contains.items);
        expression_array_contains.deinit(alloc);
    }
    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }

    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            const where_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try parseWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                where_context.schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                where_context.field_expression_qualifiers,
                where_context.returning_expression_qualifiers,
                where_context.defer_row_expression_field_validation,
                &predicates,
                &json_contains,
                &json_path_eq,
                &json_path_exists,
                &array_any,
                &array_contains,
                &array_eq,
                &in_predicates,
                &text_patterns,
                &or_predicates,
                &not_predicates,
                &access_or_predicates,
                &access_not_predicates,
                &expression_predicates,
                &expression_or_predicates,
                &expression_not_predicates,
                &expression_array_contains,
                options.realtime_ns,
                options.fixed_binary_hooks,
                options.bare_boolean_hooks,
                options.expression_alternatives_hooks,
                options.expression_condition_hooks,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "window")) {
            const keyword_index = pos.* - 1;
            const generated_window_end = try generatedWindowClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            const end = topLevelWindowClauseEnd(tokens, pos.*);
            var window_pos: usize = pos.*;
            const window_context = options.context_hooks.get_context(options.context_hooks.ptr);
            var generated_window_options = WindowDefinitionParserOptions{
                .schema = window_context.schema,
                .field_expression_qualifiers = window_context.field_expression_qualifiers,
                .returning_expression_qualifiers = window_context.returning_expression_qualifiers,
                .defer_row_expression_field_validation = window_context.defer_row_expression_field_validation,
                .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                .function_bindings = options.function_bindings,
                .order_expression_hooks = options.order_expression_hooks,
            };
            if (options.generated_read_ast) |read| generated_window_options.generated_window_items = read.window_items;
            const discarded_named_windows = try parseNamedWindowSpecsAlloc(
                alloc,
                tokens,
                &window_pos,
                end,
                options.params,
                generated_window_options,
            );
            defer plan_mod.freeNamedWindowSpecs(alloc, discarded_named_windows);
            pos.* = end;
            if (generated_window_end) |generated_end| {
                if (pos.* != generated_end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try parseWindowOutputOrderByAlloc(
                alloc,
                tokens,
                pos,
                options.context_hooks.get_context(options.context_hooks.ptr).schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                &order_by,
                select,
                blk: {
                    var order_options = options.output_order_expression_options;
                    order_options.generated_read_ast = options.generated_read_ast;
                    break :blk order_options;
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "for")) {
            return error.UnsupportedSqlShape;
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else if (nextIsUnsupportedQueryKeyword(tokens, pos.*)) {
            return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    const ctes = if (direct_graph_source) |*source| ctes: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsCte, 1);
        out[0] = source.cte;
        source.cte = .{ .name = "" };
        direct_graph_source_transferred = true;
        plan_mod.freeTableAlias(alloc, source.table_ref);
        source.table_ref = .{ .name = "", .alias = "" };
        break :ctes out;
    } else &.{};

    return .{
        .table_name = table_ref.name,
        .plan = .{
            .ctes = ctes,
            .window = .{
                .source = .{
                    .predicates = try predicates.toOwnedSlice(alloc),
                    .array_any = try array_any.toOwnedSlice(alloc),
                    .array_contains = try array_contains.toOwnedSlice(alloc),
                    .array_eq = try array_eq.toOwnedSlice(alloc),
                    .in_predicates = try in_predicates.toOwnedSlice(alloc),
                    .json_contains = try json_contains.toOwnedSlice(alloc),
                    .json_path_eq = try json_path_eq.toOwnedSlice(alloc),
                    .json_path_exists = try json_path_exists.toOwnedSlice(alloc),
                    .text_patterns = try text_patterns.toOwnedSlice(alloc),
                    .or_predicates = try or_predicates.toOwnedSlice(alloc),
                    .not_predicates = try not_predicates.toOwnedSlice(alloc),
                    .access_or_predicates = try access_or_predicates.toOwnedSlice(alloc),
                    .access_not_predicates = try access_not_predicates.toOwnedSlice(alloc),
                    .expression_predicates = try expression_predicates.toOwnedSlice(alloc),
                    .expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc),
                    .expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc),
                    .expression_array_contains = try expression_array_contains.toOwnedSlice(alloc),
                    .select_all = true,
                },
                .windows = select.windows,
                .select = select.fields,
                .select_all = select.select_all,
                .order_by = try order_by.toOwnedSlice(alloc),
                .limit = limit,
                .offset = offset,
            },
        },
    };
}

pub fn parseJoinAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: JoinParserOptions,
) !plan_mod.LoweredJoin {
    if (options.generated_read_ast) |read| try validateGeneratedReadAstPayloads(tokens, read.*);
    try validateGeneratedJoinExecutableContract(options.generated_read_ast, tokens, .join);
    try parser.expectKeyword(tokens, pos, "select");

    const generated_projection_end = try generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const raw_select = if (try generatedJoinProjectionListAlloc(alloc, options.generated_read_ast, tokens, pos)) |generated_projection|
        generated_projection
    else
        try plan_mod.parseJoinProjectionListAlloc(alloc, tokens, pos);
    defer plan_mod.freeQualifiedProjections(alloc, raw_select);
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }

    try parser.expectKeyword(tokens, pos, "from");
    const left_tokens_start = pos.*;
    var left_graph_source = try parseGraphTableFunctionSourceAtAlloc(alloc, tokens, pos.*, "__antfly_graph_join_left", options.available_ctes, options.generated_read_ast);
    var left_graph_source_transferred = false;
    defer if (!left_graph_source_transferred) {
        if (left_graph_source) |*source| source.deinit(alloc);
    };
    const left_table = if (left_graph_source) |source| table_ref: {
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generatedTableAliasFromJoinSideAlloc(alloc, tokens, pos, options.generated_read_ast, .left)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    defer plan_mod.freeTableAlias(alloc, left_table);
    const operator_tokens_start = pos.*;

    const natural_join = parser.matchKeyword(tokens, pos, "natural");
    const cross_join = if (natural_join) false else parser.matchKeyword(tokens, pos, "cross");
    const join_type: db_mod.types.RelationalRowsJoinType = if (natural_join) blk: {
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .inner;
    } else if (cross_join) blk: {
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .inner;
    } else if (parser.matchKeyword(tokens, pos, "left")) blk: {
        _ = parser.matchKeyword(tokens, pos, "outer");
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .left;
    } else blk: {
        _ = parser.matchKeyword(tokens, pos, "inner");
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .inner;
    };
    const right_tokens_start = pos.*;

    var right_graph_source = try parseGraphTableFunctionSourceAtAlloc(alloc, tokens, pos.*, "__antfly_graph_join", options.available_ctes, options.generated_read_ast);
    var right_graph_source_transferred = false;
    defer if (!right_graph_source_transferred) {
        if (right_graph_source) |*source| source.deinit(alloc);
    };
    const right_table = if (right_graph_source) |source| table_ref: {
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generatedTableAliasFromJoinSideAlloc(alloc, tokens, pos, options.generated_read_ast, .right)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    defer plan_mod.freeTableAlias(alloc, right_table);
    const condition_tokens_start = pos.*;
    if (std.mem.eql(u8, left_table.alias, right_table.alias)) return error.UnsupportedSqlShape;

    const left_table_name_source = if (left_graph_source) |source| switch (source.cte.table_function.?) {
        .graph_query => |graph_query| graph_query.table_name,
        .graph_metric_query => |graph_metric_query| graph_metric_query.table_name,
        .graph_metric_rerank_query => |graph_metric_rerank_query| graph_metric_rerank_query.table_name,
    } else left_table.name;
    const right_table_name_source = if (right_graph_source) |source| switch (source.cte.table_function.?) {
        .graph_query => |graph_query| graph_query.table_name,
        .graph_metric_query => |graph_metric_query| graph_metric_query.table_name,
        .graph_metric_rerank_query => |graph_metric_rerank_query| graph_metric_rerank_query.table_name,
    } else right_table.name;
    if (left_graph_source != null and !std.mem.eql(u8, left_table_name_source, right_table_name_source)) return error.UnsupportedSqlShape;
    if (right_graph_source) |source| {
        const graph_table_name = switch (source.cte.table_function.?) {
            .graph_query => |graph_query| graph_query.table_name,
            .graph_metric_query => |graph_metric_query| graph_metric_query.table_name,
            .graph_metric_rerank_query => |graph_metric_rerank_query| graph_metric_rerank_query.table_name,
        };
        if (!std.mem.eql(u8, left_table_name_source, graph_table_name)) return error.UnsupportedSqlShape;
    }

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var current_context = initial_context;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    var available_ctes = options.available_ctes;
    var available_ctes_owned = false;
    defer if (available_ctes_owned) alloc.free(available_ctes);
    const implicit_graph_cte_count: usize = @as(usize, if (left_graph_source != null) 1 else 0) + @as(usize, if (right_graph_source != null) 1 else 0);
    if (implicit_graph_cte_count != 0) {
        const combined = try alloc.alloc(db_mod.types.RelationalRowsCte, options.available_ctes.len + implicit_graph_cte_count);
        @memcpy(combined[0..options.available_ctes.len], options.available_ctes);
        var combined_index = options.available_ctes.len;
        if (left_graph_source) |source| {
            combined[combined_index] = source.cte;
            combined_index += 1;
        }
        if (right_graph_source) |source| {
            combined[combined_index] = source.cte;
            combined_index += 1;
        }
        available_ctes = combined;
        available_ctes_owned = true;
    }
    if (available_ctes.len != 0) {
        const cte_base_schema = initial_context.joined_source_schema orelse initial_context.schema;
        planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, cte_base_schema, available_ctes);
    }
    current_context.schema = relational_rows.rowsPlannedCteSchema(planned_ctes, left_table.name) orelse initial_context.schema;
    current_context.joined_source_schema = relational_rows.rowsPlannedCteSchema(planned_ctes, right_table.name) orelse initial_context.joined_source_schema orelse initial_context.schema;
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    var on = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinOn).empty;
    errdefer {
        plan_mod.freeJoinOn(alloc, on.items);
        on.deinit(alloc);
    }
    var left_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, left_predicates.items);
        left_predicates.deinit(alloc);
    }
    var right_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, right_predicates.items);
        right_predicates.deinit(alloc);
    }
    var left_json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, left_json_contains.items);
        left_json_contains.deinit(alloc);
    }
    var right_json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, right_json_contains.items);
        right_json_contains.deinit(alloc);
    }
    var left_json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, left_json_path_exists.items);
        left_json_path_exists.deinit(alloc);
    }
    var right_json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, right_json_path_exists.items);
        right_json_path_exists.deinit(alloc);
    }
    var left_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, left_array_contains.items);
        left_array_contains.deinit(alloc);
    }
    var right_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, right_array_contains.items);
        right_array_contains.deinit(alloc);
    }
    var left_array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, left_array_eq.items);
        left_array_eq.deinit(alloc);
    }
    var right_array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, right_array_eq.items);
        right_array_eq.deinit(alloc);
    }
    var left_in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, left_in_predicates.items);
        left_in_predicates.deinit(alloc);
    }
    var right_in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, right_in_predicates.items);
        right_in_predicates.deinit(alloc);
    }
    var left_text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, left_text_patterns.items);
        left_text_patterns.deinit(alloc);
    }
    var right_text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, right_text_patterns.items);
        right_text_patterns.deinit(alloc);
    }
    var left_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, left_expression_predicates.items);
        left_expression_predicates.deinit(alloc);
    }
    var right_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, right_expression_predicates.items);
        right_expression_predicates.deinit(alloc);
    }
    var left_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, left_expression_or_predicates.items);
        left_expression_or_predicates.deinit(alloc);
    }
    var right_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, right_expression_or_predicates.items);
        right_expression_or_predicates.deinit(alloc);
    }
    var left_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, left_expression_not_predicates.items);
        left_expression_not_predicates.deinit(alloc);
    }
    var right_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, right_expression_not_predicates.items);
        right_expression_not_predicates.deinit(alloc);
    }
    var left_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, left_expression_array_contains.items);
        left_expression_array_contains.deinit(alloc);
    }
    var right_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, right_expression_array_contains.items);
        right_expression_array_contains.deinit(alloc);
    }
    var match_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, match_expression_predicates.items);
        match_expression_predicates.deinit(alloc);
    }
    var on_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, on_expression_predicates.items);
        on_expression_predicates.deinit(alloc);
    }
    var on_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, on_expression_or_predicates.items);
        on_expression_or_predicates.deinit(alloc);
    }
    var on_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, on_expression_not_predicates.items);
        on_expression_not_predicates.deinit(alloc);
    }
    var on_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, on_expression_array_contains.items);
        on_expression_array_contains.deinit(alloc);
    }
    var match_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_or_predicates.items);
        match_expression_or_predicates.deinit(alloc);
    }
    var match_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_not_predicates.items);
        match_expression_not_predicates.deinit(alloc);
    }
    var match_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, match_expression_array_contains.items);
        match_expression_array_contains.deinit(alloc);
    }

    if (cross_join) {
        try validateGeneratedSingleConditionlessJoinForClause(
            options.generated_read_ast,
            .join,
            tokens,
            .{ .start = left_tokens_start, .end = operator_tokens_start },
            .{ .start = operator_tokens_start, .end = right_tokens_start },
            .cross,
            .{ .start = right_tokens_start, .end = condition_tokens_start },
        );
    } else if (natural_join) {
        try appendNaturalJoinColumnsAlloc(alloc, current_context.schema, current_context.joined_source_schema, &on);
        try validateGeneratedSingleConditionlessJoinForClause(
            options.generated_read_ast,
            .join,
            tokens,
            .{ .start = left_tokens_start, .end = operator_tokens_start },
            .{ .start = operator_tokens_start, .end = right_tokens_start },
            .natural,
            .{ .start = right_tokens_start, .end = condition_tokens_start },
        );
    } else if (parser.matchKeyword(tokens, pos, "on")) {
        const predicate_tokens_start = pos.*;
        var on_targets = JoinOnPredicateTargets{
            .on = &on,
            .left_predicates = &left_predicates,
            .right_predicates = &right_predicates,
            .on_expression_predicates = &on_expression_predicates,
            .on_expression_or_predicates = &on_expression_or_predicates,
            .on_expression_not_predicates = &on_expression_not_predicates,
            .on_expression_array_contains = &on_expression_array_contains,
        };
        const generated_on_expression = try generatedSingleJoinPredicateExpression(options.generated_read_ast);
        try parseJoinOnAlloc(
            alloc,
            tokens,
            pos,
            options.params,
            current_context.schema,
            current_context.joined_source_schema,
            join_type,
            left_table.alias,
            right_table.alias,
            options.string_to_array_predicate_is_containment,
            &on_targets,
            options.expression_where_options,
            options.realtime_ns,
            generated_on_expression,
        );
        try validateGeneratedSingleJoinForClause(
            options.generated_read_ast,
            .join,
            tokens,
            .{ .start = left_tokens_start, .end = operator_tokens_start },
            .{ .start = operator_tokens_start, .end = right_tokens_start },
            join_type,
            .{ .start = right_tokens_start, .end = condition_tokens_start },
            .{ .start = condition_tokens_start, .end = pos.* },
            .{ .start = predicate_tokens_start, .end = pos.* },
        );
    } else if (parser.matchKeyword(tokens, pos, "using")) {
        try parser.expectToken(tokens, pos, .lparen);
        const column_tokens_start = pos.*;
        const using_columns = if (try generatedJoinUsingColumnsAlloc(alloc, options.generated_read_ast, .join, tokens, pos)) |generated_columns|
            generated_columns
        else
            try grammar.parseIdentifierListAlloc(alloc, tokens, pos);
        defer strings.freeStringSlice(alloc, using_columns);
        const column_tokens_end = pos.*;
        try parser.expectToken(tokens, pos, .rparen);
        try appendJoinUsingColumnsAlloc(alloc, using_columns, current_context.schema, current_context.joined_source_schema, &on);
        try validateGeneratedSingleJoinUsingForClause(
            options.generated_read_ast,
            .join,
            tokens,
            .{ .start = left_tokens_start, .end = operator_tokens_start },
            .{ .start = operator_tokens_start, .end = right_tokens_start },
            join_type,
            .{ .start = right_tokens_start, .end = condition_tokens_start },
            .{ .start = condition_tokens_start, .end = pos.* },
            .{ .start = column_tokens_start, .end = column_tokens_end },
        );
    } else {
        return error.UnsupportedSqlShape;
    }

    var select = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinProjection).empty;
    errdefer {
        plan_mod.freeJoinProjections(alloc, select.items);
        select.deinit(alloc);
    }
    try binder.resolveJoinProjectionsAlloc(alloc, current_context.schema, current_context.joined_source_schema, raw_select, left_table.alias, right_table.alias, &select);

    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }

    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            var where_targets = JoinWherePredicateTargets{
                .left_predicates = &left_predicates,
                .right_predicates = &right_predicates,
                .left_json_contains = &left_json_contains,
                .right_json_contains = &right_json_contains,
                .left_json_path_exists = &left_json_path_exists,
                .right_json_path_exists = &right_json_path_exists,
                .left_array_contains = &left_array_contains,
                .right_array_contains = &right_array_contains,
                .left_array_eq = &left_array_eq,
                .right_array_eq = &right_array_eq,
                .left_in_predicates = &left_in_predicates,
                .right_in_predicates = &right_in_predicates,
                .left_text_patterns = &left_text_patterns,
                .right_text_patterns = &right_text_patterns,
                .left_expression_predicates = &left_expression_predicates,
                .right_expression_predicates = &right_expression_predicates,
                .left_expression_or_predicates = &left_expression_or_predicates,
                .right_expression_or_predicates = &right_expression_or_predicates,
                .left_expression_not_predicates = &left_expression_not_predicates,
                .right_expression_not_predicates = &right_expression_not_predicates,
                .left_expression_array_contains = &left_expression_array_contains,
                .right_expression_array_contains = &right_expression_array_contains,
                .match_expression_predicates = &match_expression_predicates,
                .match_expression_or_predicates = &match_expression_or_predicates,
                .match_expression_not_predicates = &match_expression_not_predicates,
                .match_expression_array_contains = &match_expression_array_contains,
            };
            try parseJoinWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                current_context.schema,
                current_context.joined_source_schema,
                left_table.alias,
                right_table.alias,
                options.string_to_array_predicate_is_containment,
                &where_targets,
                options.expression_where_options,
                options.realtime_ns,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try parseJoinOrderByAlloc(
                alloc,
                tokens,
                pos,
                current_context.schema,
                &order_by,
                select.items,
                blk: {
                    var order_options = options.output_order_expression_options;
                    order_options.generated_read_ast = options.generated_read_ast;
                    break :blk order_options;
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else if (nextIsUnsupportedQueryKeyword(tokens, pos.*)) {
            return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    const left_table_name = try alloc.dupe(u8, left_table_name_source);
    var left_table_name_transferred = false;
    errdefer if (!left_table_name_transferred) alloc.free(left_table_name);
    const right_table_name = try alloc.dupe(u8, right_table_name_source);
    var right_table_name_transferred = false;
    errdefer if (!right_table_name_transferred) alloc.free(right_table_name);
    const left_source_cte = if (left_graph_source) |source| try alloc.dupe(u8, source.cte.name) else "";
    var left_source_cte_transferred = false;
    errdefer if (!left_source_cte_transferred and left_source_cte.len > 0) alloc.free(left_source_cte);
    const right_source_cte = if (right_graph_source) |source| try alloc.dupe(u8, source.cte.name) else "";
    var right_source_cte_transferred = false;
    errdefer if (!right_source_cte_transferred and right_source_cte.len > 0) alloc.free(right_source_cte);

    const join_request = db_mod.types.RelationalRowsJoinRequest{
        .left = .{
            .source_cte = left_source_cte,
            .predicates = try left_predicates.toOwnedSlice(alloc),
            .json_contains = try left_json_contains.toOwnedSlice(alloc),
            .json_path_exists = try left_json_path_exists.toOwnedSlice(alloc),
            .array_contains = try left_array_contains.toOwnedSlice(alloc),
            .array_eq = try left_array_eq.toOwnedSlice(alloc),
            .in_predicates = try left_in_predicates.toOwnedSlice(alloc),
            .text_patterns = try left_text_patterns.toOwnedSlice(alloc),
            .expression_predicates = try left_expression_predicates.toOwnedSlice(alloc),
            .expression_or_predicates = try left_expression_or_predicates.toOwnedSlice(alloc),
            .expression_not_predicates = try left_expression_not_predicates.toOwnedSlice(alloc),
            .expression_array_contains = try left_expression_array_contains.toOwnedSlice(alloc),
            .select_all = true,
        },
        .right = .{
            .source_cte = right_source_cte,
            .predicates = try right_predicates.toOwnedSlice(alloc),
            .json_contains = try right_json_contains.toOwnedSlice(alloc),
            .json_path_exists = try right_json_path_exists.toOwnedSlice(alloc),
            .array_contains = try right_array_contains.toOwnedSlice(alloc),
            .array_eq = try right_array_eq.toOwnedSlice(alloc),
            .in_predicates = try right_in_predicates.toOwnedSlice(alloc),
            .text_patterns = try right_text_patterns.toOwnedSlice(alloc),
            .expression_predicates = try right_expression_predicates.toOwnedSlice(alloc),
            .expression_or_predicates = try right_expression_or_predicates.toOwnedSlice(alloc),
            .expression_not_predicates = try right_expression_not_predicates.toOwnedSlice(alloc),
            .expression_array_contains = try right_expression_array_contains.toOwnedSlice(alloc),
            .select_all = true,
        },
        .on = try on.toOwnedSlice(alloc),
        .on_expression_predicates = try on_expression_predicates.toOwnedSlice(alloc),
        .on_expression_or_predicates = try on_expression_or_predicates.toOwnedSlice(alloc),
        .on_expression_not_predicates = try on_expression_not_predicates.toOwnedSlice(alloc),
        .on_expression_array_contains = try on_expression_array_contains.toOwnedSlice(alloc),
        .match_expression_predicates = try match_expression_predicates.toOwnedSlice(alloc),
        .match_expression_or_predicates = try match_expression_or_predicates.toOwnedSlice(alloc),
        .match_expression_not_predicates = try match_expression_not_predicates.toOwnedSlice(alloc),
        .match_expression_array_contains = try match_expression_array_contains.toOwnedSlice(alloc),
        .join_type = join_type,
        .select = try select.toOwnedSlice(alloc),
        .order_by = try order_by.toOwnedSlice(alloc),
        .limit = limit,
        .offset = offset,
    };
    left_table_name_transferred = true;
    right_table_name_transferred = true;
    left_source_cte_transferred = true;
    right_source_cte_transferred = true;
    const ctes = if (implicit_graph_cte_count != 0) ctes: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsCte, implicit_graph_cte_count);
        var out_index: usize = 0;
        if (left_graph_source) |*source| {
            out[out_index] = source.cte;
            out_index += 1;
            source.cte = .{ .name = "" };
            plan_mod.freeTableAlias(alloc, source.table_ref);
            source.table_ref = .{ .name = "", .alias = "" };
            left_graph_source_transferred = true;
        }
        if (right_graph_source) |*source| {
            out[out_index] = source.cte;
            out_index += 1;
            source.cte = .{ .name = "" };
            plan_mod.freeTableAlias(alloc, source.table_ref);
            source.table_ref = .{ .name = "", .alias = "" };
            right_graph_source_transferred = true;
        }
        break :ctes out;
    } else &.{};
    return .{
        .left_table_name = left_table_name,
        .right_table_name = right_table_name,
        .ctes = ctes,
        .join = join_request,
    };
}

fn freeSelectListAlloc(alloc: std.mem.Allocator, select: plan_mod.SelectList) void {
    strings.freeStringSlice(alloc, select.fields);
    plan_mod.freeJsonExtract(alloc, select.json_extract);
    plan_mod.freeArrayLengthProjections(alloc, select.array_length);
    plan_mod.freeCoalesceProjections(alloc, select.coalesce);
    plan_mod.freeFieldAliasProjections(alloc, select.field_aliases);
    plan_mod.freeExpressionProjections(alloc, select.expressions);
    if (select.outputs.len > 0) alloc.free(select.outputs);
}

pub fn parseLateralSubqueryAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: LateralSubqueryParserOptions,
) !plan_mod.LateralSubquery {
    if (options.generated_read_ast) |read| try validateGeneratedReadAstPayloads(tokens, read.*);
    try parser.expectKeyword(tokens, pos, "select");
    const inferred_table_ref: ?plan_mod.TableAlias = if (try inferGeneratedTableAliasFromReadSourceAlloc(alloc, tokens, pos.*, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.inferSelectSourceAliasAlloc(alloc, tokens, pos.*);
    defer if (inferred_table_ref) |value| plan_mod.freeTableAlias(alloc, value);

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    const left_schema = initial_context.schema;
    const right_base_schema = initial_context.joined_source_schema orelse initial_context.schema;

    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    var right_parse_schema = right_base_schema;
    if (inferred_table_ref) |value| {
        if (plan_mod.findCteByName(options.available_ctes, value.name) != null) {
            planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, right_base_schema, options.available_ctes);
            right_parse_schema = relational_rows.rowsPlannedCteSchema(planned_ctes, value.name) orelse return error.UnsupportedSqlShape;
        }
    }

    options.context_hooks.set_context(options.context_hooks.ptr, .{
        .schema = right_parse_schema,
        .joined_source_schema = right_parse_schema,
    });
    const select_context = options.context_hooks.get_context(options.context_hooks.ptr);
    const generated_projection_end = try generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const select = try parseSelectListAlloc(
        alloc,
        tokens,
        pos,
        .{
            .params = options.params,
            .output_schema = right_parse_schema,
            .select_item_schema = select_context.schema,
            .function_bindings = options.function_bindings,
            .type_context = .{
                .alloc = alloc,
                .schema = select_context.schema,
                .joined_source_schema = select_context.joined_source_schema,
            },
            .field_source = options.field_source,
            .select_item_options = options.select_item_options,
            .generated_read_ast = options.generated_read_ast,
        },
    );
    defer freeSelectListAlloc(alloc, select);
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const output_columns = try expr_projection.selectOutputColumnsAlloc(alloc, .{
        .alloc = alloc,
        .schema = right_parse_schema,
        .joined_source_schema = right_parse_schema,
    }, select);
    errdefer ddl_plan.freeDdlRelationalColumns(alloc, output_columns);

    options.context_hooks.set_context(options.context_hooks.ptr, .{
        .schema = left_schema,
        .joined_source_schema = right_parse_schema,
    });
    if (select.select_all) return error.UnsupportedSqlShape;

    try parser.expectKeyword(tokens, pos, "from");
    const right_table = if (try generatedTableAliasFromReadSourceAlloc(alloc, tokens, pos, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    errdefer plan_mod.freeTableAlias(alloc, right_table);
    if (inferred_table_ref) |value| {
        if (!std.mem.eql(u8, right_table.name, value.name) or !std.mem.eql(u8, right_table.alias, value.alias)) return error.UnsupportedSqlShape;
    }

    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, json_contains.items);
        json_contains.deinit(alloc);
    }
    var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, json_path_exists.items);
        json_path_exists.deinit(alloc);
    }
    var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, array_contains.items);
        array_contains.deinit(alloc);
    }
    var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, array_eq.items);
        array_eq.deinit(alloc);
    }
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, in_predicates.items);
        in_predicates.deinit(alloc);
    }
    var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, text_patterns.items);
        text_patterns.deinit(alloc);
    }
    var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, expression_predicates.items);
        expression_predicates.deinit(alloc);
    }
    var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
        expression_or_predicates.deinit(alloc);
    }
    var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
        expression_not_predicates.deinit(alloc);
    }
    var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, expression_array_contains.items);
        expression_array_contains.deinit(alloc);
    }
    var match_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, match_expression_predicates.items);
        match_expression_predicates.deinit(alloc);
    }
    var match_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_or_predicates.items);
        match_expression_or_predicates.deinit(alloc);
    }
    var match_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_not_predicates.items);
        match_expression_not_predicates.deinit(alloc);
    }
    var match_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, match_expression_array_contains.items);
        match_expression_array_contains.deinit(alloc);
    }
    var correlations = std.ArrayListUnmanaged(db_mod.types.RelationalRowsLateralCorrelation).empty;
    errdefer {
        plan_mod.freeLateralCorrelations(alloc, correlations.items);
        correlations.deinit(alloc);
    }
    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }

    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            var targets = LateralWherePredicateTargets{
                .predicates = &predicates,
                .json_contains = &json_contains,
                .json_path_exists = &json_path_exists,
                .array_contains = &array_contains,
                .array_eq = &array_eq,
                .in_predicates = &in_predicates,
                .text_patterns = &text_patterns,
                .expression_predicates = &expression_predicates,
                .expression_or_predicates = &expression_or_predicates,
                .expression_not_predicates = &expression_not_predicates,
                .expression_array_contains = &expression_array_contains,
                .match_expression_predicates = &match_expression_predicates,
                .match_expression_or_predicates = &match_expression_or_predicates,
                .match_expression_not_predicates = &match_expression_not_predicates,
                .match_expression_array_contains = &match_expression_array_contains,
                .correlations = &correlations,
            };
            try parseLateralWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                left_schema,
                right_parse_schema,
                options.left_alias,
                right_table.alias,
                stringToArrayPredicateIsContainment(tokens, pos.*),
                &targets,
                options.expression_where_options,
                options.realtime_ns,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try parseSelectOutputOrderByAlloc(
                alloc,
                tokens,
                pos,
                &order_by,
                select,
                .{
                    .schema = left_schema,
                    .function_bindings = options.function_bindings,
                    .field_expression_qualifiers = &.{},
                    .returning_expression_qualifiers = &.{},
                    .defer_row_expression_field_validation = false,
                    .type_context = .{ .alloc = alloc, .schema = left_schema },
                    .order_expression_hooks = options.order_expression_hooks,
                    .generated_read_ast = options.generated_read_ast,
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else {
            return error.UnsupportedSqlShape;
        }
    }
    if (limit == null or correlations.items.len == 0) return error.UnsupportedSqlShape;

    return .{
        .table = right_table,
        .output_columns = output_columns,
        .predicates = try predicates.toOwnedSlice(alloc),
        .json_contains = try json_contains.toOwnedSlice(alloc),
        .json_path_exists = try json_path_exists.toOwnedSlice(alloc),
        .array_contains = try array_contains.toOwnedSlice(alloc),
        .array_eq = try array_eq.toOwnedSlice(alloc),
        .in_predicates = try in_predicates.toOwnedSlice(alloc),
        .text_patterns = try text_patterns.toOwnedSlice(alloc),
        .expression_predicates = try expression_predicates.toOwnedSlice(alloc),
        .expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc),
        .expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc),
        .expression_array_contains = try expression_array_contains.toOwnedSlice(alloc),
        .match_expression_predicates = try match_expression_predicates.toOwnedSlice(alloc),
        .match_expression_or_predicates = try match_expression_or_predicates.toOwnedSlice(alloc),
        .match_expression_not_predicates = try match_expression_not_predicates.toOwnedSlice(alloc),
        .match_expression_array_contains = try match_expression_array_contains.toOwnedSlice(alloc),
        .correlations = try correlations.toOwnedSlice(alloc),
        .order_by = try order_by.toOwnedSlice(alloc),
        .limit = limit,
        .offset = offset,
    };
}

pub fn parseLateralAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: LateralParserOptions,
) !plan_mod.LoweredLateralPlan {
    if (options.generated_read_ast) |read| try validateGeneratedReadAstPayloads(tokens, read.*);
    try validateGeneratedJoinExecutableContract(options.generated_read_ast, tokens, .lateral);
    try parser.expectKeyword(tokens, pos, "select");

    const raw_select = if (try generatedJoinProjectionListAlloc(alloc, options.generated_read_ast, tokens, pos)) |generated_projections|
        generated_projections
    else
        try plan_mod.parseJoinProjectionListAlloc(alloc, tokens, pos);
    defer plan_mod.freeQualifiedProjections(alloc, raw_select);

    try parser.expectKeyword(tokens, pos, "from");
    const left_tokens_start = pos.*;
    const left_table = if (try generatedTableAliasFromJoinSideAlloc(alloc, tokens, pos, options.generated_read_ast, .left)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    defer plan_mod.freeTableAlias(alloc, left_table);
    const operator_tokens_start = pos.*;

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (options.available_ctes.len != 0) {
        const cte_base_schema = initial_context.joined_source_schema orelse initial_context.schema;
        planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, cte_base_schema, options.available_ctes);
    }
    const left_source_schema = relational_rows.rowsPlannedCteSchema(planned_ctes, left_table.name) orelse initial_context.schema;
    const right_source_schema = initial_context.joined_source_schema orelse initial_context.schema;
    var current_context = JoinParserContext{
        .schema = left_source_schema,
        .joined_source_schema = right_source_schema,
    };
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    try parser.expectKeyword(tokens, pos, "left");
    _ = parser.matchKeyword(tokens, pos, "outer");
    try parser.expectKeyword(tokens, pos, "join");
    const right_tokens_start = pos.*;
    try parser.expectKeyword(tokens, pos, "lateral");
    try parser.expectToken(tokens, pos, .lparen);
    const close_index = (parser.findMatchingRParenAfterOpenIndex(tokens, pos.*) orelse return error.UnsupportedSqlShape);
    const generated_lateral_subquery_read_ast = try generatedLateralSubqueryReadAstForRange(options.generated_read_ast, pos.*, close_index);
    var lateral_subquery = try options.subquery_hooks.parse_subquery(
        options.subquery_hooks.ptr,
        tokens[pos.*..close_index],
        left_source_schema,
        right_source_schema,
        left_table.alias,
        options.available_ctes,
        generated_lateral_subquery_read_ast,
    );
    errdefer plan_mod.freeLateralSubquery(alloc, lateral_subquery);
    pos.* = close_index + 1;

    const lateral_alias = if (try generatedLateralAliasAlloc(alloc, tokens, pos, options.generated_read_ast)) |generated_alias|
        generated_alias
    else
        try grammar.parseRequiredAliasAlloc(alloc, tokens, pos);
    defer alloc.free(lateral_alias);
    const condition_tokens_start = pos.*;

    current_context.joined_source_schema = .{
        .storage_mode = .relational,
        .relational_columns = lateral_subquery.output_columns,
    };
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    try parser.expectKeyword(tokens, pos, "on");
    const predicate_tokens_start = pos.*;
    try parser.expectKeyword(tokens, pos, "true");
    try validateGeneratedSingleJoinForClause(
        options.generated_read_ast,
        .lateral,
        tokens,
        .{ .start = left_tokens_start, .end = operator_tokens_start },
        .{ .start = operator_tokens_start, .end = right_tokens_start },
        .left,
        .{ .start = right_tokens_start, .end = condition_tokens_start },
        .{ .start = condition_tokens_start, .end = pos.* },
        .{ .start = predicate_tokens_start, .end = pos.* },
    );

    var left_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, left_predicates.items);
        left_predicates.deinit(alloc);
    }
    var left_json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, left_json_contains.items);
        left_json_contains.deinit(alloc);
    }
    var left_json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, left_json_path_exists.items);
        left_json_path_exists.deinit(alloc);
    }
    var left_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, left_array_contains.items);
        left_array_contains.deinit(alloc);
    }
    var left_array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, left_array_eq.items);
        left_array_eq.deinit(alloc);
    }
    var left_in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, left_in_predicates.items);
        left_in_predicates.deinit(alloc);
    }
    var left_text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, left_text_patterns.items);
        left_text_patterns.deinit(alloc);
    }
    var left_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, left_expression_predicates.items);
        left_expression_predicates.deinit(alloc);
    }
    var left_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, left_expression_or_predicates.items);
        left_expression_or_predicates.deinit(alloc);
    }
    var left_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, left_expression_not_predicates.items);
        left_expression_not_predicates.deinit(alloc);
    }
    var left_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, left_expression_array_contains.items);
        left_expression_array_contains.deinit(alloc);
    }
    var unsupported_right_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer {
        freeRelationalChecks(alloc, unsupported_right_predicates.items);
        unsupported_right_predicates.deinit(alloc);
    }
    var unsupported_right_json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    defer {
        freeJsonContains(alloc, unsupported_right_json_contains.items);
        unsupported_right_json_contains.deinit(alloc);
    }
    var unsupported_right_json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    defer {
        freeJsonPathExists(alloc, unsupported_right_json_path_exists.items);
        unsupported_right_json_path_exists.deinit(alloc);
    }
    var unsupported_right_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    defer {
        freeArrayContains(alloc, unsupported_right_array_contains.items);
        unsupported_right_array_contains.deinit(alloc);
    }
    var unsupported_right_array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    defer {
        freeArrayEq(alloc, unsupported_right_array_eq.items);
        unsupported_right_array_eq.deinit(alloc);
    }
    var unsupported_right_in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    defer {
        freeInPredicates(alloc, unsupported_right_in_predicates.items);
        unsupported_right_in_predicates.deinit(alloc);
    }
    var unsupported_right_text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    defer {
        freeTextPatterns(alloc, unsupported_right_text_patterns.items);
        unsupported_right_text_patterns.deinit(alloc);
    }
    var unsupported_right_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    defer {
        freeExpressionConditions(alloc, unsupported_right_expression_predicates.items);
        unsupported_right_expression_predicates.deinit(alloc);
    }
    var unsupported_right_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    defer {
        freeExpressionPredicateGroups(alloc, unsupported_right_expression_or_predicates.items);
        unsupported_right_expression_or_predicates.deinit(alloc);
    }
    var unsupported_right_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    defer {
        freeExpressionPredicateGroups(alloc, unsupported_right_expression_not_predicates.items);
        unsupported_right_expression_not_predicates.deinit(alloc);
    }
    var unsupported_right_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    defer {
        freeExpressionArrayContains(alloc, unsupported_right_expression_array_contains.items);
        unsupported_right_expression_array_contains.deinit(alloc);
    }
    var match_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, match_expression_predicates.items);
        match_expression_predicates.deinit(alloc);
    }
    var match_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_or_predicates.items);
        match_expression_or_predicates.deinit(alloc);
    }
    var match_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_not_predicates.items);
        match_expression_not_predicates.deinit(alloc);
    }
    var match_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, match_expression_array_contains.items);
        match_expression_array_contains.deinit(alloc);
    }
    var select = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinProjection).empty;
    errdefer {
        plan_mod.freeJoinProjections(alloc, select.items);
        select.deinit(alloc);
    }
    try binder.resolveJoinProjectionsAlloc(alloc, current_context.schema, current_context.joined_source_schema, raw_select, left_table.alias, lateral_alias, &select);

    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }
    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            var where_targets = JoinWherePredicateTargets{
                .left_predicates = &left_predicates,
                .right_predicates = &unsupported_right_predicates,
                .left_json_contains = &left_json_contains,
                .right_json_contains = &unsupported_right_json_contains,
                .left_json_path_exists = &left_json_path_exists,
                .right_json_path_exists = &unsupported_right_json_path_exists,
                .left_array_contains = &left_array_contains,
                .right_array_contains = &unsupported_right_array_contains,
                .left_array_eq = &left_array_eq,
                .right_array_eq = &unsupported_right_array_eq,
                .left_in_predicates = &left_in_predicates,
                .right_in_predicates = &unsupported_right_in_predicates,
                .left_text_patterns = &left_text_patterns,
                .right_text_patterns = &unsupported_right_text_patterns,
                .left_expression_predicates = &left_expression_predicates,
                .right_expression_predicates = &unsupported_right_expression_predicates,
                .left_expression_or_predicates = &left_expression_or_predicates,
                .right_expression_or_predicates = &unsupported_right_expression_or_predicates,
                .left_expression_not_predicates = &left_expression_not_predicates,
                .right_expression_not_predicates = &unsupported_right_expression_not_predicates,
                .left_expression_array_contains = &left_expression_array_contains,
                .right_expression_array_contains = &unsupported_right_expression_array_contains,
                .match_expression_predicates = &match_expression_predicates,
                .match_expression_or_predicates = &match_expression_or_predicates,
                .match_expression_not_predicates = &match_expression_not_predicates,
                .match_expression_array_contains = &match_expression_array_contains,
            };
            try parseJoinWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                current_context.schema,
                current_context.joined_source_schema,
                left_table.alias,
                lateral_alias,
                options.string_to_array_predicate_is_containment,
                &where_targets,
                options.expression_where_options,
                options.realtime_ns,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
            if (unsupported_right_predicates.items.len != 0 or
                unsupported_right_json_contains.items.len != 0 or
                unsupported_right_json_path_exists.items.len != 0 or
                unsupported_right_array_contains.items.len != 0 or
                unsupported_right_array_eq.items.len != 0 or
                unsupported_right_in_predicates.items.len != 0 or
                unsupported_right_text_patterns.items.len != 0 or
                unsupported_right_expression_predicates.items.len != 0 or
                unsupported_right_expression_or_predicates.items.len != 0 or
                unsupported_right_expression_not_predicates.items.len != 0 or
                unsupported_right_expression_array_contains.items.len != 0) return error.UnsupportedSqlShape;
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try parseJoinOrderByAlloc(
                alloc,
                tokens,
                pos,
                current_context.schema,
                &order_by,
                select.items,
                blk: {
                    var order_options = options.output_order_expression_options;
                    order_options.generated_read_ast = options.generated_read_ast;
                    break :blk order_options;
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    if (lateral_subquery.match_expression_predicates.len > 0) {
        try match_expression_predicates.appendSlice(alloc, lateral_subquery.match_expression_predicates);
        alloc.free(lateral_subquery.match_expression_predicates);
        lateral_subquery.match_expression_predicates = &.{};
    }
    if (lateral_subquery.match_expression_or_predicates.len > 0) {
        try match_expression_or_predicates.appendSlice(alloc, lateral_subquery.match_expression_or_predicates);
        alloc.free(lateral_subquery.match_expression_or_predicates);
        lateral_subquery.match_expression_or_predicates = &.{};
    }
    if (lateral_subquery.match_expression_not_predicates.len > 0) {
        try match_expression_not_predicates.appendSlice(alloc, lateral_subquery.match_expression_not_predicates);
        alloc.free(lateral_subquery.match_expression_not_predicates);
        lateral_subquery.match_expression_not_predicates = &.{};
    }
    if (lateral_subquery.match_expression_array_contains.len > 0) {
        try match_expression_array_contains.appendSlice(alloc, lateral_subquery.match_expression_array_contains);
        alloc.free(lateral_subquery.match_expression_array_contains);
        lateral_subquery.match_expression_array_contains = &.{};
    }

    const left_table_name = try alloc.dupe(u8, left_table.name);
    var left_table_name_transferred = false;
    errdefer if (!left_table_name_transferred) alloc.free(left_table_name);
    const right_table_name = try alloc.dupe(u8, lateral_subquery.table.name);
    var right_table_name_transferred = false;
    errdefer if (!right_table_name_transferred) alloc.free(right_table_name);
    const plan_left_table_name = try alloc.dupe(u8, left_table.name);
    var plan_left_table_name_transferred = false;
    errdefer if (!plan_left_table_name_transferred) alloc.free(plan_left_table_name);
    const plan_right_table_name = try alloc.dupe(u8, lateral_subquery.table.name);
    var plan_right_table_name_transferred = false;
    errdefer if (!plan_right_table_name_transferred) alloc.free(plan_right_table_name);

    const left_owned_predicates = try left_predicates.toOwnedSlice(alloc);
    const left_owned_json_contains = try left_json_contains.toOwnedSlice(alloc);
    const left_owned_json_path_exists = try left_json_path_exists.toOwnedSlice(alloc);
    const left_owned_array_contains = try left_array_contains.toOwnedSlice(alloc);
    const left_owned_array_eq = try left_array_eq.toOwnedSlice(alloc);
    const left_owned_in_predicates = try left_in_predicates.toOwnedSlice(alloc);
    const left_owned_text_patterns = try left_text_patterns.toOwnedSlice(alloc);
    const left_owned_expression_predicates = try left_expression_predicates.toOwnedSlice(alloc);
    const left_owned_expression_or_predicates = try left_expression_or_predicates.toOwnedSlice(alloc);
    const left_owned_expression_not_predicates = try left_expression_not_predicates.toOwnedSlice(alloc);
    const left_owned_expression_array_contains = try left_expression_array_contains.toOwnedSlice(alloc);
    const match_owned_expression_predicates = try match_expression_predicates.toOwnedSlice(alloc);
    const match_owned_expression_or_predicates = try match_expression_or_predicates.toOwnedSlice(alloc);
    const match_owned_expression_not_predicates = try match_expression_not_predicates.toOwnedSlice(alloc);
    const match_owned_expression_array_contains = try match_expression_array_contains.toOwnedSlice(alloc);
    const select_owned = try select.toOwnedSlice(alloc);
    const order_owned = try order_by.toOwnedSlice(alloc);

    const right_predicates = lateral_subquery.predicates;
    const right_json_contains = lateral_subquery.json_contains;
    const right_json_path_exists = lateral_subquery.json_path_exists;
    const right_array_contains = lateral_subquery.array_contains;
    const right_array_eq = lateral_subquery.array_eq;
    const right_in_predicates = lateral_subquery.in_predicates;
    const right_text_patterns = lateral_subquery.text_patterns;
    const right_expression_predicates = lateral_subquery.expression_predicates;
    const right_expression_or_predicates = lateral_subquery.expression_or_predicates;
    const right_expression_not_predicates = lateral_subquery.expression_not_predicates;
    const right_expression_array_contains = lateral_subquery.expression_array_contains;
    const correlations = lateral_subquery.correlations;
    const right_order_by = lateral_subquery.order_by;
    const right_limit = lateral_subquery.limit;
    const right_offset = lateral_subquery.offset;
    lateral_subquery.predicates = &.{};
    lateral_subquery.json_contains = &.{};
    lateral_subquery.json_path_exists = &.{};
    lateral_subquery.array_contains = &.{};
    lateral_subquery.array_eq = &.{};
    lateral_subquery.in_predicates = &.{};
    lateral_subquery.text_patterns = &.{};
    lateral_subquery.expression_predicates = &.{};
    lateral_subquery.expression_or_predicates = &.{};
    lateral_subquery.expression_not_predicates = &.{};
    lateral_subquery.expression_array_contains = &.{};
    lateral_subquery.correlations = &.{};
    lateral_subquery.order_by = &.{};
    ddl_plan.freeDdlRelationalColumns(alloc, lateral_subquery.output_columns);
    lateral_subquery.output_columns = &.{};
    plan_mod.freeTableAlias(alloc, lateral_subquery.table);
    lateral_subquery.table = .{ .name = "", .alias = "" };

    left_table_name_transferred = true;
    right_table_name_transferred = true;
    plan_left_table_name_transferred = true;
    plan_right_table_name_transferred = true;
    return .{
        .left_table_name = left_table_name,
        .right_table_name = right_table_name,
        .plan = .{
            .left_table = plan_left_table_name,
            .right_table = plan_right_table_name,
            .lateral = .{
                .left = .{
                    .predicates = left_owned_predicates,
                    .json_contains = left_owned_json_contains,
                    .json_path_exists = left_owned_json_path_exists,
                    .array_contains = left_owned_array_contains,
                    .array_eq = left_owned_array_eq,
                    .in_predicates = left_owned_in_predicates,
                    .text_patterns = left_owned_text_patterns,
                    .expression_predicates = left_owned_expression_predicates,
                    .expression_or_predicates = left_owned_expression_or_predicates,
                    .expression_not_predicates = left_owned_expression_not_predicates,
                    .expression_array_contains = left_owned_expression_array_contains,
                    .select_all = true,
                },
                .right = .{
                    .predicates = right_predicates,
                    .json_contains = right_json_contains,
                    .json_path_exists = right_json_path_exists,
                    .array_contains = right_array_contains,
                    .array_eq = right_array_eq,
                    .in_predicates = right_in_predicates,
                    .text_patterns = right_text_patterns,
                    .expression_predicates = right_expression_predicates,
                    .expression_or_predicates = right_expression_or_predicates,
                    .expression_not_predicates = right_expression_not_predicates,
                    .expression_array_contains = right_expression_array_contains,
                    .select_all = true,
                    .order_by = right_order_by,
                    .limit = right_limit,
                    .offset = right_offset,
                },
                .correlations = correlations,
                .match_expression_predicates = match_owned_expression_predicates,
                .match_expression_or_predicates = match_owned_expression_or_predicates,
                .match_expression_not_predicates = match_owned_expression_not_predicates,
                .match_expression_array_contains = match_owned_expression_array_contains,
                .select = select_owned,
                .order_by = order_owned,
                .limit = limit,
                .offset = offset,
            },
        },
    };
}

pub fn parseQueryPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    cte_hooks: plan_mod.CteSelectParserHooks,
    query_hooks: QueryPlanParserHooks,
    tail_hooks: plan_mod.SimpleSelectSetTailHooks,
) !plan_mod.LoweredQueryPlan {
    if (!parser.peekKeyword(tokens, pos.*, "with")) {
        var lowered = try parseQueryPlanSelectWithContext(query_hooks, &.{}, true, false);
        errdefer lowered.deinit(alloc);
        var parsed_set_operation = false;
        while (grammar.nextIsSelectSetOperationKeyword(tokens, pos.*)) {
            parsed_set_operation = true;
            if (lowered.ctes.len != 0) return error.UnsupportedSqlShape;
            const generated_op = try parseGeneratedSelectSetOperation(tokens, pos, generated_read_ast);
            const op = generated_op orelse try grammar.parseSelectSetOperation(tokens, pos);
            var rhs = try parseQueryPlanSelectWithContext(query_hooks, &.{}, true, true);
            defer rhs.deinit(alloc);
            if (rhs.ctes.len != 0) return error.UnsupportedSqlShape;
            if (lowered.system_time_as_of_sequence != null or rhs.system_time_as_of_sequence != null or
                lowered.system_time_as_of_timestamp_ns != null or rhs.system_time_as_of_timestamp_ns != null) return error.UnsupportedSqlShape;
            try select_set.applySimpleSelectSetOperationAlloc(alloc, &lowered, rhs, op);
        }
        if (parsed_set_operation and !parser.atEnd(tokens, pos.*)) {
            try plan_mod.parseSimpleSelectSetResultTailAlloc(alloc, tokens, pos, params, generated_read_ast, &lowered, tail_hooks);
        }
        if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        var base_table_name: ?[]const u8 = null;
        defer if (base_table_name) |table| alloc.free(table);
        if (lowered.ctes.len != 0) try plan_mod.resolveSelectSourceForPlanAlloc(alloc, &lowered, lowered.ctes, &base_table_name);
        const table_name = if (lowered.ctes.len != 0) blk: {
            const base = base_table_name orelse return error.UnsupportedSqlShape;
            base_table_name = null;
            alloc.free(lowered.table_name);
            lowered.table_name = "";
            break :blk base;
        } else blk: {
            const table = lowered.table_name;
            lowered.table_name = "";
            break :blk table;
        };
        const ctes = lowered.ctes;
        const system_time_as_of_sequence = lowered.system_time_as_of_sequence;
        const system_time_as_of_timestamp_ns = lowered.system_time_as_of_timestamp_ns;
        lowered.ctes = &.{};
        lowered.clearSelectOutputs(alloc);
        return .{
            .table_name = table_name,
            .plan = .{
                .ctes = ctes,
                .query = lowered.query,
            },
            .system_time_as_of_sequence = system_time_as_of_sequence,
            .system_time_as_of_timestamp_ns = system_time_as_of_timestamp_ns,
        };
    }

    var base_table_name: ?[]const u8 = null;
    defer if (base_table_name) |table| alloc.free(table);
    const ctes = try plan_mod.parseCtesForPlanAlloc(alloc, tokens, pos, &base_table_name, cte_hooks);
    var ctes_transferred = false;
    errdefer if (!ctes_transferred) plan_mod.freePlanCtes(alloc, ctes);

    var final = try parseQueryPlanSelectWithContext(query_hooks, ctes, true, false);
    errdefer final.deinit(alloc);
    try plan_mod.resolveSelectSourceForPlanAlloc(alloc, &final, ctes, &base_table_name);
    var parsed_set_operation = false;
    while (grammar.nextIsSelectSetOperationKeyword(tokens, pos.*)) {
        parsed_set_operation = true;
        const generated_op = try parseGeneratedSelectSetOperation(tokens, pos, generated_read_ast);
        const op = generated_op orelse try grammar.parseSelectSetOperation(tokens, pos);
        var rhs = try parseQueryPlanSelectWithContext(query_hooks, ctes, true, true);
        defer rhs.deinit(alloc);
        try plan_mod.resolveSelectSourceForPlanAlloc(alloc, &rhs, ctes, &base_table_name);
        if (final.system_time_as_of_sequence != null or rhs.system_time_as_of_sequence != null or
            final.system_time_as_of_timestamp_ns != null or rhs.system_time_as_of_timestamp_ns != null) return error.UnsupportedSqlShape;
        try select_set.applySimpleSelectSetOperationAlloc(alloc, &final, rhs, op);
    }
    if (parsed_set_operation and !parser.atEnd(tokens, pos.*)) {
        try plan_mod.parseSimpleSelectSetResultTailAlloc(alloc, tokens, pos, params, generated_read_ast, &final, tail_hooks);
    }
    if (parser.matchToken(tokens, pos, .semicolon) != null and !parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
    if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;

    const table_name = base_table_name orelse return error.UnsupportedSqlShape;
    const system_time_as_of_sequence = final.system_time_as_of_sequence;
    const system_time_as_of_timestamp_ns = final.system_time_as_of_timestamp_ns;
    base_table_name = null;
    alloc.free(final.table_name);
    final.table_name = "";
    final.clearSelectOutputs(alloc);
    ctes_transferred = true;
    return .{
        .table_name = table_name,
        .plan = .{
            .ctes = ctes,
            .query = final.query,
        },
        .system_time_as_of_sequence = system_time_as_of_sequence,
        .system_time_as_of_timestamp_ns = system_time_as_of_timestamp_ns,
    };
}

fn parseGeneratedSelectSetOperation(
    tokens: []const Token,
    pos: *usize,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !?ast.SelectSetOperation {
    const read = generated_read_ast orelse return null;
    const range = read.set_operation_tokens orelse return error.UnsupportedSqlShape;
    if (range.start != pos.*) {
        if (pos.* > range.start and pos.* < range.end) return null;
        return error.UnsupportedSqlShape;
    }
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    const operator_tokens = read.set_operation.operator_tokens orelse return error.UnsupportedSqlShape;
    if (operator_tokens.start != range.start or operator_tokens.end != operator_tokens.start + 1 or operator_tokens.end > range.end) return error.UnsupportedSqlShape;
    const right_query = read.set_operation.right_query_tokens orelse return error.UnsupportedSqlShape;
    if (right_query.start < operator_tokens.end or right_query.end > range.end) return error.UnsupportedSqlShape;
    if (!tokens[right_query.start].matchesKeywordTag(.select)) return error.UnsupportedSqlShape;

    const op: ast.SelectSetOperation = switch (read.set_operation.kind orelse return error.UnsupportedSqlShape) {
        .@"union" => blk: {
            if (!tokens[operator_tokens.start].matchesKeywordTag(.@"union")) return error.UnsupportedSqlShape;
            if (read.set_operation.all_tokens) |all_tokens| {
                if (all_tokens.start != operator_tokens.end or all_tokens.end != all_tokens.start + 1 or all_tokens.end != right_query.start) return error.UnsupportedSqlShape;
                if (!tokens[all_tokens.start].matchesKeywordTag(.all)) return error.UnsupportedSqlShape;
                break :blk .union_all;
            }
            if (right_query.start == operator_tokens.end) break :blk .union_distinct;
            if (right_query.start == operator_tokens.end + 1 and tokens[operator_tokens.end].matchesKeywordTag(.distinct)) break :blk .union_distinct;
            return error.UnsupportedSqlShape;
        },
        .intersect => blk: {
            if (!tokens[operator_tokens.start].matchesKeywordTag(.intersect) or read.set_operation.all_tokens != null) return error.UnsupportedSqlShape;
            if (right_query.start == operator_tokens.end) break :blk .intersect;
            if (right_query.start == operator_tokens.end + 1 and tokens[operator_tokens.end].matchesKeywordTag(.distinct)) break :blk .intersect;
            return error.UnsupportedSqlShape;
        },
        .except => blk: {
            if (!tokens[operator_tokens.start].matchesKeywordTag(.except) or read.set_operation.all_tokens != null) return error.UnsupportedSqlShape;
            if (right_query.start == operator_tokens.end) break :blk .except;
            if (right_query.start == operator_tokens.end + 1 and tokens[operator_tokens.end].matchesKeywordTag(.distinct)) break :blk .except;
            return error.UnsupportedSqlShape;
        },
    };
    pos.* = right_query.start;
    return op;
}

fn parseQueryPlanSelectWithContext(
    hooks: QueryPlanParserHooks,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    allow_select_set_boundary: bool,
    allow_select_set_result_tail_boundary: bool,
) !plan_mod.LoweredSelect {
    const previous_context = hooks.context_hooks.get_context(hooks.context_hooks.ptr);
    var context = previous_context;
    context.available_ctes = available_ctes;
    context.allow_select_set_boundary = allow_select_set_boundary;
    context.allow_select_set_result_tail_boundary = allow_select_set_result_tail_boundary;
    hooks.context_hooks.set_context(hooks.context_hooks.ptr, context);
    defer hooks.context_hooks.set_context(hooks.context_hooks.ptr, previous_context);

    return try hooks.parse_select(hooks.ptr);
}

fn stringSlicesEqual(a: []const []const u8, b: []const []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (!std.mem.eql(u8, left, right)) return false;
    }
    return true;
}

fn stringSlicesContains(values: []const []const u8, value: []const u8) bool {
    for (values) |candidate| {
        if (std.mem.eql(u8, candidate, value)) return true;
    }
    return false;
}

fn stringSlicesIntersect(a: []const []const u8, b: []const []const u8) bool {
    for (a) |value| {
        if (stringSlicesContains(b, value)) return true;
    }
    return false;
}

pub fn peekUnsupportedSimpleFieldTail(tokens: []const Token, pos: usize) bool {
    return parser.peekKind(tokens, pos, .lparen) or expr_operator.peekJsonExtractOperator(tokens, pos);
}

pub fn parseSimpleReturningFieldOwnedAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
) ![]const u8 {
    const field = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
    errdefer alloc.free(field);
    if (peekUnsupportedSimpleFieldTail(tokens, pos.*)) return error.UnsupportedSqlShape;
    if (binder.relationalColumnForReturningField(schema, field) == null) return error.InvalidSqlCatalog;
    return field;
}

pub fn parseGroupByAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    group_by: *std.ArrayListUnmanaged([]const u8),
) !void {
    while (true) {
        const field = try expr_generated.parseRowExpressionFieldOwnedAlloc(
            alloc,
            tokens,
            pos,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        );
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        if (peekUnsupportedSimpleFieldTail(tokens, pos.*)) return error.UnsupportedSqlShape;
        if (binder.relationalColumnForField(schema, field, null) == null) return error.InvalidSqlCatalog;
        try group_by.append(alloc, field);
        field_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
}

pub fn parseReturningListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
) ![]const []const u8 {
    if (parser.matchToken(tokens, pos, .star) != null) {
        const fields = try alloc.alloc([]const u8, 1);
        errdefer alloc.free(fields);
        fields[0] = try alloc.dupe(u8, "*");
        return fields;
    }

    var fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (fields.items) |field| alloc.free(field);
        fields.deinit(alloc);
    }
    while (true) {
        const field = try parseSimpleReturningFieldOwnedAlloc(alloc, tokens, pos, schema);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        try fields.append(alloc, field);
        field_transferred = true;
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }
    return try fields.toOwnedSlice(alloc);
}

pub fn parseCoalesceFieldOperandOrNullOwnedAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
) !?db_mod.types.RelationalRowsCoalesceOperand {
    if (!parser.peekKind(tokens, pos.*, .identifier) or
        parser.peekKeywordTag(tokens, pos.*, .null) or
        parser.peekKeywordTag(tokens, pos.*, .true) or
        parser.peekKeywordTag(tokens, pos.*, .false))
    {
        return null;
    }

    const field = try expr_generated.parseRowExpressionFieldOwnedAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    errdefer alloc.free(field);
    if (parser.peekKind(tokens, pos.*, .lparen)) return error.UnsupportedSqlShape;
    if (binder.relationalColumnForField(schema, field, null) == null) return error.InvalidSqlCatalog;
    return .{ .kind = .field, .field = field };
}

pub fn parseArrayFieldOwnedAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
) ![]const u8 {
    const field = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
    errdefer alloc.free(field);
    _ = binder.relationalColumnForField(schema, field, .array) orelse return error.InvalidSqlCatalog;
    return field;
}

pub fn parseRowExpressionArrayFieldOwnedAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
) ![]const u8 {
    const parsed_field = try parseIdentifierOwnedAlloc(alloc, tokens, pos);
    defer alloc.free(parsed_field);
    const field = try binder.normalizeRowExpressionFieldAlloc(
        alloc,
        schema,
        parsed_field,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    errdefer alloc.free(field);
    _ = binder.relationalColumnForField(schema, field, .array) orelse return error.InvalidSqlCatalog;
    return field;
}

pub fn peekSimpleReturningField(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len or tokens[pos].kind != .identifier) return false;
    if (parser.peekKeyword(tokens, pos, "lower") or
        parser.peekKeyword(tokens, pos, "upper") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsInitcapFunction) or
        parser.peekKeyword(tokens, pos, "trim") or
        parser.peekKeyword(tokens, pos, "replace") or
        parser.peekKeyword(tokens, pos, "regexp_replace") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction) or
        parser.peekKeyword(tokens, pos, "concat") or
        parser.peekKeyword(tokens, pos, "concat_ws") or
        parser.peekKeyword(tokens, pos, "coalesce") or
        parser.peekKeyword(tokens, pos, "nullif") or
        expr_token.peekTextLengthFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsAsciiFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsChrFunction) or
        expr_token.peekSubstringFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction) or
        expr_token.peekSplitPartFunctionKeyword(tokens, pos) or
        expr_token.peekStrposFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsMd5Function) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTrimVariantFunction) or
        parser.peekKeyword(tokens, pos, "position") or
        parser.peekKeyword(tokens, pos, "abs") or
        parser.peekKeyword(tokens, pos, "round") or
        expr_token.peekFunctionCallTag(tokens, pos, .trunc) or
        expr_token.peekFunctionCallTag(tokens, pos, .floor) or
        expr_token.peekFunctionCallTag(tokens, pos, .ceil) or
        expr_token.peekFunctionCallTag(tokens, pos, .sqrt) or
        expr_token.peekFunctionCallTag(tokens, pos, .sign) or
        expr_token.peekFunctionCallTag(tokens, pos, .mod) or
        expr_token.peekFunctionCallTag(tokens, pos, .power) or
        parser.peekKeyword(tokens, pos, "case") or
        parser.peekKeyword(tokens, pos, "cast"))
    {
        return false;
    }
    if (pos + 1 >= tokens.len) return true;
    if (expr_operator.peekBooleanOperator(tokens, pos + 1) != null) return false;
    return switch (tokens[pos + 1].kind) {
        .plus, .minus, .star, .slash, .percent, .lparen, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .pipe_concat => false,
        else => true,
    };
}

pub fn peekSqlTypedDatetimeLiteral(tokens: []const Token, pos: usize) bool {
    return pos + 1 < tokens.len and
        tokens[pos].kind == .identifier and
        tokens[pos + 1].kind == .string and
        (std.ascii.eqlIgnoreCase(tokens[pos].text, "date") or
            std.ascii.eqlIgnoreCase(tokens[pos].text, "timestamp") or
            std.ascii.eqlIgnoreCase(tokens[pos].text, "timestamptz"));
}

pub fn peekParenthesizedNullTestProjection(tokens: []const Token, pos: usize) bool {
    if (pos + 2 >= tokens.len) return false;
    return tokens[pos].kind == .lparen and
        tokens[pos + 1].kind == .identifier and
        tokens[pos + 2].matchesKeywordTag(.is);
}

pub fn rowExpressionHasTopLevelPipeConcat(tokens: []const Token, pos: usize) bool {
    var depth: usize = 0;
    var i = pos;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
            },
            .pipe_concat => if (depth == 0) return true,
            .comma, .semicolon, .eq, .neq, .lt, .lte, .gt, .gte, .at_contains, .range_overlap, .question, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => if (depth == 0) return false,
            .identifier => if (depth == 0 and expr_token.rowExpressionBoundaryKeywordToken(token)) return false,
            else => {},
        }
    }
    return false;
}

pub fn nextIsAggregateFunction(tokens: []const Token, pos: usize) bool {
    if (pos + 1 >= tokens.len) return false;
    if (tokens[pos].kind != .identifier or tokens[pos + 1].kind != .lparen) return false;
    const name = tokens[pos].text;
    return std.ascii.eqlIgnoreCase(name, "count") or
        std.ascii.eqlIgnoreCase(name, "sum") or
        std.ascii.eqlIgnoreCase(name, "min") or
        std.ascii.eqlIgnoreCase(name, "max") or
        std.ascii.eqlIgnoreCase(name, "avg") or
        std.ascii.eqlIgnoreCase(name, "percentile_cont") or
        std.ascii.eqlIgnoreCase(name, "percentile_disc") or
        std.ascii.eqlIgnoreCase(name, "mode") or
        std.ascii.eqlIgnoreCase(name, "array_agg") or
        std.ascii.eqlIgnoreCase(name, "string_agg") or
        std.ascii.eqlIgnoreCase(name, "bool_or") or
        std.ascii.eqlIgnoreCase(name, "bool_and");
}

pub fn peekWindowFunction(tokens: []const Token, pos: usize) bool {
    return parser.peekKeyword(tokens, pos, "row_number") or
        parser.peekKeyword(tokens, pos, "rank") or
        parser.peekKeyword(tokens, pos, "dense_rank") or
        parser.peekKeyword(tokens, pos, "percent_rank") or
        parser.peekKeyword(tokens, pos, "cume_dist") or
        parser.peekKeyword(tokens, pos, "ntile") or
        parser.peekKeyword(tokens, pos, "lag") or
        parser.peekKeyword(tokens, pos, "lead") or
        parser.peekKeyword(tokens, pos, "first_value") or
        parser.peekKeyword(tokens, pos, "last_value") or
        parser.peekKeyword(tokens, pos, "nth_value") or
        parser.peekKeyword(tokens, pos, "count") or
        parser.peekKeyword(tokens, pos, "sum") or
        parser.peekKeyword(tokens, pos, "avg") or
        parser.peekKeyword(tokens, pos, "min") or
        parser.peekKeyword(tokens, pos, "max") or
        parser.peekKeyword(tokens, pos, "bool_or") or
        parser.peekKeyword(tokens, pos, "bool_and");
}

pub fn peekAggregateExpressionInput(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len) return false;
    if (tokens[pos].kind == .lparen or tokens[pos].kind == .minus) return true;
    if (expr_operator.jsonExtractExpressionCanStartAt(tokens, pos)) return true;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonExtractPathFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonTypeofFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonArrayLengthFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonBuildObjectFunction) or
        value_mod.peekConvertFromFunctionCall(tokens, pos) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayLengthFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayPositionFunction) or
        parser.peekKeyword(tokens, pos, "case") or
        parser.peekKeyword(tokens, pos, "cast") or
        expr_token.peekCoalesceFunctionCall(tokens, pos) or
        expr_token.peekArrayElementTransformFunctionCall(tokens, pos) or
        expr_token.peekArrayToStringFunctionCall(tokens, pos) or
        expr_token.peekStringToArrayFunctionCall(tokens, pos) or
        expr_token.peekCaseFoldFunctionCall(tokens, pos) or
        expr_token.peekConcatFunctionCall(tokens, pos) or
        expr_token.peekReplaceFunctionCall(tokens, pos) or
        expr_token.peekRegexpReplaceFunctionCall(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction) or
        expr_token.peekNullifFunctionCall(tokens, pos) or
        expr_token.peekTextLengthFunctionKeyword(tokens, pos) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .ascii) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .chr) or
        expr_token.peekSubstringFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction) or
        expr_token.peekSplitPartFunctionKeyword(tokens, pos) or
        expr_token.peekStrposFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction) or
        parser.peekKeyword(tokens, pos, "position") or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .abs) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .round) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .trunc) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .floor) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .ceil) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .sqrt) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .sign) or
        expr_token.peekFixedBinaryFunctionCall(tokens, pos, .mod) or
        expr_token.peekFixedBinaryFunctionCall(tokens, pos, .power) or
        expr_token.peekGreatestLeastFunctionCall(tokens, pos))
    {
        return true;
    }
    if (tokens[pos].kind == .identifier and pos + 1 < tokens.len) {
        return switch (tokens[pos + 1].kind) {
            .plus, .minus, .star, .slash, .percent => true,
            else => false,
        };
    }
    return false;
}

pub fn peekAggregateExpressionFilter(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len) return false;
    if (peekParenthesizedExpressionCondition(tokens, pos)) return true;
    if (tokens[pos].kind == .minus) return true;
    if (expr_operator.jsonExtractExpressionCanStartAt(tokens, pos)) return true;
    if (expr_operator.jsonKeySetExpressionCanStartAt(tokens, pos)) return true;
    if (rowExpressionHasTopLevelPipeConcat(tokens, pos)) return true;
    if (parser.peekKeyword(tokens, pos, "lower") or
        parser.peekKeyword(tokens, pos, "upper") or
        parser.peekKeyword(tokens, pos, "trim") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTrimVariantFunction) or
        parser.peekKeyword(tokens, pos, "replace") or
        parser.peekKeyword(tokens, pos, "regexp_replace") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction) or
        parser.peekKeyword(tokens, pos, "case") or
        parser.peekKeyword(tokens, pos, "cast") or
        parser.peekKeyword(tokens, pos, "coalesce") or
        parser.peekKeyword(tokens, pos, "nullif") or
        expr_token.peekTextLengthFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsAsciiFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsChrFunction) or
        expr_token.peekSubstringFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction) or
        expr_token.peekSplitPartFunctionKeyword(tokens, pos) or
        expr_token.peekStrposFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction) or
        parser.peekKeyword(tokens, pos, "position") or
        parser.peekKeyword(tokens, pos, "abs") or
        parser.peekKeyword(tokens, pos, "round") or
        expr_token.peekFunctionCallTag(tokens, pos, .trunc) or
        expr_token.peekFunctionCallTag(tokens, pos, .floor) or
        expr_token.peekFunctionCallTag(tokens, pos, .ceil) or
        expr_token.peekFunctionCallTag(tokens, pos, .sqrt) or
        expr_token.peekFunctionCallTag(tokens, pos, .sign) or
        expr_token.peekFunctionCallTag(tokens, pos, .mod) or
        expr_token.peekFunctionCallTag(tokens, pos, .power) or
        parser.peekKeyword(tokens, pos, "greatest") or
        parser.peekKeyword(tokens, pos, "least") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonExtractPathFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonTypeofFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonArrayLengthFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonBuildObjectFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayLengthFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayPositionFunction) or
        parser.peekKeywordTag(tokens, pos, .now) or
        parser.peekKeywordTag(tokens, pos, .current_timestamp) or
        parser.peekKeywordTag(tokens, pos, .current_date))
    {
        return true;
    }
    if (tokens[pos].kind == .identifier and pos + 1 < tokens.len) {
        return switch (tokens[pos + 1].kind) {
            .plus, .minus, .star, .slash, .percent, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .pipe_concat => true,
            else => false,
        };
    }
    return false;
}

pub fn peekAggregateOutputOrderExpression(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len) return false;
    if (tokens[pos].kind == .lparen or tokens[pos].kind == .minus) return true;
    if (rowExpressionHasTopLevelPipeConcat(tokens, pos)) return true;
    if (parser.peekKeyword(tokens, pos, "lower") or
        parser.peekKeyword(tokens, pos, "upper") or
        parser.peekKeyword(tokens, pos, "trim") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTrimVariantFunction) or
        parser.peekKeyword(tokens, pos, "replace") or
        parser.peekKeyword(tokens, pos, "regexp_replace") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction) or
        parser.peekKeyword(tokens, pos, "concat") or
        parser.peekKeyword(tokens, pos, "concat_ws") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonExtractPathFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonTypeofFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonArrayLengthFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonBuildObjectFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayLengthFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayPositionFunction) or
        parser.peekKeyword(tokens, pos, "array_append") or
        parser.peekKeyword(tokens, pos, "array_prepend") or
        parser.peekKeyword(tokens, pos, "array_cat") or
        parser.peekKeyword(tokens, pos, "array_remove") or
        parser.peekKeyword(tokens, pos, "array_replace") or
        parser.peekKeyword(tokens, pos, "array_to_string") or
        parser.peekKeyword(tokens, pos, "string_to_array") or
        parser.peekKeyword(tokens, pos, "case") or
        parser.peekKeyword(tokens, pos, "cast") or
        parser.peekKeyword(tokens, pos, "coalesce") or
        parser.peekKeyword(tokens, pos, "nullif") or
        expr_token.peekTextLengthFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsAsciiFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsChrFunction) or
        expr_token.peekSubstringFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction) or
        expr_token.peekSplitPartFunctionKeyword(tokens, pos) or
        expr_token.peekStrposFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsMd5Function) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction) or
        parser.peekKeyword(tokens, pos, "position") or
        parser.peekKeyword(tokens, pos, "abs") or
        parser.peekKeyword(tokens, pos, "round") or
        expr_token.peekFunctionCallTag(tokens, pos, .trunc) or
        expr_token.peekFunctionCallTag(tokens, pos, .floor) or
        expr_token.peekFunctionCallTag(tokens, pos, .ceil) or
        expr_token.peekFunctionCallTag(tokens, pos, .sqrt) or
        expr_token.peekFunctionCallTag(tokens, pos, .sign) or
        expr_token.peekFunctionCallTag(tokens, pos, .mod) or
        expr_token.peekFunctionCallTag(tokens, pos, .power) or
        parser.peekKeyword(tokens, pos, "greatest") or
        parser.peekKeyword(tokens, pos, "least"))
    {
        return true;
    }
    if (tokens[pos].kind == .identifier and pos + 1 < tokens.len) {
        return switch (tokens[pos + 1].kind) {
            .plus, .minus, .star, .slash, .percent, .pipe_concat, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text => true,
            else => false,
        };
    }
    return false;
}

pub fn peekGeneralOrderRowExpression(tokens: []const Token, pos: usize) bool {
    return expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonExtractPathFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonTypeofFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonArrayLengthFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonBuildObjectFunction) or
        value_mod.peekToJsonbFunctionCall(tokens, pos) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayLengthFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayPositionFunction) or
        expr_token.peekArrayElementTransformFunctionCall(tokens, pos) or
        expr_token.peekArrayToStringFunctionCall(tokens, pos) or
        expr_token.peekCaseExpressionSyntax(tokens, pos) or
        expr_token.peekCastExpressionSyntax(tokens, pos) or
        expr_token.peekCoalesceFunctionCall(tokens, pos) or
        expr_token.peekRegexpReplaceFunctionCall(tokens, pos) or
        expr_token.peekReplaceFunctionCall(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction) or
        expr_token.peekNullifFunctionCall(tokens, pos) or
        expr_token.peekTextLengthFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsAsciiFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsChrFunction) or
        expr_token.peekSubstringFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction) or
        expr_token.peekSplitPartFunctionKeyword(tokens, pos) or
        expr_token.peekStrposFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsMd5Function) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction) or
        expr_token.peekPositionFunctionSyntax(tokens, pos) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .abs) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .round) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .trunc) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .floor) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .ceil) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .sqrt) or
        expr_token.peekFixedUnaryFunctionCall(tokens, pos, .sign) or
        expr_token.peekFixedBinaryFunctionCall(tokens, pos, .mod) or
        expr_token.peekFixedBinaryFunctionCall(tokens, pos, .power) or
        expr_token.peekGreatestLeastFunctionCall(tokens, pos);
}

pub const OrderExpressionStart = enum {
    parenthesized_null_test,
    parenthesized,
    pipe_concat,
    json_extract_field,
    generated_or_case_fold,
    generated_or_md5,
    generated_or_concat,
    general,
    unary_negative,
    field,
};

pub fn orderExpressionStartAt(tokens: []const Token, pos: usize) OrderExpressionStart {
    if (peekParenthesizedNullTestProjection(tokens, pos)) return .parenthesized_null_test;
    if (expr_token.peekParenthesizedExpressionSyntax(tokens, pos)) return .parenthesized;
    if (rowExpressionHasTopLevelPipeConcat(tokens, pos)) return .pipe_concat;
    if (pos < tokens.len and tokens[pos].kind == .identifier and pos + 1 < tokens.len and expr_operator.tokenKindIsJsonExtractOperator(tokens[pos + 1].kind)) return .json_extract_field;
    if (expr_token.peekCaseFoldFunctionCall(tokens, pos)) return .generated_or_case_fold;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsMd5Function)) return .generated_or_md5;
    if (expr_token.peekConcatFunctionCall(tokens, pos)) return .generated_or_concat;
    if (peekGeneralOrderRowExpression(tokens, pos)) return .general;
    if (expr_token.peekUnaryNegativeExpressionSyntax(tokens, pos)) return .unary_negative;
    return .field;
}

pub fn parseOrderExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    function_bindings: expr_row_parse.SqlFunctionBindings,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    type_context: expr_type.RowExpressionTypeContext,
    options: OrderExpressionParserOptions,
) !db_mod.types.RelationalRowsQueryOrder {
    if (expr_row_parse.peekExtensionFunctionCall(tokens, pos.*, function_bindings.extension_functions) or
        expr_row_parse.peekRoutineExpressionCall(tokens, pos.*, function_bindings.routine_expressions))
    {
        if (options.generated_expression_ast) |generated_expression| {
            if (generated_expression.kind != .function_call) return error.UnsupportedSqlShape;
        }
        const expression_start = pos.*;
        const expression = try expr_row_parse.parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        try expr_generated_validate.validateGeneratedRowExpressionIdentity(
            tokens,
            expression_start,
            pos.*,
            expression,
            options.generated_expression_ast,
        );
        try type_context.validateOrderableRowExpression(expression);
        expression_transferred = true;
        return .{ .expression = expression };
    }

    const start = orderExpressionStartAt(tokens, pos.*);
    try validateGeneratedOrderExpressionStartForExpression(tokens, start, options.generated_expression_ast);
    switch (start) {
        .parenthesized_null_test => {
            _ = parser.matchToken(tokens, pos, .lparen) orelse unreachable;
            const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
            defer alloc.free(parsed_field);
            const field = try binder.normalizeRowExpressionFieldAlloc(alloc, schema, parsed_field, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            if (binder.relationalColumnForField(schema, field, null) == null) return error.InvalidSqlCatalog;
            try parser.expectKeyword(tokens, pos, "is");
            const null_test: db_mod.types.RelationalRowsQueryOrderNullTest = if (parser.matchKeyword(tokens, pos, "not")) blk: {
                try parser.expectKeyword(tokens, pos, "null");
                break :blk .is_not_null;
            } else blk: {
                try parser.expectKeyword(tokens, pos, "null");
                break :blk .is_null;
            };
            try parser.expectToken(tokens, pos, .rparen);
            field_transferred = true;
            var order = try orderForOwnedFieldAlloc(alloc, schema, field);
            order.null_test = null_test;
            return order;
        },
        .parenthesized => {
            const expression_start = pos.*;
            const expression = try expr_row_parse.parseParenthesizedRowExpressionAlloc(alloc, tokens, pos, options.parenthesized);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(alloc, expression);
            try expr_generated_validate.validateGeneratedRowExpressionIdentity(
                tokens,
                expression_start,
                pos.*,
                expression,
                options.generated_expression_ast,
            );
            try type_context.validateOrderableRowExpression(expression);
            expression_transferred = true;
            return .{ .expression = expression };
        },
        .pipe_concat => {
            const expression_start = pos.*;
            const expression = try expr_row_parse.parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(alloc, expression);
            try expr_generated_validate.validateGeneratedRowExpressionIdentity(
                tokens,
                expression_start,
                pos.*,
                expression,
                options.generated_expression_ast,
            );
            try type_context.validateTextRowExpression(expression);
            expression_transferred = true;
            return .{ .expression = expression };
        },
        .json_extract_field, .generated_or_concat, .general => {
            if (try expr_generated.parseGeneratedFieldExpressionOrNullOwnedAlloc(
                alloc,
                tokens,
                pos,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
            )) |field| return try orderForOwnedFieldAlloc(alloc, schema, field);
            const expression_start = pos.*;
            const expression = try expr_row_parse.parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(alloc, expression);
            try expr_generated_validate.validateGeneratedRowExpressionIdentity(
                tokens,
                expression_start,
                pos.*,
                expression,
                options.generated_expression_ast,
            );
            try type_context.validateOrderableRowExpression(expression);
            expression_transferred = true;
            return .{ .expression = expression };
        },
        .generated_or_case_fold => {
            if (try expr_generated.parseGeneratedFieldExpressionOrNullOwnedAlloc(
                alloc,
                tokens,
                pos,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
            )) |field| return try orderForOwnedFieldAlloc(alloc, schema, field);
            const expression_start = pos.*;
            const expression = try expr_row_parse.parseCaseFoldRowExpressionAlloc(
                alloc,
                tokens,
                pos,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                options.field_source,
                type_context,
                options.case_fold_hooks,
            );
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(alloc, expression);
            try expr_generated_validate.validateGeneratedRowExpressionIdentity(
                tokens,
                expression_start,
                pos.*,
                expression,
                options.generated_expression_ast,
            );
            if (expression.kind == .field and expression.field.len != 0) {
                expression_transferred = true;
                return try orderForOwnedFieldAlloc(alloc, schema, expression.field);
            }
            expression_transferred = true;
            return .{ .expression = expression };
        },
        .generated_or_md5 => {
            if (try expr_generated.parseGeneratedFieldExpressionOrNullOwnedAlloc(
                alloc,
                tokens,
                pos,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
            )) |field| return .{ .field = field };
            const expression_start = pos.*;
            const expression = try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .md5, type_context, .text, options.fixed_unary);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(alloc, expression);
            try expr_generated_validate.validateGeneratedRowExpressionIdentity(
                tokens,
                expression_start,
                pos.*,
                expression,
                options.generated_expression_ast,
            );
            expression_transferred = true;
            return .{ .expression = expression };
        },
        .unary_negative => {
            const expression_start = pos.*;
            const expression = try expr_row_parse.parseRowExpressionAlloc(alloc, tokens, pos, type_context, options.row_expression_hooks, options.arithmetic_hooks, options.variadic_hooks);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(alloc, expression);
            try expr_generated_validate.validateGeneratedRowExpressionIdentity(
                tokens,
                expression_start,
                pos.*,
                expression,
                options.generated_expression_ast,
            );
            try type_context.validateNumericRowExpression(expression);
            expression_transferred = true;
            return .{ .expression = expression };
        },
        .field => {},
    }

    const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    defer alloc.free(parsed_field);
    const field = try binder.normalizeRowExpressionFieldAlloc(alloc, schema, parsed_field, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
    if (expr_operator.peekArithmeticOperator(tokens, pos.*)) |_| {
        if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
        field_transferred = true;
        const expression_start = pos.* - 1;
        const expression = try expr_row_parse.parseArithmeticExpressionRestAlloc(alloc, tokens, pos, .{ .kind = .field, .field = field }, 0, type_context, options.arithmetic_hooks);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(alloc, expression);
        try expr_generated_validate.validateGeneratedRowExpressionIdentity(
            tokens,
            expression_start,
            pos.*,
            expression,
            options.generated_expression_ast,
        );
        try type_context.validateNumericRowExpression(expression);
        expression_transferred = true;
        return .{ .expression = expression };
    }
    field_transferred = true;
    return try orderForOwnedFieldAlloc(alloc, schema, field);
}

fn orderForOwnedFieldAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    field: []const u8,
) !db_mod.types.RelationalRowsQueryOrder {
    errdefer alloc.free(field);
    const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
    const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
    errdefer if (collation) |value| alloc.free(value);
    return .{
        .field = field,
        .collation = collation,
    };
}

pub fn parseCaseExpressionConditionWithSelectSchemaAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    context_hooks: SelectParserContextHooks,
    hooks: expr_row_parse.CaseExpressionParserHooks,
) !db_mod.types.RelationalRowsExpressionCondition {
    return try parseCaseExpressionConditionWithSelectSchemaAndOperatorAlloc(
        alloc,
        tokens,
        pos,
        schema,
        context_hooks,
        hooks,
        null,
    );
}

fn parseCaseExpressionConditionWithSelectSchemaAndOperatorAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    context_hooks: SelectParserContextHooks,
    hooks: expr_row_parse.CaseExpressionParserHooks,
    operator_token_index: ?*usize,
) !db_mod.types.RelationalRowsExpressionCondition {
    const previous_context = context_hooks.get_context(context_hooks.ptr);
    var context = previous_context;
    context.schema = schema;
    context_hooks.set_context(context_hooks.ptr, context);
    defer context_hooks.set_context(context_hooks.ptr, previous_context);

    return try expr_row_parse.parseCaseExpressionConditionWithOperatorAlloc(
        alloc,
        tokens,
        pos,
        context_hooks.row_expression_type_context(context_hooks.ptr),
        context.defer_row_expression_field_validation,
        hooks,
        operator_token_index,
    );
}

pub fn parseBareBooleanWhereExpressionWithSelectSchemaAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
    context_hooks: SelectParserContextHooks,
    options: BareBooleanWhereExpressionParserOptions,
) !void {
    const previous_context = context_hooks.get_context(context_hooks.ptr);
    var context = previous_context;
    context.schema = schema;
    context_hooks.set_context(context_hooks.ptr, context);
    defer context_hooks.set_context(context_hooks.ptr, previous_context);

    return try parseBareBooleanWhereExpressionAlloc(
        alloc,
        tokens,
        pos,
        context_hooks.row_expression_type_context(context_hooks.ptr),
        expression_predicates,
        options,
    );
}

pub fn parseOrderExpressionWithSelectSchemaAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    function_bindings: expr_row_parse.SqlFunctionBindings,
    context_hooks: SelectParserContextHooks,
    hooks: OrderExpressionParserOptions,
) !db_mod.types.RelationalRowsQueryOrder {
    const previous_context = context_hooks.get_context(context_hooks.ptr);
    var context = previous_context;
    context.schema = schema;
    context_hooks.set_context(context_hooks.ptr, context);
    defer context_hooks.set_context(context_hooks.ptr, previous_context);

    return try parseOrderExpressionAlloc(
        alloc,
        tokens,
        pos,
        context.schema,
        function_bindings,
        context.field_expression_qualifiers,
        context.returning_expression_qualifiers,
        context.defer_row_expression_field_validation,
        context_hooks.row_expression_type_context(context_hooks.ptr),
        hooks,
    );
}

