    trunc,
    floor,
    ceil,
    sqrt,
    sign,
    mod,
    power,
    greatest_least,
    case,
    cast,
    parenthesized,
};

pub const SelectFieldItemParserOptions = struct {
    type_context: expr_type.RowExpressionTypeContext,
    arithmetic_hooks: expr_row_parse.ArithmeticExpressionParserHooks,
    boolean_hooks: expr_row_parse.BooleanExpressionParserHooks,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst = null,
    require_exact_generated_expression: bool = false,
};

pub const SelectItemParserOptions = struct {
    expression: expr_projection.ExpressionProjectionParserOptions,
    json_value_expression: expr_projection.JsonValueExpressionProjectionParserOptions,
    select_field: SelectFieldItemParserOptions,
    extension_function: expr_row_parse.ExtensionFunctionRowExpressionParserOptions,
    routine_expression: expr_row_parse.RoutineExpressionRowExpressionParserOptions,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst = null,
    require_exact_generated_expression: bool = false,
};

pub const SelectListParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    output_schema: runtime_schema.TableSchema,
    select_item_schema: runtime_schema.TableSchema,
    function_bindings: expr_row_parse.SqlFunctionBindings = .{},
    type_context: expr_type.RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8 = &.{},
    returning_expression_qualifiers: []const []const u8 = &.{},
    defer_row_expression_field_validation: bool = false,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource = .row,
    select_item_options: SelectItemParserOptions,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst = null,
    allow_generated_projection_fallback: bool = false,
};

pub const ReturningSelectItemParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    function_bindings: expr_row_parse.SqlFunctionBindings = .{},
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    context_hooks: SelectParserContextHooks,
    select_item_options: SelectItemParserOptions,
};

pub fn parseReturningSelectItemWithQualifiersAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    returning_qualifiers: []const []const u8,
    options: ReturningSelectItemParserOptions,
) !plan_mod.SelectItem {
    const previous_context = options.context_hooks.get_context(options.context_hooks.ptr);
    var context = previous_context;
    context.field_expression_qualifiers = returning_qualifiers;
    context.returning_expression_qualifiers = returning_qualifiers;
    options.context_hooks.set_context(options.context_hooks.ptr, context);
    defer options.context_hooks.set_context(options.context_hooks.ptr, previous_context);

    const current_context = options.context_hooks.get_context(options.context_hooks.ptr);
    return try parseSelectItemAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        current_context.schema,
        options.function_bindings,
        current_context.field_expression_qualifiers,
        current_context.returning_expression_qualifiers,
        current_context.defer_row_expression_field_validation,
        options.field_source,
        options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
        options.select_item_options,
    );
}

pub const JoinedReturningSelectItemParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    function_bindings: expr_row_parse.SqlFunctionBindings = .{},
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    select_context_hooks: SelectParserContextHooks,
    joined_context_hooks: JoinedExpressionParserContextHooks,
    select_item_options: SelectItemParserOptions,
};

pub fn parseJoinedReturningSelectItemWithQualifiersAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    source_alias: []const u8,
    returning_qualifiers: []const []const u8,
    options: JoinedReturningSelectItemParserOptions,
) !plan_mod.SelectItem {
    const previous_select_context = options.select_context_hooks.get_context(options.select_context_hooks.ptr);
    const previous_joined_context = options.joined_context_hooks.get_context(options.joined_context_hooks.ptr);
    const source_qualifiers = [_][]const u8{source_alias};

    var select_context = previous_select_context;
    select_context.field_expression_qualifiers = returning_qualifiers;
    select_context.returning_expression_qualifiers = returning_qualifiers;
    select_context.defer_row_expression_field_validation = true;
    options.select_context_hooks.set_context(options.select_context_hooks.ptr, select_context);
    defer options.select_context_hooks.set_context(options.select_context_hooks.ptr, previous_select_context);

    var joined_context = previous_joined_context;
    joined_context.joined_target_expression_qualifiers = returning_qualifiers;
    joined_context.joined_source_expression_qualifiers = source_qualifiers[0..];
    joined_context.defer_row_expression_field_validation = true;
    options.joined_context_hooks.set_context(options.joined_context_hooks.ptr, joined_context);
    defer options.joined_context_hooks.set_context(options.joined_context_hooks.ptr, previous_joined_context);

    const current_context = options.select_context_hooks.get_context(options.select_context_hooks.ptr);
    return try parseSelectItemAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        current_context.schema,
        options.function_bindings,
        current_context.field_expression_qualifiers,
        current_context.returning_expression_qualifiers,
        current_context.defer_row_expression_field_validation,
        options.field_source,
        options.select_context_hooks.row_expression_type_context(options.select_context_hooks.ptr),
        options.select_item_options,
    );
}

pub const WindowSelectListParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    schema: runtime_schema.TableSchema,
    type_context: expr_type.RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8 = &.{},
    returning_expression_qualifiers: []const []const u8 = &.{},
    defer_row_expression_field_validation: bool = false,
    named_window_specs: []const plan_mod.NamedWindowSpec = &.{},
    function_bindings: expr_row_parse.SqlFunctionBindings = .{},
    order_expression_hooks: OrderExpressionParserOptions,
    window_definition_options: WindowDefinitionParserOptions,
    window_spec_options: WindowSpecParserOptions,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst = null,
};

pub fn selectItemStartAt(tokens: []const Token, pos: usize) ?SelectItemStart {
    if (rowExpressionHasTopLevelPipeConcat(tokens, pos)) return .pipe_concat;
    if (expr_token.peekUnaryNegativeExpressionSyntax(tokens, pos)) return .unary_negative;
    if (expr_token.peekBooleanNotExpressionSyntax(tokens, pos)) return .boolean_not;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsUuidV4Function)) return .uuid_v4;
    if (expr_token.peekSqlNowExpressionSyntax(tokens, pos)) return .now;
    if (expr_token.peekSqlCurrentDateExpressionSyntax(tokens, pos)) return .current_date;
    if (peekSqlTypedDatetimeLiteral(tokens, pos)) return .typed_datetime_literal;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonExtractPathFunction)) return .json_extract_path;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonTypeofFunction)) return .json_typeof;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonArrayLengthFunction)) return .json_array_length;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonBuildObjectFunction)) return .json_build_object;
    if (value_mod.peekConvertFromFunctionCall(tokens, pos)) return .convert_from;
    if (value_mod.peekToJsonbFunctionCall(tokens, pos)) return .to_jsonb;
    if (expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayLengthFunction)) return .array_length;
    if (expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayPositionFunction)) return .array_position;
    if (expr_token.peekArrayElementTransformFunctionCall(tokens, pos)) return .array_element_transform;
    if (expr_token.peekArrayToStringFunctionCall(tokens, pos)) return .array_to_string;
    if (expr_token.peekStringToArrayFunctionCall(tokens, pos)) return .string_to_array;
    if (expr_token.peekCoalesceFunctionCall(tokens, pos)) return .coalesce;
    if (expr_token.peekCaseFoldFunctionCall(tokens, pos)) return .case_fold;
    if (expr_token.peekReplaceFunctionCall(tokens, pos)) return .replace;
    if (expr_token.peekRegexpReplaceFunctionCall(tokens, pos)) return .regexp_replace;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction)) return .regexp_substr;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction)) return .regexp_match;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction)) return .regexp_count;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction)) return .regexp_instr;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction)) return .translate;
    if (expr_token.peekConcatFunctionCall(tokens, pos)) return .concat;
    if (expr_token.peekNullifFunctionCall(tokens, pos)) return .nullif;
    if (expr_token.peekTextLengthFunctionKeyword(tokens, pos)) return .text_length;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsAsciiFunction)) return .ascii;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsChrFunction)) return .chr;
    if (expr_token.peekSubstringFunctionKeyword(tokens, pos)) return .substring;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction)) return .overlay;
    if (expr_token.peekSplitPartFunctionKeyword(tokens, pos)) return .split_part;
    if (expr_token.peekStrposFunctionKeyword(tokens, pos) or expr_token.peekPositionFunctionSyntax(tokens, pos)) return .strpos;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction)) return .left_right;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction)) return .pad;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction)) return .repeat;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction)) return .reverse;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsMd5Function)) return .md5;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction)) return .starts_with;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction)) return .ends_with;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction)) return .date_trunc;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction)) return .date_bin;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction)) return .date_part;
    if (expr_token.peekFixedUnaryFunctionCall(tokens, pos, .abs)) return .abs;
    if (expr_token.peekFixedUnaryFunctionCall(tokens, pos, .round)) return .round;
    if (expr_token.peekFixedUnaryFunctionCall(tokens, pos, .trunc)) return .trunc;
    if (expr_token.peekFixedUnaryFunctionCall(tokens, pos, .floor)) return .floor;
    if (expr_token.peekFixedUnaryFunctionCall(tokens, pos, .ceil)) return .ceil;
    if (expr_token.peekFixedUnaryFunctionCall(tokens, pos, .sqrt)) return .sqrt;
    if (expr_token.peekFixedUnaryFunctionCall(tokens, pos, .sign)) return .sign;
    if (expr_token.peekFixedBinaryFunctionCall(tokens, pos, .mod)) return .mod;
    if (expr_token.peekFixedBinaryFunctionCall(tokens, pos, .power)) return .power;
    if (expr_token.peekGreatestLeastFunctionCall(tokens, pos)) return .greatest_least;
    if (expr_token.peekCaseExpressionSyntax(tokens, pos)) return .case;
    if (expr_token.peekCastExpressionSyntax(tokens, pos)) return .cast;
    if (expr_token.peekParenthesizedExpressionSyntax(tokens, pos)) return .parenthesized;
    return null;
}

pub fn selectItemStartWithFunctionBindingsAt(tokens: []const Token, pos: usize, bindings: expr_row_parse.SqlFunctionBindings) ?SelectItemStart {
    if (selectItemStartAt(tokens, pos)) |start| return start;
    if (expr_row_parse.peekExtensionFunctionCall(tokens, pos, bindings.extension_functions)) return .extension_function;
    if (expr_row_parse.peekRoutineExpressionCall(tokens, pos, bindings.routine_expressions)) return .routine_expression;
    return null;
}

pub fn parseSelectListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: SelectListParserOptions,
) !plan_mod.SelectList {
    var select_all = false;
    var fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (fields.items) |field| alloc.free(field);
        fields.deinit(alloc);
    }
    var json_extract = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonExtractProjection).empty;
    errdefer {
        for (json_extract.items) |projection| {
            alloc.free(projection.output);
            alloc.free(projection.field);
            alloc.free(projection.path);
        }
        json_extract.deinit(alloc);
    }
    var array_length = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayLengthProjection).empty;
    errdefer {
        for (array_length.items) |projection| {
            alloc.free(projection.output);
            alloc.free(projection.field);
        }
        array_length.deinit(alloc);
    }
    var coalesce = std.ArrayListUnmanaged(db_mod.types.RelationalRowsCoalesceProjection).empty;
    errdefer {
        for (coalesce.items) |projection| plan_mod.freeCoalesceProjection(alloc, projection);
        coalesce.deinit(alloc);
    }
    var expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
    errdefer {
        for (expressions.items) |projection| freeExpressionProjection(alloc, projection);
        expressions.deinit(alloc);
    }
    var field_aliases = std.ArrayListUnmanaged(db_mod.types.RelationalRowsFieldAliasProjection).empty;
    errdefer {
        for (field_aliases.items) |projection| {
            alloc.free(projection.output);
            alloc.free(projection.field);
        }
        field_aliases.deinit(alloc);
    }
    var outputs = std.ArrayListUnmanaged(ast.SelectOutputRef).empty;
    errdefer outputs.deinit(alloc);

    while (true) {
        if (parser.matchToken(tokens, pos, .star) != null) {
            if (select_all or
                fields.items.len != 0 or
                json_extract.items.len != 0 or
                array_length.items.len != 0 or
                coalesce.items.len != 0 or
                field_aliases.items.len != 0 or
                expressions.items.len != 0) return error.UnsupportedSqlShape;
            select_all = true;
            if (parser.matchToken(tokens, pos, .comma) == null) break;
            continue;
        }

        const item_start = pos.*;
        const generated_item = try generatedProjectionItemAtStart(tokens, item_start, options.generated_read_ast);
        if (generated_item == null and options.generated_read_ast != null) {
            if (!options.allow_generated_projection_fallback or !try generatedSetOperationRightQueryEndedBefore(options.generated_read_ast.?, item_start)) return error.UnsupportedSqlShape;
        }
        const generated_expression = if (generated_item) |item| item.expression else null;
        var select_item_options = options.select_item_options;
        select_item_options.generated_expression_ast = generated_expression;
        const item = try parseSelectItemAlloc(
            alloc,
            tokens,
            pos,
            options.params,
            options.select_item_schema,
            options.function_bindings,
            options.field_expression_qualifiers,
            options.returning_expression_qualifiers,
            options.defer_row_expression_field_validation,
            options.field_source,
            options.type_context,
            select_item_options,
        );
        var item_transferred = false;
        errdefer if (!item_transferred) plan_mod.freeSelectItem(alloc, item);
        switch (item) {
            .field => |field| {
                item_transferred = true;
                var field_transferred = false;
                errdefer if (!field_transferred) alloc.free(field);
                if (select_all) {
                    var output: []const u8 = try alloc.dupe(u8, field);
                    var output_transferred = false;
                    errdefer if (!output_transferred) alloc.free(output);
                    try expr_projection.disambiguateSelectProjectionOutputIfNeededAlloc(
                        alloc,
                        options.output_schema,
                        select_all,
                        fields.items,
                        json_extract.items,
                        array_length.items,
                        coalesce.items,
                        field_aliases.items,
                        expressions.items,
                        &output,
                    );
                    try outputs.append(alloc, .{ .kind = .field_alias, .index = field_aliases.items.len });
                    try field_aliases.append(alloc, .{ .field = field, .output = output });
                    field_transferred = true;
                    output_transferred = true;
                } else {
                    try outputs.append(alloc, .{ .kind = .field, .index = fields.items.len });
                    try fields.append(alloc, field);
                    field_transferred = true;
                }
            },
            .json_extract => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) {
                    alloc.free(projection.output);
                    alloc.free(projection.field);
                    alloc.free(projection.path);
                };
                try expr_projection.disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                try outputs.append(alloc, .{ .kind = .json_extract, .index = json_extract.items.len });
                try json_extract.append(alloc, projection);
                projection_transferred = true;
            },
            .array_length => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) {
                    alloc.free(projection.output);
                    alloc.free(projection.field);
                };
                try expr_projection.disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                try outputs.append(alloc, .{ .kind = .array_length, .index = array_length.items.len });
                try array_length.append(alloc, projection);
                projection_transferred = true;
            },
            .coalesce => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) plan_mod.freeCoalesceProjection(alloc, projection);
                try expr_projection.disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                const expression_projection = try plan_mod.expressionProjectionFromCoalesceAlloc(alloc, projection);
                var expression_projection_transferred = false;
                errdefer if (!expression_projection_transferred) freeExpressionProjection(alloc, expression_projection);
                try outputs.append(alloc, .{ .kind = .coalesce, .index = coalesce.items.len });
                try expressions.append(alloc, expression_projection);
                expression_projection_transferred = true;
                try coalesce.append(alloc, projection);
                projection_transferred = true;
            },
            .expression => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) freeExpressionProjection(alloc, projection);
                try expr_projection.disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                try outputs.append(alloc, .{ .kind = .expression, .index = expressions.items.len });
                try expressions.append(alloc, projection);
                projection_transferred = true;
            },
            .field_alias => |projection_value| {
                item_transferred = true;
                var projection = projection_value;
                var projection_transferred = false;
                errdefer if (!projection_transferred) {
                    alloc.free(projection.output);
                    alloc.free(projection.field);
                };
                try expr_projection.disambiguateSelectProjectionOutputIfNeededAlloc(
                    alloc,
                    options.output_schema,
                    select_all,
                    fields.items,
                    json_extract.items,
                    array_length.items,
                    coalesce.items,
                    field_aliases.items,
                    expressions.items,
                    &projection.output,
                );
                try outputs.append(alloc, .{ .kind = .field_alias, .index = field_aliases.items.len });
                try field_aliases.append(alloc, projection);
                projection_transferred = true;
            },
        }
        item_transferred = true;
        try validateGeneratedExpressionItemEnd(generated_item, pos.*);
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }

    try expr_projection.validateSelectListOutputs(
        options.output_schema,
        select_all,
        fields.items,
        json_extract.items,
        array_length.items,
        coalesce.items,
        field_aliases.items,
        expressions.items,
    );

    const owned_fields = try fields.toOwnedSlice(alloc);
    var fields_transferred = false;
    errdefer if (!fields_transferred) strings.freeStringSlice(alloc, owned_fields);
    const owned_json_extract = try json_extract.toOwnedSlice(alloc);
    var json_extract_transferred = false;
    errdefer if (!json_extract_transferred) plan_mod.freeJsonExtract(alloc, owned_json_extract);
    const owned_array_length = try array_length.toOwnedSlice(alloc);
    var array_length_transferred = false;
    errdefer if (!array_length_transferred) plan_mod.freeArrayLengthProjections(alloc, owned_array_length);
    const owned_coalesce = try coalesce.toOwnedSlice(alloc);
    var coalesce_transferred = false;
    errdefer if (!coalesce_transferred) plan_mod.freeCoalesceProjections(alloc, owned_coalesce);
    const owned_field_aliases = try field_aliases.toOwnedSlice(alloc);
    var field_aliases_transferred = false;
    errdefer if (!field_aliases_transferred) plan_mod.freeFieldAliasProjections(alloc, owned_field_aliases);
    const owned_expressions = try expressions.toOwnedSlice(alloc);
    var expressions_transferred = false;
    errdefer if (!expressions_transferred) freeExpressionProjections(alloc, owned_expressions);
    const owned_outputs = try outputs.toOwnedSlice(alloc);

    fields_transferred = true;
    json_extract_transferred = true;
    array_length_transferred = true;
    coalesce_transferred = true;
    field_aliases_transferred = true;
    expressions_transferred = true;
    return .{
        .fields = owned_fields,
        .json_extract = owned_json_extract,
        .array_length = owned_array_length,
        .coalesce = owned_coalesce,
        .field_aliases = owned_field_aliases,
        .expressions = owned_expressions,
        .outputs = owned_outputs,
        .select_all = select_all,
    };
}

fn windowSpecOutputCollision(
    output: []const u8,
    fields: []const []const u8,
    windows: []const db_mod.types.RelationalRowsWindowSpec,
) bool {
    for (fields) |field| {
        if (std.mem.eql(u8, field, output)) return true;
    }
    for (windows) |window| {
        if (std.mem.eql(u8, window.output, output)) return true;
    }
    return false;
}

fn allocateDisambiguatedWindowSpecOutputAlloc(
    alloc: std.mem.Allocator,
    output: []const u8,
    fields: []const []const u8,
    windows: []const db_mod.types.RelationalRowsWindowSpec,
) !?[]const u8 {
    if (!windowSpecOutputCollision(output, fields, windows)) return null;

    var suffix: usize = 2;
    while (true) : (suffix += 1) {
        const candidate = try std.fmt.allocPrint(alloc, "{s}_{d}", .{ output, suffix });
        if (!windowSpecOutputCollision(candidate, fields, windows)) return candidate;
        alloc.free(candidate);
    }
}

fn windowSpecWithOutput(
    spec: db_mod.types.RelationalRowsWindowSpec,
    output: []const u8,
) db_mod.types.RelationalRowsWindowSpec {
    return .{
        .output = output,
        .function = spec.function,
        .partition_by = spec.partition_by,
        .order_by = spec.order_by,
        .value_expression = spec.value_expression,
        .offset = spec.offset,
        .default_json = spec.default_json,
        .frame = spec.frame,
        .filter_predicates = spec.filter_predicates,
        .filter_array_any = spec.filter_array_any,
        .filter_array_contains = spec.filter_array_contains,
        .filter_array_eq = spec.filter_array_eq,
        .filter_in_predicates = spec.filter_in_predicates,
        .filter_json_contains = spec.filter_json_contains,
        .filter_json_path_eq = spec.filter_json_path_eq,
        .filter_json_path_exists = spec.filter_json_path_exists,
        .filter_text_patterns = spec.filter_text_patterns,
        .filter_expressions = spec.filter_expressions,
        .filter_expression_array_contains = spec.filter_expression_array_contains,
        .filter_any = spec.filter_any,
        .filter_not = spec.filter_not,
    };
}

pub fn validateWindowSelectListOutputs(
    fields: []const []const u8,
    windows: []const db_mod.types.RelationalRowsWindowSpec,
) !void {
    for (fields, 0..) |field, i| {
        for (fields[i + 1 ..]) |other| {
            if (std.mem.eql(u8, field, other)) return error.UnsupportedSqlShape;
        }
        for (windows) |window| {
            if (std.mem.eql(u8, field, window.output)) return error.UnsupportedSqlShape;
        }
    }
    for (windows, 0..) |window, i| {
        for (windows[i + 1 ..]) |other| {
            if (std.mem.eql(u8, window.output, other.output)) return error.UnsupportedSqlShape;
        }
    }
}

pub fn parseWindowSelectListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: WindowSelectListParserOptions,
) !plan_mod.WindowSelectList {
    if (parser.matchToken(tokens, pos, .star) != null) return error.UnsupportedSqlShape;

    var fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (fields.items) |field| alloc.free(field);
        fields.deinit(alloc);
    }
    var windows = std.ArrayListUnmanaged(db_mod.types.RelationalRowsWindowSpec).empty;
    errdefer {
        plan_mod.freeWindowSpecs(alloc, windows.items);
        windows.deinit(alloc);
    }
    var outputs = std.ArrayListUnmanaged(plan_mod.WindowSelectOutputRef).empty;
    errdefer outputs.deinit(alloc);

    while (true) {
        const item_start = pos.*;
        const generated_item = try generatedProjectionItemAtStart(tokens, item_start, options.generated_read_ast);
        if (generated_item == null and options.generated_read_ast != null) return error.UnsupportedSqlShape;
        const generated_expression = if (generated_item) |item| item.expression else null;
        const generated_window_function = if (generated_expression) |expression|
            try generatedWindowFunctionForExpression(tokens, expression)
        else
            null;
        const parse_window = if (options.generated_read_ast != null) blk: {
            if (peekWindowFunction(tokens, pos.*) and generated_window_function == null) return error.UnsupportedSqlShape;
            break :blk generated_window_function != null;
        } else peekWindowFunction(tokens, pos.*);

        if (parse_window) {
            var window_spec_options = options.window_spec_options;
            window_spec_options.generated_expression_ast = generated_expression;
            const parsed_spec = try parseWindowSpecAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                options.schema,
                options.field_expression_qualifiers,
                options.returning_expression_qualifiers,
                options.defer_row_expression_field_validation,
                options.type_context,
                options.named_window_specs,
                options.window_definition_options,
                window_spec_options,
            );
            var parsed_spec_transferred = false;
            errdefer if (!parsed_spec_transferred) plan_mod.freeWindowSpec(alloc, parsed_spec);
            const maybe_output = try allocateDisambiguatedWindowSpecOutputAlloc(
                alloc,
                parsed_spec.output,
                fields.items,
                windows.items,
            );
            var output_transferred = false;
            errdefer if (!output_transferred) {
                if (maybe_output) |output| alloc.free(output);
            };
            const spec = if (maybe_output) |output| windowSpecWithOutput(parsed_spec, output) else parsed_spec;
            parsed_spec_transferred = true;
            if (maybe_output != null) {
                alloc.free(parsed_spec.output);
                output_transferred = true;
            }
            var spec_transferred = false;
            errdefer if (!spec_transferred) plan_mod.freeWindowSpec(alloc, spec);
            try validateGeneratedExpressionItemEnd(generated_item, pos.*);
            try outputs.append(alloc, .{ .kind = .window, .index = windows.items.len });
            try windows.append(alloc, spec);
            spec_transferred = true;
        } else {
            if (generated_expression) |expression| {
                if (expression.kind != .token_range) return error.UnsupportedSqlShape;
            }
            const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(
                alloc,
                tokens,
                pos,
                options.schema,
                options.field_expression_qualifiers,
                options.returning_expression_qualifiers,
                options.defer_row_expression_field_validation,
            );
            defer alloc.free(parsed_field);
            const field = try binder.normalizeRowExpressionFieldAlloc(
                alloc,
                options.schema,
                parsed_field,
                options.field_expression_qualifiers,
                options.returning_expression_qualifiers,
                options.defer_row_expression_field_validation,
            );
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            if (peekUnsupportedSimpleFieldTail(tokens, pos.*)) return error.UnsupportedSqlShape;
            if (binder.relationalColumnForField(options.schema, field, null) == null) return error.InvalidSqlCatalog;
            try grammar.consumeProjectionAlias(alloc, tokens, pos, field);
            try validateGeneratedExpressionItemEnd(generated_item, pos.*);
            try outputs.append(alloc, .{ .kind = .field, .index = fields.items.len });
            try fields.append(alloc, field);
            field_transferred = true;
        }
        if (parser.matchToken(tokens, pos, .comma) == null) break;
    }

    try expr_window.validateSelectListOutputs(fields.items, windows.items);

    const owned_fields = try fields.toOwnedSlice(alloc);
    var fields_transferred = false;
    errdefer if (!fields_transferred) strings.freeStringSlice(alloc, owned_fields);
    const owned_windows = try windows.toOwnedSlice(alloc);
    var windows_transferred = false;
    errdefer if (!windows_transferred) {
        plan_mod.freeWindowSpecs(alloc, owned_windows);
        if (owned_windows.len > 0) alloc.free(owned_windows);
    };
    const owned_outputs = try outputs.toOwnedSlice(alloc);

    fields_transferred = true;
    windows_transferred = true;
    return .{
        .fields = owned_fields,
        .windows = owned_windows,
        .outputs = owned_outputs,
        .select_all = false,
    };
}

pub fn parseSelectItemAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    function_bindings: expr_row_parse.SqlFunctionBindings,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    type_context: expr_type.RowExpressionTypeContext,
    base_options: SelectItemParserOptions,
) !plan_mod.SelectItem {
    var options = base_options;
    options.expression.generated_expression_ast = options.generated_expression_ast;
    options.expression.require_exact_generated_expression = options.require_exact_generated_expression;

    if (selectItemStartWithFunctionBindingsAt(tokens, pos.*, function_bindings)) |start| {
        try validateGeneratedSelectItemStartForExpression(tokens, start, options.generated_expression_ast);
        switch (start) {
            .pipe_concat => return .{ .expression = try expr_projection.parseTextExpressionProjectionAlloc(alloc, tokens, pos, type_context, options.expression) },
            .unary_negative => return .{ .expression = try expr_projection.parseGenericExpressionProjectionAlloc(alloc, tokens, pos, type_context, options.expression) },
            .boolean_not => return .{ .expression = try expr_projection.parseBooleanExpressionProjectionAlloc(alloc, tokens, pos, type_context, options.expression) },
            .extension_function => return .{ .expression = try expr_projection.parseExtensionFunctionExpressionProjectionAlloc(alloc, tokens, pos, function_bindings.extension_functions, options.extension_function) },
            .routine_expression => return .{ .expression = try expr_projection.parseRoutineExpressionProjectionAlloc(alloc, tokens, pos, function_bindings.routine_expressions, options.routine_expression) },
            .uuid_v4 => return .{ .expression = try expr_projection.parseUuidV4ExpressionProjectionAlloc(alloc, tokens, pos) },
            .now => return .{ .expression = try expr_projection.parseNowExpressionProjectionAlloc(alloc, tokens, pos) },
            .current_date => return .{ .expression = try expr_projection.parseCurrentDateExpressionProjectionAlloc(alloc, tokens, pos) },
            .typed_datetime_literal => return .{ .expression = try expr_projection.parseTypedDatetimeLiteralExpressionProjectionAlloc(alloc, tokens, pos) },
            .json_extract_path => return .{ .expression = try expr_projection.parseJsonExtractPathExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .json_typeof => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "json_typeof", options.expression) },
            .json_array_length => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "json_array_length", options.expression) },
            .json_build_object => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "jsonb_build_object", options.expression) },
            .convert_from => return .{ .expression = try expr_projection.parseJsonValueExpressionProjectionAlloc(alloc, tokens, pos, "convert_from", options.json_value_expression) },
            .to_jsonb => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "to_jsonb", options.expression) },
            .array_length => return .{ .expression = try parseArrayLengthExpressionProjectionAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, field_source) },
            .array_position => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .array_element_transform => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .array_to_string => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "array_to_string", options.expression) },
            .string_to_array => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "string_to_array", options.expression) },
            .coalesce => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "coalesce", options.expression) },
            .case_fold => return .{ .expression = try expr_projection.parseDefaultOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .replace => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "replace", options.expression) },
            .regexp_replace => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "regexp_replace", options.expression) },
            .regexp_substr => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "regexp_substr", options.expression) },
            .regexp_match => return .{ .expression = try expr_projection.parseRegexpMatchExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .regexp_count => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "regexp_count", options.expression) },
            .regexp_instr => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "regexp_instr", options.expression) },
            .translate => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "translate", options.expression) },
            .concat => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .nullif => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "nullif", options.expression) },
            .text_length => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "length", options.expression) },
            .ascii => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .chr => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .substring => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .overlay => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .split_part => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .strpos => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .left_right => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .pad => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .repeat => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .reverse => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .md5 => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .starts_with => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .ends_with => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .date_trunc => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .date_bin => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .date_part => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .abs => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "abs", options.expression) },
            .round => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "round", options.expression) },
            .trunc, .floor, .ceil, .sqrt, .sign => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .mod => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "mod", options.expression) },
            .power => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "power", options.expression) },
            .greatest_least => return .{ .expression = try expr_projection.parseOpOutputExpressionProjectionAlloc(alloc, tokens, pos, options.expression) },
            .case => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "case", options.expression) },
            .cast => return .{ .expression = try expr_projection.parseFixedOutputExpressionProjectionAlloc(alloc, tokens, pos, "cast", options.expression) },
            .parenthesized => {
                if (peekParenthesizedNullTestProjection(tokens, pos.*)) {
                    return .{ .expression = try expr_projection.parseParenthesizedNullTestExpressionProjectionAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, field_source, options.generated_expression_ast) };
                }
                return .{ .expression = try expr_projection.parseParenthesizedExpressionProjectionAlloc(alloc, tokens, pos, options.expression) };
            },
        }
    }

    var select_field_options = options.select_field;
    select_field_options.generated_expression_ast = options.generated_expression_ast;
    select_field_options.require_exact_generated_expression = options.require_exact_generated_expression;
    return try parseSelectFieldItemAlloc(
        alloc,
        tokens,
        pos,
        schema,
        params,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
        field_source,
        select_field_options,
    );
}

pub fn parseSelectFieldItemAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    params: []const value_mod.SqlValue,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    options: SelectFieldItemParserOptions,
) !plan_mod.SelectItem {
    const expression_start = pos.*;
    const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    defer alloc.free(parsed_field);
    const field = try binder.normalizeRowExpressionFieldAlloc(alloc, schema, parsed_field, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    var field_owned = true;
    errdefer if (field_owned) alloc.free(field);
    if (parser.peekKind(tokens, pos.*, .lparen)) return error.UnsupportedSqlShape;
    if (expr_operator.matchJsonExtractOperator(tokens, pos)) |operator| {
        const as_text = expr_operator.tokenKindIsJsonExtractTextOperator(operator);
        if (binder.relationalColumnForField(schema, field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonExtractOperatorPathOwnedAlloc(alloc, tokens, pos, params, operator);
        var path_owned = true;
        errdefer if (path_owned) alloc.free(path);
        const output = try grammar.parseProjectionOutputOwnedAlloc(alloc, tokens, pos, path);
        var output_owned = true;
        errdefer if (output_owned) alloc.free(output);
        const expression = try expr_build.buildJsonExtractExpressionAlloc(
            alloc,
            .{ .kind = .field, .field = field, .field_source = field_source },
            path,
            as_text,
        );
        errdefer freeExpression(alloc, expression);
        field_owned = false;
        path_owned = false;
        output_owned = false;
        return .{ .expression = expr_build.buildExpressionProjection(output, expression) };
    }
    if (parser.matchToken(tokens, pos, .question) != null) {
        if (binder.relationalColumnForField(schema, field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonPathOwnedAlloc(alloc, tokens, pos, params);
        var path_owned = true;
        errdefer if (path_owned) alloc.free(path);
        const output = try grammar.parseProjectionOutputOwnedAlloc(alloc, tokens, pos, path);
        var output_owned = true;
        errdefer if (output_owned) alloc.free(output);
        const expression = try expr_build.buildJsonPathExistsExpressionAlloc(
            alloc,
            .{ .kind = .field, .field = field, .field_source = field_source },
            path,
        );
        errdefer freeExpression(alloc, expression);
        field_owned = false;
        path_owned = false;
        output_owned = false;
        return .{ .expression = expr_build.buildExpressionProjection(output, expression) };
    }
    if (parser.matchToken(tokens, pos, .question_any) != null or parser.matchToken(tokens, pos, .question_all) != null) {
        const match_all = tokens[pos.* - 1].kind == .question_all;
        if (binder.relationalColumnForField(schema, field, .json) == null) return error.InvalidSqlCatalog;
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        const expression = try expr_build.buildJsonKeySetExistsExpressionAlloc(alloc, field, field_source, match_all, values_json);
        errdefer freeExpression(alloc, expression);
        const output = try grammar.parseProjectionOutputOwnedAlloc(alloc, tokens, pos, if (match_all) "json_keys_all" else "json_keys_any");
        var output_owned = true;
        errdefer if (output_owned) alloc.free(output);
        output_owned = false;
        alloc.free(field);
        field_owned = false;
        return .{ .expression = expr_build.buildExpressionProjection(output, expression) };
    }
    const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
    if (expr_operator.peekArithmeticOperator(tokens, pos.*)) |_| {
        if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
        field_owned = false;
        return .{ .expression = try expr_projection.parseArithmeticExpressionProjectionFromFieldAlloc(alloc, tokens, pos, expression_start, field, field_source, options.type_context, options.arithmetic_hooks, options.generated_expression_ast, options.require_exact_generated_expression) };
    }
    if (expr_operator.peekBooleanOperator(tokens, pos.*)) |_| {
        if (column.field_type != .boolean) return error.InvalidSqlCatalog;
        field_owned = false;
        return .{ .expression = try expr_projection.parseBooleanExpressionProjectionFromFieldAlloc(alloc, tokens, pos, expression_start, field, field_source, options.type_context, options.boolean_hooks, options.generated_expression_ast, options.require_exact_generated_expression) };
    }
    const alias = try grammar.parseOptionalProjectionAliasAlloc(alloc, tokens, pos);
    var alias_transferred = false;
    errdefer if (!alias_transferred) if (alias) |owned| alloc.free(owned);
    if (alias) |output| {
        if (!std.mem.eql(u8, output, field)) {
            alias_transferred = true;
            field_owned = false;
            return .{ .expression = .{
                .output = output,
                .expression = .{
                    .kind = .field,
                    .field = field,
                    .field_source = field_source,
                },
            } };
        }
        alloc.free(output);
        alias_transferred = true;
    }
    field_owned = false;
    return .{ .field = field };
}

pub const RowExpressionOperandParserOptions = struct {
    extension_function: expr_row_parse.ExtensionFunctionRowExpressionParserOptions,
    routine_expression: expr_row_parse.RoutineExpressionRowExpressionParserOptions,
    parenthesized: expr_row_parse.ParenthesizedRowExpressionParserOptions,
    cast: expr_row_parse.CastRowExpressionParserOptions,
    case_expression: expr_row_parse.CaseExpressionParserHooks,
    case_fold: expr_row_parse.CaseFoldRowExpressionParserOptions,
    coalesce: expr_row_parse.CoalesceRowExpressionParserOptions,
    fixed_unary: expr_row_parse.FixedUnaryRowExpressionParserOptions,
    fixed_binary: expr_row_parse.FixedBinaryRowExpressionParserOptions,
    variadic: expr_row_parse.VariadicRowExpressionParserHooks,
    json_build_object: expr_row_parse.JsonBuildObjectRowExpressionParserOptions,
};

pub fn rowExpressionOperandStartWithFunctionBindingsAt(tokens: []const Token, pos: usize, bindings: expr_row_parse.SqlFunctionBindings) ?expr_parse.RowExpressionOperandStart {
    if (expr_parse.rowExpressionOperandStartAt(tokens, pos)) |start| return start;
    if (expr_row_parse.peekExtensionFunctionCall(tokens, pos, bindings.extension_functions)) return .extension_function;
    if (expr_row_parse.peekRoutineExpressionCall(tokens, pos, bindings.routine_expressions)) return .routine_expression;
    return null;
}

pub fn parseRowExpressionOperandAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    function_bindings: expr_row_parse.SqlFunctionBindings,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    joined_source_expression_qualifiers: []const []const u8,
    joined_target_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    type_context: expr_type.RowExpressionTypeContext,
    hooks: RowExpressionOperandParserOptions,
) !db_mod.types.RelationalRowsExpression {
    if (rowExpressionOperandStartWithFunctionBindingsAt(tokens, pos.*, function_bindings)) |start| {
        switch (start) {
            .parenthesized => return try expr_row_parse.parseParenthesizedRowExpressionAlloc(alloc, tokens, pos, hooks.parenthesized),
            .unary_negative => return try parseUnaryNegativeRowExpressionAlloc(alloc, tokens, pos, params, schema, joined_source_schema, function_bindings, field_expression_qualifiers, returning_expression_qualifiers, joined_source_expression_qualifiers, joined_target_expression_qualifiers, defer_row_expression_field_validation, field_source, type_context, hooks),
            .boolean_not => return try parseBooleanNotRowExpressionAlloc(alloc, tokens, pos, params, schema, joined_source_schema, function_bindings, field_expression_qualifiers, returning_expression_qualifiers, joined_source_expression_qualifiers, joined_target_expression_qualifiers, defer_row_expression_field_validation, field_source, type_context, hooks),
            .extension_function => return (try expr_row_parse.parseExtensionFunctionRowExpressionOrNullAlloc(alloc, tokens, pos, function_bindings.extension_functions, hooks.extension_function)) orelse unreachable,
            .routine_expression => return (try expr_row_parse.parseRoutineExpressionRowExpressionOrNullAlloc(alloc, tokens, pos, function_bindings.routine_expressions, hooks.routine_expression)) orelse unreachable,
            .cast => return try expr_row_parse.parseCastRowExpressionAlloc(alloc, tokens, pos, hooks.cast),
            .case => return try expr_row_parse.parseCaseRowExpressionAlloc(alloc, tokens, pos, type_context, defer_row_expression_field_validation, hooks.case_expression),
            .now => return try expr_build.parseSqlNowRowExpressionAlloc(alloc, tokens, pos),
            .current_date => return try expr_build.parseSqlCurrentDateRowExpressionAlloc(alloc, tokens, pos),
            .typed_datetime_literal => return try expr_build.parseSqlTypedDatetimeLiteralRowExpressionAlloc(alloc, tokens, pos),
            .uuid_v4 => return try expr_build.parseSqlUuidV4RowExpression(tokens, pos),
            .interval => return try expr_build.parseSqlIntervalRowExpressionAlloc(alloc, tokens, pos),
            .case_fold => return try expr_row_parse.parseCaseFoldRowExpressionAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, field_source, type_context, hooks.case_fold),
            .replace => return try expr_row_parse.parseTextTernaryRowExpressionAlloc(alloc, tokens, pos, .replace, type_context, hooks.variadic),
            .regexp_replace => return try expr_row_parse.parseRegexpListRowExpressionAlloc(alloc, tokens, pos, .regexp_replace, type_context, hooks.variadic),
            .regexp_substr => return try expr_row_parse.parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .regexp_substr, type_context, hooks.fixed_binary),
            .regexp_match => return try expr_row_parse.parseRegexpListRowExpressionAlloc(alloc, tokens, pos, .regexp_match, type_context, hooks.variadic),
            .regexp_count => return try expr_row_parse.parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .regexp_count, type_context, hooks.fixed_binary),
            .regexp_instr => return try expr_row_parse.parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .regexp_instr, type_context, hooks.fixed_binary),
            .translate => return try expr_row_parse.parseTextTernaryRowExpressionAlloc(alloc, tokens, pos, .translate, type_context, hooks.variadic),
            .concat => return try expr_row_parse.parseConcatRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .coalesce => return try expr_row_parse.parseCoalesceRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.coalesce),
            .nullif => return try parseNullifRowExpressionAlloc(alloc, tokens, pos, params, schema, joined_source_schema, function_bindings, field_expression_qualifiers, returning_expression_qualifiers, joined_source_expression_qualifiers, joined_target_expression_qualifiers, defer_row_expression_field_validation, field_source, type_context, hooks),
            .text_length => return try expr_row_parse.parseTextLengthRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_unary),
            .ascii => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .ascii, type_context, .text, hooks.fixed_unary),
            .chr => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .chr, type_context, .numeric, hooks.fixed_unary),
            .substring => return try expr_row_parse.parseSubstringRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .overlay => return try expr_row_parse.parseOverlayRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .split_part => return try expr_row_parse.parseSplitPartRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .strpos => return try expr_row_parse.parseStrposRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .left_right => return try expr_row_parse.parseLeftRightRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
            .pad => return try expr_row_parse.parsePadRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .repeat => return try expr_row_parse.parseRepeatRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
            .reverse => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .reverse, type_context, .text, hooks.fixed_unary),
            .md5 => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .md5, type_context, .text, hooks.fixed_unary),
            .starts_with => return try expr_row_parse.parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .starts_with, type_context, hooks.fixed_binary),
            .ends_with => return try expr_row_parse.parseTextBinaryRowExpressionAlloc(alloc, tokens, pos, .ends_with, type_context, hooks.fixed_binary),
            .date_trunc => return try expr_row_parse.parseDateTruncRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
            .date_bin => return try expr_row_parse.parseDateBinRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .date_part => return try expr_row_parse.parseDatePartRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .abs => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .abs, type_context, .numeric, hooks.fixed_unary),
            .round => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .round, type_context, .numeric, hooks.fixed_unary),
            .trunc => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .trunc, type_context, .numeric, hooks.fixed_unary),
            .floor => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .floor, type_context, .numeric, hooks.fixed_unary),
            .ceil => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .ceil, type_context, .numeric, hooks.fixed_unary),
            .sqrt => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .sqrt, type_context, .numeric, hooks.fixed_unary),
            .sign => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .sign, type_context, .numeric, hooks.fixed_unary),
            .mod => return try expr_row_parse.parseFixedNumericBinaryRowExpressionAlloc(alloc, tokens, pos, .mod, type_context, hooks.fixed_binary),
            .power => return try expr_row_parse.parseFixedNumericBinaryRowExpressionAlloc(alloc, tokens, pos, .power, type_context, hooks.fixed_binary),
            .greatest_least => return try expr_row_parse.parseGreatestLeastRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .json_extract_path => return try expr_row_parse.parseJsonExtractPathRowExpressionAlloc(alloc, tokens, pos, params, type_context, hooks.fixed_unary),
            .json_typeof => return try expr_row_parse.parseJsonUnaryRowExpressionAlloc(alloc, tokens, pos, .json_typeof, type_context, hooks.fixed_unary),
            .json_array_length => return try expr_row_parse.parseJsonUnaryRowExpressionAlloc(alloc, tokens, pos, .json_array_length, type_context, hooks.fixed_unary),
            .json_build_object => return try expr_row_parse.parseJsonBuildObjectRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.json_build_object),
            .to_jsonb => return try expr_row_parse.parseFixedUnaryRowExpressionAlloc(alloc, tokens, pos, .to_jsonb, type_context, .any, hooks.fixed_unary),
            .convert_from => {
                const value_json = try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params);
                errdefer alloc.free(value_json);
                return .{ .kind = .value, .value_json = value_json };
            },
            .array_length => return try parseArrayLengthRowExpressionAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, field_source),
            .array_position => return try expr_row_parse.parseArrayPositionRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
            .array_element_transform => return try expr_row_parse.parseArrayElementTransformRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .array_to_string => return try expr_row_parse.parseArrayToStringRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.variadic),
            .string_to_array => return try expr_row_parse.parseStringToArrayRowExpressionAlloc(alloc, tokens, pos, type_context, hooks.fixed_binary),
        }
    }
    if (try parseRowExpressionFieldOperandOrNullAlloc(
        alloc,
        tokens,
        pos,
        schema,
        joined_source_schema,
        params,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        joined_source_expression_qualifiers,
        joined_target_expression_qualifiers,
        defer_row_expression_field_validation,
        field_source,
    )) |expression| return expression;

    const value_json = try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params);
    errdefer alloc.free(value_json);
    return .{ .kind = .value, .value_json = value_json };
}

pub fn parseRowExpressionOperandFromContextAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    joined_source_schema: ?runtime_schema.TableSchema,
    function_bindings: expr_row_parse.SqlFunctionBindings,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
    select_context_hooks: SelectParserContextHooks,
    joined_context_hooks: JoinedExpressionParserContextHooks,
    options: RowExpressionOperandParserOptions,
) !db_mod.types.RelationalRowsExpression {
    const select_context = select_context_hooks.get_context(select_context_hooks.ptr);
    const joined_context = joined_context_hooks.get_context(joined_context_hooks.ptr);
    const defer_field_validation =
        select_context.defer_row_expression_field_validation or
        joined_context.defer_row_expression_field_validation or
        joined_context.joined_source_expression_qualifiers.len != 0 or
        joined_context.joined_target_expression_qualifiers.len != 0;
    var type_context = select_context_hooks.row_expression_type_context(select_context_hooks.ptr);
    type_context.defer_row_expression_field_validation = defer_field_validation;
    return try parseRowExpressionOperandAlloc(
        alloc,
        tokens,
        pos,
        params,
        select_context.schema,
        joined_source_schema,
        function_bindings,
        select_context.field_expression_qualifiers,
        select_context.returning_expression_qualifiers,
        joined_context.joined_source_expression_qualifiers,
        joined_context.joined_target_expression_qualifiers,
        defer_field_validation,
        field_source,
        type_context,
        options,
    );
}

pub fn parseRowExpressionFieldOperandOrNullAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    params: []const value_mod.SqlValue,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    joined_source_expression_qualifiers: []const []const u8,
    joined_target_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    field_source: db_mod.types.RelationalRowsExpressionFieldSource,
) !?db_mod.types.RelationalRowsExpression {
    if (!parser.peekKind(tokens, pos.*, .identifier) or
        parser.peekKeywordTag(tokens, pos.*, .null) or
        parser.peekKeywordTag(tokens, pos.*, .true) or
        parser.peekKeywordTag(tokens, pos.*, .false))
    {
        return null;
    }
    if (pos.* + 1 < tokens.len and tokens[pos.* + 1].kind == .lparen) return error.UnsupportedSqlShape;
    const parsed_field = if (joined_source_expression_qualifiers.len != 0 or joined_target_expression_qualifiers.len != 0)
        try parseIdentifierOwnedAlloc(alloc, tokens, pos)
    else
        try expr_generated.parseRowExpressionFieldOwnedAlloc(
            alloc,
            tokens,
            pos,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        );
    defer alloc.free(parsed_field);
    const resolved = try binder.resolveRowExpressionFieldAlloc(
        alloc,
        schema,
        joined_source_schema,
        parsed_field,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        joined_source_expression_qualifiers,
        joined_target_expression_qualifiers,
        defer_row_expression_field_validation,
        field_source,
    );
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(resolved.field);
    if (expr_operator.matchJsonExtractOperator(tokens, pos)) |operator| {
        const as_text = expr_operator.tokenKindIsJsonExtractTextOperator(operator);
        if (!defer_row_expression_field_validation and binder.relationalColumnForField(resolved.schema, resolved.field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonExtractOperatorPathOwnedAlloc(alloc, tokens, pos, params, operator);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        const expression = try expr_build.buildJsonExtractExpressionAlloc(
            alloc,
            .{ .kind = .field, .field = resolved.field, .field_source = resolved.source },
            path,
            as_text,
        );
        field_transferred = true;
        path_transferred = true;
        return expression;
    }
    if (parser.matchToken(tokens, pos, .question) != null) {
        if (!defer_row_expression_field_validation and binder.relationalColumnForField(resolved.schema, resolved.field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonPathOwnedAlloc(alloc, tokens, pos, params);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        const expression = try expr_build.buildJsonPathExistsExpressionAlloc(
            alloc,
            .{ .kind = .field, .field = resolved.field, .field_source = resolved.source },
            path,
        );
        field_transferred = true;
        path_transferred = true;
        return expression;
    }
    if (parser.matchToken(tokens, pos, .question_any) != null or parser.matchToken(tokens, pos, .question_all) != null) {
        const match_all = tokens[pos.* - 1].kind == .question_all;
        if (!defer_row_expression_field_validation and binder.relationalColumnForField(resolved.schema, resolved.field, .json) == null) return error.InvalidSqlCatalog;
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        const expression = try expr_build.buildJsonKeySetExistsExpressionAlloc(alloc, resolved.field, resolved.source, match_all, values_json);
        field_transferred = true;
        alloc.free(resolved.field);
        return expression;
    }
    if (!defer_row_expression_field_validation and binder.relationalColumnForField(resolved.schema, resolved.field, null) == null) return error.InvalidSqlCatalog;
    field_transferred = true;
    return .{ .kind = .field, .field = resolved.field, .field_source = resolved.source };
}

pub fn peekWindowOutputOrderExpression(tokens: []const Token, pos: usize) bool {
    return peekAggregateOutputOrderExpression(tokens, pos);
}

pub fn peekAggregateHavingExpression(tokens: []const Token, pos: usize) bool {
    if (nextIsAggregateFunction(tokens, pos)) return false;
    if (pos >= tokens.len) return false;
    const token = tokens[pos];
    if (peekParenthesizedExpressionCondition(tokens, pos)) return true;
    if (token.kind == .identifier) {
        if (pos + 1 >= tokens.len) return false;
        const next = tokens[pos + 1];
        if (next.kind == .eq or next.kind == .neq or next.kind == .gt or next.kind == .gte or next.kind == .lt or next.kind == .lte) return false;
        if (next.matchesKeywordTag(.is)) return false;
        return true;
    }
    return token.kind == .minus or
        token.kind == .number or
        parser.peekKeyword(tokens, pos, "lower") or
        parser.peekKeyword(tokens, pos, "upper") or
        parser.peekKeyword(tokens, pos, "trim") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTrimVariantFunction) or
        parser.peekKeyword(tokens, pos, "replace") or
        parser.peekKeyword(tokens, pos, "regexp_replace") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction) or
        parser.peekKeyword(tokens, pos, "case") or
        parser.peekKeyword(tokens, pos, "cast") or
        parser.peekKeyword(tokens, pos, "coalesce") or
        parser.peekKeyword(tokens, pos, "nullif") or
        expr_token.peekTextLengthFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsAsciiFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsChrFunction) or
        expr_token.peekSubstringFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction) or
        expr_token.peekSplitPartFunctionKeyword(tokens, pos) or
        expr_token.peekStrposFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsMd5Function) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction) or
        parser.peekKeyword(tokens, pos, "position") or
        parser.peekKeyword(tokens, pos, "abs") or
        parser.peekKeyword(tokens, pos, "round") or
        expr_token.peekFunctionCallTag(tokens, pos, .trunc) or
        expr_token.peekFunctionCallTag(tokens, pos, .floor) or
        expr_token.peekFunctionCallTag(tokens, pos, .ceil) or
        expr_token.peekFunctionCallTag(tokens, pos, .sqrt) or
        expr_token.peekFunctionCallTag(tokens, pos, .sign) or
        expr_token.peekFunctionCallTag(tokens, pos, .mod) or
        expr_token.peekFunctionCallTag(tokens, pos, .power) or
        parser.peekKeyword(tokens, pos, "greatest") or
        parser.peekKeyword(tokens, pos, "least");
}

pub fn parseExpressionRegexpMatchConditionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    type_context: expr_type.RowExpressionTypeContext,
    expression: db_mod.types.RelationalRowsExpression,
    case_insensitive: bool,
    negated: bool,
    options: ExpressionWhereConditionRowParserOptions,
) !db_mod.types.RelationalRowsExpressionCondition {
    const pattern_expression = try parseExpressionWhereConditionRowExpressionAlloc(alloc, tokens, pos, type_context, options);
    defer freeExpression(alloc, pattern_expression);
    return try expr_predicate.expressionRegexpMatchConditionAlloc(alloc, type_context, expression, pattern_expression, case_insensitive, negated);
}

pub fn parseWhereAtomAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    json_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
    json_path_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate),
    json_path_exists: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate),
    array_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate),
    array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate),
    array_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate),
    in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
    text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
    or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    negated: bool,
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    try expr_generated_validate.rejectGeneratedUnsupportedSubqueryPredicateExpression(tokens, generated_expression_ast);

    if (!negated and parser.matchKeyword(tokens, pos, "not")) {
        try parser.expectToken(tokens, pos, .lparen);
        try parseWhereAtomAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, predicates, json_contains, json_path_eq, json_path_exists, array_any, array_contains, array_eq, in_predicates, text_patterns, or_predicates, true, realtime_ns, null);
        try parser.expectToken(tokens, pos, .rparen);
        return;
    }
    if (!negated and valueEqualsAnyArrayPredicateCanStart(tokens, pos.*)) {
        try expr_generated_validate.validateGeneratedExpressionPredicateKind(generated_expression_ast, .quantified_comparison);
    }
    if (!negated and try parseValueEqualsAnyArrayPredicateAlloc(
        alloc,
        tokens,
        pos,
        params,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
        array_any,
        generated_expression_ast,
    )) {
        return;
    }
    const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(alloc, tokens, pos, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    defer alloc.free(parsed_field);
    if (try binder.normalizePeriodReferenceAlloc(alloc, schema, parsed_field, field_expression_qualifiers, returning_expression_qualifiers)) |period_field| {
        defer alloc.free(period_field);
        if (binder.relationalPeriodForDdl(schema.periods, period_field)) |period| {
            if (parser.matchToken(tokens, pos, .at_contains) != null) {
                try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(generated_expression_ast, .contains, tokens, pos.* - 1);
                if (negated) return error.UnsupportedSqlShape;
                const start_column = binder.relationalColumnForField(schema, period.start_column, null) orelse return error.InvalidSqlCatalog;
                const end_column = binder.relationalColumnForField(schema, period.end_column, null) orelse return error.InvalidSqlCatalog;
                if (start_column.field_type != end_column.field_type or !binder.relationalPeriodColumnType(start_column.field_type)) return error.InvalidSqlCatalog;
                const point_json = try parseSqlRangeConstructorEndpointJsonAlloc(alloc, tokens, pos, params, start_column.field_type, realtime_ns);
                defer alloc.free(point_json);
                if (std.mem.eql(u8, point_json, "null")) return error.UnsupportedSqlShape;
                try appendTemporalRangeContainsPredicateGroups(alloc, or_predicates, period, point_json);
                return;
            }
            if (parser.matchToken(tokens, pos, .range_overlap) != null) {
                try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(generated_expression_ast, .overlaps, tokens, pos.* - 1);
                if (negated) return error.UnsupportedSqlShape;
                const range = try parseSqlPeriodRangeValuePairAlloc(alloc, tokens, pos, params, schema, period, realtime_ns);
                defer freePeriodRangeValuePair(alloc, range);
                try appendTemporalRangeOverlapsPredicateGroups(alloc, or_predicates, period, range);
                return;
            }
        }
    }

    const field = try binder.normalizeRowExpressionFieldAlloc(alloc, schema, parsed_field, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    var field_transferred = false;
    defer if (!field_transferred) alloc.free(field);
    const maybe_column = binder.relationalColumnForField(schema, field, null);

    if (expr_operator.matchJsonExtractOperator(tokens, pos)) |operator| {
        const as_text = expr_operator.tokenKindIsJsonExtractTextOperator(operator);
        const path = try value_mod.parseJsonExtractOperatorPathOwnedAlloc(alloc, tokens, pos, params, operator);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        const op_token_index = pos.*;
        try parser.expectToken(tokens, pos, .eq);
        try expr_generated_validate.validateGeneratedComparisonPredicateExpression(generated_expression_ast, tokens, op_token_index, .eq);
        const value_json = if (as_text)
            try value_mod.parseJsonValueAlloc(alloc, tokens, pos, params)
        else
            try value_mod.parseRequiredJsonDocumentValueAlloc(alloc, tokens, pos, params);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        if (binder.relationalColumnForField(schema, field, .json) == null) return error.InvalidSqlCatalog;
        const predicate_field = try alloc.dupe(u8, field);
        var predicate_field_transferred = false;
        errdefer if (!predicate_field_transferred) alloc.free(predicate_field);
        try json_path_eq.append(alloc, .{
            .field = predicate_field,
            .path = path,
            .value_json = value_json,
        });
        predicate_field_transferred = true;
        path_transferred = true;
        value_transferred = true;
        return;
    }
    if (parser.matchToken(tokens, pos, .at_contains) != null) {
        try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(generated_expression_ast, .contains, tokens, pos.* - 1);
        const column = maybe_column orelse return error.InvalidSqlCatalog;
        const value_json = try value_mod.parseStructuredPredicateValueAlloc(alloc, tokens, pos, params, column);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        if (column.field_type == .array) {
            try value_mod.validateSqlArrayValueJson(alloc, column, value_json);
            try array_contains.append(alloc, .{
                .field = field,
                .value_json = value_json,
            });
            field_transferred = true;
            value_transferred = true;
            return;
        }
        if (column.field_type != .json) return error.InvalidSqlCatalog;
        try json_contains.append(alloc, .{
            .field = field,
            .value_json = value_json,
        });
        field_transferred = true;
        value_transferred = true;
        return;
    }
    if (parser.matchToken(tokens, pos, .question) != null) {
        try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(generated_expression_ast, .json_key_exists, tokens, pos.* - 1);
        if (binder.relationalColumnForField(schema, field, .json) == null) return error.InvalidSqlCatalog;
        const path = try value_mod.parseJsonPathOwnedAlloc(alloc, tokens, pos, params);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        try json_path_exists.append(alloc, .{
            .field = field,
            .path = path,
        });
        field_transferred = true;
        path_transferred = true;
        return;
    }
    const column = maybe_column orelse return error.InvalidSqlCatalog;
    const is_tail_token_index = pos.*;
    if (try expr_operator.parseExpressionIsTailIf(tokens, pos, .{
        .allow_boolean_unknown = true,
        .allow_boolean_literal = true,
        .allow_boolean_literal_negation = true,
    })) |is_tail| {
        switch (is_tail.kind) {
            .distinct_comparison => {
                try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_expression_ast, tokens, is_tail_token_index, is_tail);
                const value_json = try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
                var value_transferred = false;
                errdefer if (!value_transferred) alloc.free(value_json);
                const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
                var collation_transferred = false;
                errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
                try predicates.append(alloc, .{
                    .name = "",
                    .field = field,
                    .op = is_tail.op,
                    .value_json = value_json,
                    .collation = collation,
                });
                value_transferred = true;
                field_transferred = true;
                collation_transferred = true;
                return;
            },
            .boolean_unknown => {
                try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_expression_ast, tokens, is_tail_token_index, is_tail);
                if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                try predicates.append(alloc, .{
                    .name = "",
                    .field = field,
                    .op = is_tail.op,
                    .value_json = null,
                });
                field_transferred = true;
                return;
            },
            .boolean_literal => {
                try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_expression_ast, tokens, is_tail_token_index, is_tail);
                if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                if (is_tail.boolean_negated) {
                    try appendBooleanIsNotPredicateGroups(alloc, or_predicates, field, is_tail.boolean_value);
                    return;
                }
                const value_json = try alloc.dupe(u8, value_mod.booleanJson(is_tail.boolean_value));
                var value_transferred = false;
                errdefer if (!value_transferred) alloc.free(value_json);
                try predicates.append(alloc, .{
                    .name = "",
                    .field = field,
                    .op = .eq,
                    .value_json = value_json,
                });
                value_transferred = true;
                field_transferred = true;
                return;
            },
            .null_test => {},
        }
        try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_expression_ast, tokens, is_tail_token_index, is_tail);
        try predicates.append(alloc, .{
            .name = "",
            .field = field,
            .op = is_tail.op,
            .value_json = null,
        });
        field_transferred = true;
        return;
    }
    const postfix_null_token_index = pos.*;
    if (expr_operator.matchPostfixNullTest(tokens, pos)) |op| {
        try expr_generated_validate.validateGeneratedPostfixNullPredicateExpression(generated_expression_ast, tokens, postfix_null_token_index, op);
        try predicates.append(alloc, .{
            .name = "",
            .field = field,
            .op = op,
            .value_json = null,
        });
        field_transferred = true;
        return;
    }
    if (parser.matchKeyword(tokens, pos, "like") or parser.matchKeyword(tokens, pos, "ilike")) {
        const case_insensitive = tokens[pos.* - 1].matchesKeywordTag(.ilike);
        const generated_kind: generated_parser.GeneratedSqlExpressionKind = if (case_insensitive) .ilike else .like;
        const generated_quantifier_token_index: ?usize = if (expr_token.tokenAtIsAnySomeOrAll(tokens, pos.*)) pos.* else null;
        try expr_generated_validate.validateGeneratedPatternPredicateIdentity(generated_expression_ast, generated_kind, tokens, pos.* - 1, generated_quantifier_token_index);
        try expr_predicate.parseAndAppendTextPatternPredicateAlloc(alloc, tokens, pos, params, text_patterns, field, column, case_insensitive, negated, realtime_ns);
        return;
    }
    if (parser.matchKeyword(tokens, pos, "between")) {
        const operator_token_index = pos.* - 1;
        const modifier_token_index = expr_generated_validate.betweenModifierTokenIndex(tokens, pos.*);
        try expr_generated_validate.validateGeneratedSetOrBetweenPredicateIdentity(generated_expression_ast, .between, tokens, operator_token_index, null, modifier_token_index);
        const symmetric = expr_token.matchBetweenSymmetricMode(tokens, pos);
        const lower_json = try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
        defer alloc.free(lower_json);
        try parser.expectKeyword(tokens, pos, "and");
        const upper_json = try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
        defer alloc.free(upper_json);
        try appendBetweenPredicateValuesAlloc(alloc, predicates, or_predicates, field, column, lower_json, upper_json, negated, symmetric);
        return;
    }
    if (parser.matchKeyword(tokens, pos, "not")) {
        const negation_token_index = pos.* - 1;
        if (parser.matchKeyword(tokens, pos, "between")) {
            const operator_token_index = pos.* - 1;
            const modifier_token_index = expr_generated_validate.betweenModifierTokenIndex(tokens, pos.*);
            try expr_generated_validate.validateGeneratedSetOrBetweenPredicateIdentity(generated_expression_ast, .not_between, tokens, operator_token_index, negation_token_index, modifier_token_index);
            const symmetric = expr_token.matchBetweenSymmetricMode(tokens, pos);
            const lower_json = try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
            defer alloc.free(lower_json);
            try parser.expectKeyword(tokens, pos, "and");
            const upper_json = try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
            defer alloc.free(upper_json);
            try appendBetweenPredicateValuesAlloc(alloc, predicates, or_predicates, field, column, lower_json, upper_json, true, symmetric);
            return;
        }
        if (parser.matchKeyword(tokens, pos, "like") or parser.matchKeyword(tokens, pos, "ilike")) {
            const case_insensitive = tokens[pos.* - 1].matchesKeywordTag(.ilike);
            const generated_kind: generated_parser.GeneratedSqlExpressionKind = if (case_insensitive) .not_ilike else .not_like;
            const generated_quantifier_token_index: ?usize = if (expr_token.tokenAtIsAnySomeOrAll(tokens, pos.*)) pos.* else null;
            try expr_generated_validate.validateGeneratedPatternPredicateIdentity(generated_expression_ast, generated_kind, tokens, pos.* - 1, generated_quantifier_token_index);
            try expr_predicate.parseAndAppendTextPatternPredicateAlloc(alloc, tokens, pos, params, text_patterns, field, column, case_insensitive, true, realtime_ns);
            return;
        }
        try parser.expectKeyword(tokens, pos, "in");
        try expr_generated_validate.validateGeneratedSetOrBetweenPredicateIdentity(generated_expression_ast, .not_in_list, tokens, pos.* - 1, negation_token_index, null);
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        const values_json = try value_mod.parseSqlInValuesJsonAlloc(alloc, tokens, pos, params);
        var values_transferred = false;
        errdefer if (!values_transferred) alloc.free(values_json);
        try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
        const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
        var collation_transferred = false;
        errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
        try in_predicates.append(alloc, .{
            .field = field,
            .values_json = values_json,
            .negated = true,
            .collation = collation,
        });
        field_transferred = true;
        values_transferred = true;
        collation_transferred = true;
        return;
    }
    if (parser.matchKeyword(tokens, pos, "in")) {
        try expr_generated_validate.validateGeneratedSetOrBetweenPredicateIdentity(generated_expression_ast, .in_list, tokens, pos.* - 1, null, null);
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        const values_json = try value_mod.parseSqlInValuesJsonAlloc(alloc, tokens, pos, params);
        var values_transferred = false;
        errdefer if (!values_transferred) alloc.free(values_json);
        try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
        const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
        var collation_transferred = false;
        errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
        try in_predicates.append(alloc, .{
            .field = field,
            .values_json = values_json,
            .negated = false,
            .collation = collation,
        });
        field_transferred = true;
        values_transferred = true;
        collation_transferred = true;
        return;
    }

    const op_token_index = pos.*;
    const op = try expr_operator.parseComparisonOp(tokens, pos);
    if (op == .eq and expr_token.matchAnyOrSomeKeyword(tokens, pos)) {
        try expr_generated_validate.validateGeneratedQuantifiedPredicateIdentity(generated_expression_ast, tokens, op_token_index, pos.* - 1);
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        try parser.expectToken(tokens, pos, .lparen);
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        var values_transferred = false;
        errdefer if (!values_transferred) alloc.free(values_json);
        try parser.expectToken(tokens, pos, .rparen);
        try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
        const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
        var collation_transferred = false;
        errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
        try in_predicates.append(alloc, .{
            .field = field,
            .values_json = values_json,
            .negated = negated,
            .collation = collation,
        });
        field_transferred = true;
        values_transferred = true;
        collation_transferred = true;
        return;
    }
    if (op == .ne and expr_token.matchAnyOrSomeKeyword(tokens, pos)) {
        try expr_generated_validate.validateGeneratedQuantifiedPredicateIdentity(generated_expression_ast, tokens, op_token_index, pos.* - 1);
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        try parser.expectToken(tokens, pos, .lparen);
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        try parser.expectToken(tokens, pos, .rparen);
        try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
        if (negated) {
            try appendScalarAllEqualityPredicates(alloc, predicates, field, values_json, column.collation);
        } else {
            try appendScalarValuesJsonOrGroups(alloc, or_predicates, field, values_json, .ne, column.collation);
        }
        return;
    }
    if (op == .eq and parser.matchKeyword(tokens, pos, "all")) {
        try expr_generated_validate.validateGeneratedQuantifiedPredicateIdentity(generated_expression_ast, tokens, op_token_index, pos.* - 1);
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        try parser.expectToken(tokens, pos, .lparen);
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        defer alloc.free(values_json);
        try parser.expectToken(tokens, pos, .rparen);
        try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
        try appendScalarAllEqualityPredicates(alloc, predicates, field, values_json, column.collation);
        return;
    }
    if (op == .ne and parser.matchKeyword(tokens, pos, "all")) {
        try expr_generated_validate.validateGeneratedQuantifiedPredicateIdentity(generated_expression_ast, tokens, op_token_index, pos.* - 1);
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        try parser.expectToken(tokens, pos, .lparen);
        const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
        var values_transferred = false;
        errdefer if (!values_transferred) alloc.free(values_json);
        try parser.expectToken(tokens, pos, .rparen);
        try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
        const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
        var collation_transferred = false;
        errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
        try in_predicates.append(alloc, .{
            .field = field,
            .values_json = values_json,
            .negated = !negated,
            .collation = collation,
        });
        field_transferred = true;
        values_transferred = true;
        collation_transferred = true;
        return;
    }
    if (negated) return error.UnsupportedSqlShape;
    try expr_generated_validate.validateGeneratedRelationalPredicateExpression(generated_expression_ast, tokens, op_token_index, op);
    const value_json = if (column.field_type == .array and op == .eq)
        try value_mod.parseArrayPredicateValueAlloc(alloc, tokens, pos, params)
    else
        try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    if (column.field_type == .array) {
        if (op != .eq) return error.UnsupportedSqlShape;
        try value_mod.validateSqlArrayValueJson(alloc, column, value_json);
        try array_eq.append(alloc, .{
            .field = field,
            .value_json = value_json,
        });
        field_transferred = true;
        value_transferred = true;
        return;
    }
    const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
    var collation_transferred = false;
    errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
    try predicates.append(alloc, .{
        .name = "",
        .field = field,
        .op = op,
        .value_json = value_json,
        .collation = collation,
    });
    field_transferred = true;
    value_transferred = true;
    collation_transferred = true;
}

pub fn parseJoinWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    left_alias: []const u8,
    right_alias: []const u8,
    string_to_array_predicate_is_containment: bool,
    targets: *JoinWherePredicateTargets,
    expression_where_options: JoinedMutationExpressionWhereConditionParserOptions,
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    while (true) {
        const generated_atom_expression = try generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast);

        if (try joinedMutationExpressionSideAt(tokens, pos.*, left_alias, right_alias, string_to_array_predicate_is_containment)) |expression_side| {
            var expression_where_options_with_generated = expression_where_options;
            expression_where_options_with_generated.generated_expression_ast = generated_atom_expression;
            expression_where_options_with_generated.alternatives_hooks.generated_expression_ast = generated_atom_expression;
            expression_where_options_with_generated.expression_condition_hooks.generated_expression_ast = generated_atom_expression;
            try parseJoinedMutationExpressionWhereConditionWithContextAlloc(
                alloc,
                tokens,
                pos,
                expression_side,
                targets,
                left_alias,
                right_alias,
                expression_where_options_with_generated,
            );
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }

        const source = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
        defer plan_mod.freeQualifiedField(alloc, source);
        const side = try binder.joinSideForQualifier(source.qualifier, left_alias, right_alias);
        const column = try binder.joinColumnForSide(schema, joined_source_schema, side, source.field);
        const target = if (side == .left) targets.left_predicates else targets.right_predicates;
        const target_json_contains = if (side == .left) targets.left_json_contains else targets.right_json_contains;
        const target_json_path_exists = if (side == .left) targets.left_json_path_exists else targets.right_json_path_exists;
        const target_array_contains = if (side == .left) targets.left_array_contains else targets.right_array_contains;
        const target_array_eq = if (side == .left) targets.left_array_eq else targets.right_array_eq;
        const target_in_predicates = if (side == .left) targets.left_in_predicates else targets.right_in_predicates;
        const target_text_patterns = if (side == .left) targets.left_text_patterns else targets.right_text_patterns;
        const target_expression_or_predicates = if (side == .left) targets.left_expression_or_predicates else targets.right_expression_or_predicates;

        if (parser.matchToken(tokens, pos, .at_contains) != null) {
            try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(generated_atom_expression, .contains, tokens, pos.* - 1);
            const value_json = try value_mod.parseStructuredPredicateValueAlloc(alloc, tokens, pos, params, column);
            var value_transferred = false;
            errdefer if (!value_transferred) alloc.free(value_json);
            const field = try alloc.dupe(u8, source.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            if (column.field_type == .array) {
                try value_mod.validateSqlArrayValueJson(alloc, column, value_json);
                try target_array_contains.append(alloc, .{ .field = field, .value_json = value_json });
            } else {
                if (column.field_type != .json) return error.InvalidSqlCatalog;
                try target_json_contains.append(alloc, .{ .field = field, .value_json = value_json });
            }
            field_transferred = true;
            value_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (parser.matchToken(tokens, pos, .question) != null) {
            try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(generated_atom_expression, .json_key_exists, tokens, pos.* - 1);
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            const path = try value_mod.parseJsonPathOwnedAlloc(alloc, tokens, pos, params);
            var path_transferred = false;
            errdefer if (!path_transferred) alloc.free(path);
            const field = try alloc.dupe(u8, source.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            try target_json_path_exists.append(alloc, .{ .field = field, .path = path });
            field_transferred = true;
            path_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (parser.matchKeyword(tokens, pos, "like") or parser.matchKeyword(tokens, pos, "ilike")) {
            const case_insensitive = tokens[pos.* - 1].matchesKeywordTag(.ilike);
            const generated_kind: generated_parser.GeneratedSqlExpressionKind = if (case_insensitive) .ilike else .like;
            const generated_quantifier_token_index: ?usize = if (expr_token.tokenAtIsAnySomeOrAll(tokens, pos.*)) pos.* else null;
            try expr_generated_validate.validateGeneratedPatternPredicateIdentity(generated_atom_expression, generated_kind, tokens, pos.* - 1, generated_quantifier_token_index);
            try expr_predicate.parseAndAppendTextPatternPredicateAlloc(alloc, tokens, pos, params, target_text_patterns, source.field, column, case_insensitive, false, realtime_ns);
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (parser.matchKeyword(tokens, pos, "not")) {
            const negation_token_index = pos.* - 1;
            if (parser.matchKeyword(tokens, pos, "like") or parser.matchKeyword(tokens, pos, "ilike")) {
                const case_insensitive = tokens[pos.* - 1].matchesKeywordTag(.ilike);
                const generated_kind: generated_parser.GeneratedSqlExpressionKind = if (case_insensitive) .not_ilike else .not_like;
                const generated_quantifier_token_index: ?usize = if (expr_token.tokenAtIsAnySomeOrAll(tokens, pos.*)) pos.* else null;
                try expr_generated_validate.validateGeneratedPatternPredicateIdentity(generated_atom_expression, generated_kind, tokens, pos.* - 1, generated_quantifier_token_index);
                try expr_predicate.parseAndAppendTextPatternPredicateAlloc(alloc, tokens, pos, params, target_text_patterns, source.field, column, case_insensitive, true, realtime_ns);
                if (!parser.matchKeyword(tokens, pos, "and")) break;
                continue;
            }
            try parser.expectKeyword(tokens, pos, "in");
            try expr_generated_validate.validateGeneratedSetOrBetweenPredicateIdentity(generated_atom_expression, .not_in_list, tokens, pos.* - 1, negation_token_index, null);
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            const values_json = try value_mod.parseSqlInValuesJsonAlloc(alloc, tokens, pos, params);
            var values_transferred = false;
            errdefer if (!values_transferred) alloc.free(values_json);
            try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
            const field = try alloc.dupe(u8, source.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
            var collation_transferred = false;
            errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
            try target_in_predicates.append(alloc, .{ .field = field, .values_json = values_json, .negated = true, .collation = collation });
            field_transferred = true;
            values_transferred = true;
            collation_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (parser.matchKeyword(tokens, pos, "in")) {
            try expr_generated_validate.validateGeneratedSetOrBetweenPredicateIdentity(generated_atom_expression, .in_list, tokens, pos.* - 1, null, null);
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            const values_json = try value_mod.parseSqlInValuesJsonAlloc(alloc, tokens, pos, params);
            var values_transferred = false;
            errdefer if (!values_transferred) alloc.free(values_json);
            try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
            const field = try alloc.dupe(u8, source.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
            var collation_transferred = false;
            errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
            try target_in_predicates.append(alloc, .{ .field = field, .values_json = values_json, .negated = false, .collation = collation });
            field_transferred = true;
            values_transferred = true;
            collation_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        const op_token_index = pos.*;
        const op: runtime_schema.RelationalCheckOp = if (try expr_operator.parseExpressionIsTailIf(tokens, pos, .{
            .allow_boolean_unknown = true,
            .allow_boolean_literal = true,
            .allow_boolean_literal_negation = true,
        })) |is_tail| blk: {
            try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_atom_expression, tokens, op_token_index, is_tail);
            switch (is_tail.kind) {
                .distinct_comparison, .null_test => {},
                .boolean_unknown => {
                    if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                    break :blk is_tail.op;
                },
                .boolean_literal => {
                    if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                    if (is_tail.boolean_negated) {
                        try expr_condition.appendBooleanIsNotExpressionGroups(alloc, target_expression_or_predicates, source.field, is_tail.boolean_value);
                        if (!parser.matchKeyword(tokens, pos, "and")) break;
                        continue;
                    }
                    const value_json = try alloc.dupe(u8, value_mod.booleanJson(is_tail.boolean_value));
                    var value_transferred = false;
                    errdefer if (!value_transferred) alloc.free(value_json);
                    const field = try alloc.dupe(u8, source.field);
                    var field_transferred = false;
                    errdefer if (!field_transferred) alloc.free(field);
                    try target.append(alloc, .{
                        .name = "",
                        .field = field,
                        .op = .eq,
                        .value_json = value_json,
                    });
                    field_transferred = true;
                    value_transferred = true;
                    if (!parser.matchKeyword(tokens, pos, "and")) break;
                    continue;
                },
            }
            break :blk is_tail.op;
        } else try expr_operator.parseComparisonOp(tokens, pos);
        if (op == .eq and expr_token.matchAnyOrSomeKeyword(tokens, pos)) {
            try expr_generated_validate.validateGeneratedQuantifiedPredicateIdentity(generated_atom_expression, tokens, op_token_index, pos.* - 1);
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            try parser.expectToken(tokens, pos, .lparen);
            const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
            var values_transferred = false;
            errdefer if (!values_transferred) alloc.free(values_json);
            try parser.expectToken(tokens, pos, .rparen);
            try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
            const field = try alloc.dupe(u8, source.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
            var collation_transferred = false;
            errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
            try target_in_predicates.append(alloc, .{ .field = field, .values_json = values_json, .negated = false, .collation = collation });
            field_transferred = true;
            values_transferred = true;
            collation_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        try expr_generated_validate.validateGeneratedRelationalPredicateExpression(generated_atom_expression, tokens, op_token_index, op);
        const value_json = if (op == .is_null or op == .is_not_null)
            null
        else if (column.field_type == .array and op == .eq)
            try value_mod.parseArrayPredicateValueAlloc(alloc, tokens, pos, params)
        else
            try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
        var value_transferred = false;
        errdefer if (!value_transferred) if (value_json) |json| alloc.free(json);
        const field = try alloc.dupe(u8, source.field);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        if (column.field_type == .array and op == .eq) {
            try value_mod.validateSqlArrayValueJson(alloc, column, value_json.?);
            try target_array_eq.append(alloc, .{ .field = field, .value_json = value_json.? });
            field_transferred = true;
            value_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
        var collation_transferred = false;
        errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
        try target.append(alloc, .{ .name = "", .field = field, .op = op, .value_json = value_json, .collation = collation });
        field_transferred = true;
        value_transferred = true;
        collation_transferred = true;
        if (!parser.matchKeyword(tokens, pos, "and")) break;
    }
}

pub fn parseJoinOnAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    join_type: db_mod.types.RelationalRowsJoinType,
    left_alias: []const u8,
    right_alias: []const u8,
    string_to_array_predicate_is_containment: bool,
    targets: *JoinOnPredicateTargets,
    expression_where_options: JoinedMutationExpressionWhereConditionParserOptions,
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    while (true) {
        const generated_atom_expression = try generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast);

        if (try joinedMutationExpressionSideAt(tokens, pos.*, left_alias, right_alias, string_to_array_predicate_is_containment)) |_| {
            var unused_left_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
            defer {
                freeExpressionConditions(alloc, unused_left_expression_predicates.items);
                unused_left_expression_predicates.deinit(alloc);
            }
            var unused_right_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
            defer {
                freeExpressionConditions(alloc, unused_right_expression_predicates.items);
                unused_right_expression_predicates.deinit(alloc);
            }
            var unused_left_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer {
                freeExpressionPredicateGroups(alloc, unused_left_expression_or_predicates.items);
                unused_left_expression_or_predicates.deinit(alloc);
            }
            var unused_right_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer {
                freeExpressionPredicateGroups(alloc, unused_right_expression_or_predicates.items);
                unused_right_expression_or_predicates.deinit(alloc);
            }
            var unused_left_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer {
                freeExpressionPredicateGroups(alloc, unused_left_expression_not_predicates.items);
                unused_left_expression_not_predicates.deinit(alloc);
            }
            var unused_right_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer {
                freeExpressionPredicateGroups(alloc, unused_right_expression_not_predicates.items);
                unused_right_expression_not_predicates.deinit(alloc);
            }
            var unused_left_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
            defer {
                freeExpressionArrayContains(alloc, unused_left_expression_array_contains.items);
                unused_left_expression_array_contains.deinit(alloc);
            }
            var unused_right_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
            defer {
                freeExpressionArrayContains(alloc, unused_right_expression_array_contains.items);
                unused_right_expression_array_contains.deinit(alloc);
            }

            var expression_targets = JoinWherePredicateTargets{
                .left_predicates = undefined,
                .right_predicates = undefined,
                .left_json_contains = undefined,
                .right_json_contains = undefined,
                .left_json_path_exists = undefined,
                .right_json_path_exists = undefined,
                .left_array_contains = undefined,
                .right_array_contains = undefined,
                .left_array_eq = undefined,
                .right_array_eq = undefined,
                .left_in_predicates = undefined,
                .right_in_predicates = undefined,
                .left_text_patterns = undefined,
                .right_text_patterns = undefined,
                .left_expression_predicates = &unused_left_expression_predicates,
                .right_expression_predicates = &unused_right_expression_predicates,
                .left_expression_or_predicates = &unused_left_expression_or_predicates,
                .right_expression_or_predicates = &unused_right_expression_or_predicates,
                .left_expression_not_predicates = &unused_left_expression_not_predicates,
                .right_expression_not_predicates = &unused_right_expression_not_predicates,
                .left_expression_array_contains = &unused_left_expression_array_contains,
                .right_expression_array_contains = &unused_right_expression_array_contains,
                .match_expression_predicates = targets.on_expression_predicates,
                .match_expression_or_predicates = targets.on_expression_or_predicates,
                .match_expression_not_predicates = targets.on_expression_not_predicates,
                .match_expression_array_contains = targets.on_expression_array_contains,
            };
            var expression_where_options_with_generated = expression_where_options;
            expression_where_options_with_generated.generated_expression_ast = generated_atom_expression;
            expression_where_options_with_generated.alternatives_hooks.generated_expression_ast = generated_atom_expression;
            expression_where_options_with_generated.expression_condition_hooks.generated_expression_ast = generated_atom_expression;
            try parseJoinedMutationExpressionWhereConditionWithContextAlloc(
                alloc,
                tokens,
                pos,
                .mixed,
                &expression_targets,
                left_alias,
                right_alias,
                expression_where_options_with_generated,
            );
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }

        const lhs = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
        defer plan_mod.freeQualifiedField(alloc, lhs);
        const lhs_side = try binder.joinSideForQualifier(lhs.qualifier, left_alias, right_alias);
        const lhs_column = try binder.joinColumnForSide(schema, joined_source_schema, lhs_side, lhs.field);
        const target_predicates = if (lhs_side == .left) targets.left_predicates else targets.right_predicates;
        const op_token_index = pos.*;
        const op: runtime_schema.RelationalCheckOp = if (try expr_operator.parseExpressionIsTailIf(tokens, pos, .{
            .allow_distinct = false,
            .allow_boolean_unknown = true,
            .allow_boolean_literal = true,
        })) |is_tail| blk: {
            try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_atom_expression, tokens, op_token_index, is_tail);
            switch (is_tail.kind) {
                .distinct_comparison => unreachable,
                .null_test => {},
                .boolean_unknown => {
                    if (lhs_column.field_type != .boolean) return error.InvalidSqlCatalog;
                    break :blk is_tail.op;
                },
                .boolean_literal => {
                    if (lhs_column.field_type != .boolean) return error.InvalidSqlCatalog;
                    const value_json = try alloc.dupe(u8, value_mod.booleanJson(is_tail.boolean_value));
                    var value_transferred = false;
                    errdefer if (!value_transferred) alloc.free(value_json);
                    try appendJoinOnScalarPredicateAlloc(
                        alloc,
                        target_predicates,
                        targets.on_expression_predicates,
                        join_type,
                        lhs_side,
                        lhs.field,
                        .eq,
                        value_json,
                        lhs_column.collation,
                    );
                    value_transferred = true;
                    if (!parser.matchKeyword(tokens, pos, "and")) break;
                    continue;
                },
            }
            break :blk is_tail.op;
        } else try expr_operator.parseComparisonOp(tokens, pos);
        try expr_generated_validate.validateGeneratedRelationalPredicateExpression(generated_atom_expression, tokens, op_token_index, op);
        if (op == .eq and parser.peekKind(tokens, pos.*, .identifier) and identifierContainsQualifier(tokens[pos.*].text)) {
            const rhs = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
            defer plan_mod.freeQualifiedField(alloc, rhs);
            const rhs_side = try binder.joinSideForQualifier(rhs.qualifier, left_alias, right_alias);
            if (lhs_side == rhs_side) return error.UnsupportedSqlShape;
            const rhs_column = try binder.joinColumnForSide(schema, joined_source_schema, rhs_side, rhs.field);
            if (lhs_column.field_type != rhs_column.field_type) return error.UnsupportedSqlShape;
            const left_field_source = if (lhs_side == .left) lhs.field else rhs.field;
            const right_field_source = if (lhs_side == .right) lhs.field else rhs.field;
            const left_field = try alloc.dupe(u8, left_field_source);
            var left_transferred = false;
            errdefer if (!left_transferred) alloc.free(left_field);
            const right_field = try alloc.dupe(u8, right_field_source);
            var right_transferred = false;
            errdefer if (!right_transferred) alloc.free(right_field);
            try targets.on.append(alloc, .{ .left_field = left_field, .right_field = right_field });
            left_transferred = true;
            right_transferred = true;
        } else {
            if (parser.peekKind(tokens, pos.*, .identifier) and identifierContainsQualifier(tokens[pos.*].text)) return error.UnsupportedSqlShape;
            const value_json = if (op == .is_null or op == .is_not_null)
                null
            else
                try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, lhs_column, realtime_ns);
            var value_transferred = false;
            errdefer if (!value_transferred) if (value_json) |json| alloc.free(json);
            try appendJoinOnScalarPredicateAlloc(
                alloc,
                target_predicates,
                targets.on_expression_predicates,
                join_type,
                lhs_side,
                lhs.field,
                op,
                value_json,
                lhs_column.collation,
            );
            value_transferred = true;
        }
        if (!parser.matchKeyword(tokens, pos, "and")) break;
    }
}

fn appendJoinUsingColumnsAlloc(
    alloc: std.mem.Allocator,
    columns: []const []const u8,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    out: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinOn),
) !void {
    try grammar.validateSqlIdentifierListUnique(columns);
    for (columns) |column| {
        const left_column = try binder.joinColumnForSide(schema, joined_source_schema, .left, column);
        const right_column = try binder.joinColumnForSide(schema, joined_source_schema, .right, column);
        if (left_column.field_type != right_column.field_type) return error.UnsupportedSqlShape;
        if (left_column.array_item_type != right_column.array_item_type) return error.UnsupportedSqlShape;

        const left_field = try alloc.dupe(u8, column);
        var left_transferred = false;
        errdefer if (!left_transferred) alloc.free(left_field);
        const right_field = try alloc.dupe(u8, column);
        var right_transferred = false;
        errdefer if (!right_transferred) alloc.free(right_field);
        try out.append(alloc, .{ .left_field = left_field, .right_field = right_field });
        left_transferred = true;
        right_transferred = true;
    }
}

fn appendNaturalJoinColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    out: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinOn),
) !void {
    const right_schema = joined_source_schema orelse schema;
    var columns = std.ArrayListUnmanaged([]const u8).empty;
    defer columns.deinit(alloc);
    for (schema.relational_columns) |left_column| {
        for (right_schema.relational_columns) |right_column| {
            if (!std.mem.eql(u8, left_column.name, right_column.name)) continue;
            try columns.append(alloc, left_column.name);
            break;
        }
    }
    try appendJoinUsingColumnsAlloc(alloc, columns.items, schema, joined_source_schema, out);
}

pub fn parseLateralWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    left_alias: []const u8,
    right_alias: []const u8,
    string_to_array_predicate_is_containment: bool,
    targets: *LateralWherePredicateTargets,
    expression_where_options: JoinedMutationExpressionWhereConditionParserOptions,
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    while (true) {
        const generated_atom_expression = try generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast);

        if (try joinedMutationExpressionSideAt(tokens, pos.*, left_alias, right_alias, string_to_array_predicate_is_containment)) |expression_side| {
            switch (expression_side) {
                .single => |single| if (single != .right) return error.UnsupportedSqlShape,
                .mixed => {},
            }

            var unsupported_left_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
            defer {
                freeExpressionConditions(alloc, unsupported_left_expression_predicates.items);
                unsupported_left_expression_predicates.deinit(alloc);
            }
            var unsupported_left_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer {
                freeExpressionPredicateGroups(alloc, unsupported_left_expression_or_predicates.items);
                unsupported_left_expression_or_predicates.deinit(alloc);
            }
            var unsupported_left_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer {
                freeExpressionPredicateGroups(alloc, unsupported_left_expression_not_predicates.items);
                unsupported_left_expression_not_predicates.deinit(alloc);
            }
            var unsupported_left_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
            defer {
                freeExpressionArrayContains(alloc, unsupported_left_expression_array_contains.items);
                unsupported_left_expression_array_contains.deinit(alloc);
            }
            var unsupported_match_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
            defer {
                freeExpressionConditions(alloc, unsupported_match_expression_predicates.items);
                unsupported_match_expression_predicates.deinit(alloc);
            }
            var unsupported_match_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer {
                freeExpressionPredicateGroups(alloc, unsupported_match_expression_or_predicates.items);
                unsupported_match_expression_or_predicates.deinit(alloc);
            }
            var unsupported_match_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer {
                freeExpressionPredicateGroups(alloc, unsupported_match_expression_not_predicates.items);
                unsupported_match_expression_not_predicates.deinit(alloc);
            }
            var unsupported_match_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
            defer {
                freeExpressionArrayContains(alloc, unsupported_match_expression_array_contains.items);
                unsupported_match_expression_array_contains.deinit(alloc);
            }

            const effective_side: JoinedMutationExpressionSide = switch (expression_side) {
                .single => .{ .single = .right },
                .mixed => .mixed,
            };
            var expression_targets = JoinWherePredicateTargets{
                .left_predicates = undefined,
                .right_predicates = undefined,
                .left_json_contains = undefined,
                .right_json_contains = undefined,
                .left_json_path_exists = undefined,
                .right_json_path_exists = undefined,
                .left_array_contains = undefined,
                .right_array_contains = undefined,
                .left_array_eq = undefined,
                .right_array_eq = undefined,
                .left_in_predicates = undefined,
                .right_in_predicates = undefined,
                .left_text_patterns = undefined,
                .right_text_patterns = undefined,
                .left_expression_predicates = &unsupported_left_expression_predicates,
                .right_expression_predicates = targets.expression_predicates,
                .left_expression_or_predicates = &unsupported_left_expression_or_predicates,
                .right_expression_or_predicates = targets.expression_or_predicates,
                .left_expression_not_predicates = &unsupported_left_expression_not_predicates,
                .right_expression_not_predicates = targets.expression_not_predicates,
                .left_expression_array_contains = &unsupported_left_expression_array_contains,
                .right_expression_array_contains = targets.expression_array_contains,
                .match_expression_predicates = targets.match_expression_predicates,
                .match_expression_or_predicates = targets.match_expression_or_predicates,
                .match_expression_not_predicates = targets.match_expression_not_predicates,
                .match_expression_array_contains = targets.match_expression_array_contains,
            };
            const saved_match_predicates = targets.match_expression_predicates;
            const saved_match_or = targets.match_expression_or_predicates;
            const saved_match_not = targets.match_expression_not_predicates;
            const saved_match_array = targets.match_expression_array_contains;
            if (effective_side == .mixed) {
                expression_targets.match_expression_predicates = targets.match_expression_predicates;
                expression_targets.match_expression_or_predicates = targets.match_expression_or_predicates;
                expression_targets.match_expression_not_predicates = targets.match_expression_not_predicates;
                expression_targets.match_expression_array_contains = targets.match_expression_array_contains;
            } else {
                expression_targets.match_expression_predicates = &unsupported_match_expression_predicates;
                expression_targets.match_expression_or_predicates = &unsupported_match_expression_or_predicates;
                expression_targets.match_expression_not_predicates = &unsupported_match_expression_not_predicates;
                expression_targets.match_expression_array_contains = &unsupported_match_expression_array_contains;
            }
            _ = saved_match_predicates;
            _ = saved_match_or;
            _ = saved_match_not;
            _ = saved_match_array;
            var expression_where_options_with_generated = expression_where_options;
            expression_where_options_with_generated.generated_expression_ast = generated_atom_expression;
            expression_where_options_with_generated.alternatives_hooks.generated_expression_ast = generated_atom_expression;
            expression_where_options_with_generated.expression_condition_hooks.generated_expression_ast = generated_atom_expression;
            try parseJoinedMutationExpressionWhereConditionWithContextAlloc(
                alloc,
                tokens,
                pos,
                effective_side,
                &expression_targets,
                left_alias,
                right_alias,
                expression_where_options_with_generated,
            );
            if (unsupported_left_expression_predicates.items.len != 0 or
                unsupported_left_expression_or_predicates.items.len != 0 or
                unsupported_left_expression_not_predicates.items.len != 0 or
                unsupported_left_expression_array_contains.items.len != 0 or
                unsupported_match_expression_predicates.items.len != 0 or
                unsupported_match_expression_or_predicates.items.len != 0 or
                unsupported_match_expression_not_predicates.items.len != 0 or
                unsupported_match_expression_array_contains.items.len != 0) return error.UnsupportedSqlShape;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }

        const lhs = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
        defer plan_mod.freeQualifiedField(alloc, lhs);
        const lhs_side = try binder.joinSideForQualifier(lhs.qualifier, left_alias, right_alias);
        const column = try binder.joinColumnForSide(schema, joined_source_schema, lhs_side, lhs.field);

        if (parser.matchToken(tokens, pos, .at_contains) != null) {
            try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(generated_atom_expression, .contains, tokens, pos.* - 1);
            if (lhs_side != .right) return error.UnsupportedSqlShape;
            const value_json = try value_mod.parseStructuredPredicateValueAlloc(alloc, tokens, pos, params, column);
            var value_transferred = false;
            errdefer if (!value_transferred) alloc.free(value_json);
            const field = try alloc.dupe(u8, lhs.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            if (column.field_type == .array) {
                try value_mod.validateSqlArrayValueJson(alloc, column, value_json);
                try targets.array_contains.append(alloc, .{ .field = field, .value_json = value_json });
            } else {
                if (column.field_type != .json) return error.InvalidSqlCatalog;
                try targets.json_contains.append(alloc, .{ .field = field, .value_json = value_json });
            }
            field_transferred = true;
            value_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (parser.matchToken(tokens, pos, .question) != null) {
            try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(generated_atom_expression, .json_key_exists, tokens, pos.* - 1);
            if (lhs_side != .right) return error.UnsupportedSqlShape;
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            const path = try value_mod.parseJsonPathOwnedAlloc(alloc, tokens, pos, params);
            var path_transferred = false;
            errdefer if (!path_transferred) alloc.free(path);
            const field = try alloc.dupe(u8, lhs.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            try targets.json_path_exists.append(alloc, .{ .field = field, .path = path });
            field_transferred = true;
            path_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (parser.matchKeyword(tokens, pos, "like") or parser.matchKeyword(tokens, pos, "ilike")) {
            if (lhs_side != .right) return error.UnsupportedSqlShape;
            const case_insensitive = tokens[pos.* - 1].matchesKeywordTag(.ilike);
            const generated_kind: generated_parser.GeneratedSqlExpressionKind = if (case_insensitive) .ilike else .like;
            const generated_quantifier_token_index: ?usize = if (expr_token.tokenAtIsAnySomeOrAll(tokens, pos.*)) pos.* else null;
            try expr_generated_validate.validateGeneratedPatternPredicateIdentity(generated_atom_expression, generated_kind, tokens, pos.* - 1, generated_quantifier_token_index);
            try expr_predicate.parseAndAppendTextPatternPredicateAlloc(alloc, tokens, pos, params, targets.text_patterns, lhs.field, column, case_insensitive, false, realtime_ns);
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (parser.matchKeyword(tokens, pos, "not")) {
            const negation_token_index = pos.* - 1;
            if (lhs_side != .right) return error.UnsupportedSqlShape;
            if (parser.matchKeyword(tokens, pos, "like") or parser.matchKeyword(tokens, pos, "ilike")) {
                const case_insensitive = tokens[pos.* - 1].matchesKeywordTag(.ilike);
                const generated_kind: generated_parser.GeneratedSqlExpressionKind = if (case_insensitive) .not_ilike else .not_like;
                const generated_quantifier_token_index: ?usize = if (expr_token.tokenAtIsAnySomeOrAll(tokens, pos.*)) pos.* else null;
                try expr_generated_validate.validateGeneratedPatternPredicateIdentity(generated_atom_expression, generated_kind, tokens, pos.* - 1, generated_quantifier_token_index);
                try expr_predicate.parseAndAppendTextPatternPredicateAlloc(alloc, tokens, pos, params, targets.text_patterns, lhs.field, column, case_insensitive, true, realtime_ns);
                if (!parser.matchKeyword(tokens, pos, "and")) break;
                continue;
            }
            try parser.expectKeyword(tokens, pos, "in");
            try expr_generated_validate.validateGeneratedSetOrBetweenPredicateIdentity(generated_atom_expression, .not_in_list, tokens, pos.* - 1, negation_token_index, null);
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            const values_json = try value_mod.parseSqlInValuesJsonAlloc(alloc, tokens, pos, params);
            var values_transferred = false;
            errdefer if (!values_transferred) alloc.free(values_json);
            try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
            const field = try alloc.dupe(u8, lhs.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
            var collation_transferred = false;
            errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
            try targets.in_predicates.append(alloc, .{ .field = field, .values_json = values_json, .negated = true, .collation = collation });
            field_transferred = true;
            values_transferred = true;
            collation_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (parser.matchKeyword(tokens, pos, "in")) {
            try expr_generated_validate.validateGeneratedSetOrBetweenPredicateIdentity(generated_atom_expression, .in_list, tokens, pos.* - 1, null, null);
            if (lhs_side != .right) return error.UnsupportedSqlShape;
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            const values_json = try value_mod.parseSqlInValuesJsonAlloc(alloc, tokens, pos, params);
            var values_transferred = false;
            errdefer if (!values_transferred) alloc.free(values_json);
            try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
            const field = try alloc.dupe(u8, lhs.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
            var collation_transferred = false;
            errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
            try targets.in_predicates.append(alloc, .{ .field = field, .values_json = values_json, .negated = false, .collation = collation });
            field_transferred = true;
            values_transferred = true;
            collation_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }

        const op_token_index = pos.*;
        const op: runtime_schema.RelationalCheckOp = if (try expr_operator.parseExpressionIsTailIf(tokens, pos, .{
            .allow_distinct = false,
            .allow_boolean_unknown = true,
            .allow_boolean_literal = true,
            .allow_boolean_literal_negation = true,
        })) |is_tail| blk: {
            try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_atom_expression, tokens, op_token_index, is_tail);
            if (lhs_side != .right) return error.UnsupportedSqlShape;
            switch (is_tail.kind) {
                .distinct_comparison => unreachable,
                .null_test => {},
                .boolean_unknown => {
                    if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                    break :blk is_tail.op;
                },
                .boolean_literal => {
                    if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                    if (is_tail.boolean_negated) {
                        try expr_condition.appendBooleanIsNotExpressionGroups(alloc, targets.expression_or_predicates, lhs.field, is_tail.boolean_value);
                        if (!parser.matchKeyword(tokens, pos, "and")) break;
                        continue;
                    }
                    const value_json = try alloc.dupe(u8, value_mod.booleanJson(is_tail.boolean_value));
                    var value_transferred = false;
                    errdefer if (!value_transferred) alloc.free(value_json);
                    const field = try alloc.dupe(u8, lhs.field);
                    var field_transferred = false;
                    errdefer if (!field_transferred) alloc.free(field);
                    try targets.predicates.append(alloc, .{
                        .name = "",
                        .field = field,
                        .op = .eq,
                        .value_json = value_json,
                    });
                    field_transferred = true;
                    value_transferred = true;
                    if (!parser.matchKeyword(tokens, pos, "and")) break;
                    continue;
                },
            }
            break :blk is_tail.op;
        } else try expr_operator.parseComparisonOp(tokens, pos);
        if (op == .eq and expr_token.matchAnyOrSomeKeyword(tokens, pos)) {
            try expr_generated_validate.validateGeneratedQuantifiedPredicateIdentity(generated_atom_expression, tokens, op_token_index, pos.* - 1);
            if (lhs_side != .right) return error.UnsupportedSqlShape;
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            try parser.expectToken(tokens, pos, .lparen);
            const values_json = try value_mod.parseJsonArrayValueAlloc(alloc, tokens, pos, params);
            var values_transferred = false;
            errdefer if (!values_transferred) alloc.free(values_json);
            try parser.expectToken(tokens, pos, .rparen);
            try value_mod.validateSqlScalarValuesJson(alloc, column, values_json);
            const field = try alloc.dupe(u8, lhs.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
            var collation_transferred = false;
            errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
            try targets.in_predicates.append(alloc, .{ .field = field, .values_json = values_json, .negated = false, .collation = collation });
            field_transferred = true;
            values_transferred = true;
            collation_transferred = true;
            if (!parser.matchKeyword(tokens, pos, "and")) break;
            continue;
        }
        if (pos.* < tokens.len and tokens[pos.*].kind == .identifier and identifierContainsQualifier(tokens[pos.*].text)) {
            if (op != .eq) return error.UnsupportedSqlShape;
            const rhs = try plan_mod.parseQualifiedFieldAlloc(alloc, tokens, pos);
            defer plan_mod.freeQualifiedField(alloc, rhs);
            const rhs_side = try binder.joinSideForQualifier(rhs.qualifier, left_alias, right_alias);
            if (lhs_side == rhs_side) return error.UnsupportedSqlShape;
            const rhs_column = try binder.joinColumnForSide(schema, joined_source_schema, rhs_side, rhs.field);
            if (column.field_type != rhs_column.field_type) return error.UnsupportedSqlShape;
            try expr_generated_validate.validateGeneratedRelationalPredicateExpression(generated_atom_expression, tokens, op_token_index, op);
            const left_source = if (lhs_side == .left) lhs.field else rhs.field;
            const right_source = if (lhs_side == .right) lhs.field else rhs.field;
            const left_field = try alloc.dupe(u8, left_source);
            var left_transferred = false;
            errdefer if (!left_transferred) alloc.free(left_field);
            const right_field = try alloc.dupe(u8, right_source);
            var right_transferred = false;
            errdefer if (!right_transferred) alloc.free(right_field);
            try targets.correlations.append(alloc, .{ .left_field = left_field, .right_field = right_field });
            left_transferred = true;
            right_transferred = true;
        } else {
            try expr_generated_validate.validateGeneratedRelationalPredicateExpression(generated_atom_expression, tokens, op_token_index, op);
            if (lhs_side != .right) return error.UnsupportedSqlShape;
            const value_json = if (op == .is_null or op == .is_not_null)
                null
            else if (column.field_type == .array and op == .eq)
                try value_mod.parseArrayPredicateValueAlloc(alloc, tokens, pos, params)
            else
                try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
            var value_transferred = false;
            errdefer if (!value_transferred) if (value_json) |json| alloc.free(json);
            const field = try alloc.dupe(u8, lhs.field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            if (column.field_type == .array and op == .eq) {
                try value_mod.validateSqlArrayValueJson(alloc, column, value_json.?);
                try targets.array_eq.append(alloc, .{ .field = field, .value_json = value_json.? });
                field_transferred = true;
                value_transferred = true;
                if (!parser.matchKeyword(tokens, pos, "and")) break;
                continue;
            }
            const collation = if (column.collation) |value| try alloc.dupe(u8, value) else null;
            var collation_transferred = false;
            errdefer if (!collation_transferred) if (collation) |value| alloc.free(value);
            try targets.predicates.append(alloc, .{ .name = "", .field = field, .op = op, .value_json = value_json, .collation = collation });
            field_transferred = true;
            value_transferred = true;
            collation_transferred = true;
        }
        if (!parser.matchKeyword(tokens, pos, "and")) break;
    }
}

pub fn joinedMutationExpressionSideAt(
    tokens: []const Token,
    pos: usize,
    target_alias: []const u8,
    source_alias: []const u8,
    string_to_array_predicate_is_containment: bool,
) !?JoinedMutationExpressionSide {
    if (!joinedMutationExpressionCanStartAt(tokens, pos, string_to_array_predicate_is_containment)) return null;

    var side: ?db_mod.types.RelationalRowsJoinProjectionSide = null;
    var mixed = false;
    var depth: usize = 0;
    var i = pos;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) break;
                depth -= 1;
            },
            .semicolon => if (depth == 0) break,
            .identifier => {
                if (depth == 0 and (token.matchesKeywordTag(.@"and") or
                    token.matchesKeywordTag(.@"or") or
                    expr_token.sqlWhereTailClauseKeywordToken(token)))
                {
                    break;
                }
                if (identifierContainsQualifier(token.text)) {
                    const dot = std.mem.indexOfScalar(u8, token.text, '.') orelse unreachable;
                    const next_side = try binder.joinSideForQualifier(token.text[0..dot], target_alias, source_alias);
                    if (side) |existing| {
                        if (existing != next_side) mixed = true;
                    } else {
                        side = next_side;
                    }
                }
            },
            else => {},
        }
    }
    if (mixed) return .mixed;
    if (side) |single| return .{ .single = single };
    return null;
}

pub fn joinedMutationExpressionCanStartAt(
    tokens: []const Token,
    pos: usize,
    string_to_array_predicate_is_containment: bool,
) bool {
    if (pos >= tokens.len) return false;
    if (tokens[pos].kind == .identifier and pos + 1 < tokens.len and identifierContainsQualifier(tokens[pos].text)) {
        return switch (tokens[pos + 1].kind) {
            .plus, .minus, .star, .slash, .percent, .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text, .pipe_concat, .question_any, .question_all => true,
            else => false,
        };
    }
    if (expressionPredicateCanStartAt(tokens, pos)) return true;
    if (canParseExpressionNotWhere(tokens, pos)) return true;
    if (parser.peekKeyword(tokens, pos, "string_to_array") and string_to_array_predicate_is_containment) return true;
    if (tokens[pos].kind == .lparen) {
        const inner = parser.predicateStartIndexAfterOpenParens(tokens, pos);
        return expressionPredicateCanStartAt(tokens, inner);
    }
    return false;
}

pub fn peekConflictExistingFieldIncrement(
    tokens: []const Token,
    pos: usize,
    field: []const u8,
    column: runtime_schema.RelationalColumn,
) bool {
    if (column.field_type != .numeric) return false;
    if (pos + 1 >= tokens.len or tokens[pos].kind != .identifier) return false;
    if (!std.mem.eql(u8, tokens[pos].text, field)) return false;
    const op = tokens[pos + 1].kind;
    if (op != .plus and op != .minus) return false;
    return !expr_operator.peekArithmeticRhsKeyword(tokens, pos, "interval");
}

pub fn peekSimpleScalarSetPredicate(tokens: []const Token, pos: usize) bool {
    if (pos + 1 >= tokens.len or tokens[pos].kind != .identifier) return false;
    if (pos + 2 < tokens.len and
        tokens[pos + 1].matchesKeywordTag(.not) and
        tokens[pos + 2].matchesKeywordTag(.in))
    {
        return true;
    }
    if (tokens[pos + 1].matchesKeywordTag(.in)) return true;
    if (pos + 2 >= tokens.len) return false;
    if (tokens[pos + 1].kind != .eq and tokens[pos + 1].kind != .neq) return false;
    return tokens[pos + 2].matchesKeywordTag(.any) or
        tokens[pos + 2].matchesKeywordTag(.some) or
        tokens[pos + 2].matchesKeywordTag(.all);
}

pub fn canParseScalarNotWhere(tokens: []const Token, pos: usize) bool {
    if (!parser.peekKeywordTag(tokens, pos, .not) or pos + 1 >= tokens.len or tokens[pos + 1].kind != .lparen) return false;
    var i = pos + 2;
    var depth: usize = 1;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => return false,
            .rparen => {
                depth -= 1;
                if (depth == 0) return true;
            },
            .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json, .at_contains, .range_overlap, .question => return false,
            .identifier => {
                if (token.matchesKeywordTag(.any) or
                    token.matchesKeywordTag(.some) or
                    token.matchesKeywordTag(.between) or
                    token.matchesKeywordTag(.in) or
                    token.matchesKeywordTag(.exists))
                {
                    return false;
                }
                if (token.matchesKeywordTag(.not)) {
                    if (i == 0 or tokens[i - 1].kind != .identifier or
                        !tokens[i - 1].matchesKeywordTag(.is))
                    {
                        return false;
                    }
                }
            },
            else => {},
        }
    }
    return false;
}

pub fn parseScalarWherePredicateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    params: []const value_mod.SqlValue,
    realtime_ns: u64,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !runtime_schema.RelationalCheck {
    const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    defer alloc.free(parsed_field);
    const field = try binder.normalizeRowExpressionFieldAlloc(alloc, schema, parsed_field, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation);
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    if (expr_operator.peekJsonExtractOperator(tokens, pos.*) or parser.peekKind(tokens, pos.*, .at_contains) or parser.peekKind(tokens, pos.*, .range_overlap) or parser.peekKind(tokens, pos.*, .question)) return error.UnsupportedSqlShape;
    const column = binder.relationalColumnForField(schema, field, null) orelse return error.InvalidSqlCatalog;
    if (column.field_type == .array or column.field_type == .json) return error.UnsupportedSqlShape;

    const is_tail_token_index = pos.*;
    if (try expr_operator.parseExpressionIsTailIf(tokens, pos, .{
        .allow_boolean_unknown = true,
        .allow_boolean_literal = true,
    })) |is_tail| {
        switch (is_tail.kind) {
            .distinct_comparison => {
                try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_expression_ast, tokens, is_tail_token_index, is_tail);
                const value_json = try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
                var value_transferred = false;
                errdefer if (!value_transferred) alloc.free(value_json);
                field_transferred = true;
                value_transferred = true;
                return .{
                    .name = "",
                    .field = field,
                    .op = is_tail.op,
                    .value_json = value_json,
                };
            },
            .boolean_unknown => {
                try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_expression_ast, tokens, is_tail_token_index, is_tail);
                if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                field_transferred = true;
                return .{
                    .name = "",
                    .field = field,
                    .op = is_tail.op,
                    .value_json = null,
                };
            },
            .boolean_literal => {
                try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_expression_ast, tokens, is_tail_token_index, is_tail);
                if (column.field_type != .boolean) return error.InvalidSqlCatalog;
                const value_json = try alloc.dupe(u8, value_mod.booleanJson(is_tail.boolean_value));
                var value_transferred = false;
                errdefer if (!value_transferred) alloc.free(value_json);
                field_transferred = true;
                value_transferred = true;
                return .{
                    .name = "",
                    .field = field,
                    .op = .eq,
                    .value_json = value_json,
                };
            },
            .null_test => {},
        }
        try expr_generated_validate.validateGeneratedIsTailPredicateExpression(generated_expression_ast, tokens, is_tail_token_index, is_tail);
        field_transferred = true;
        return .{
            .name = "",
            .field = field,
            .op = is_tail.op,
            .value_json = null,
        };
    }

    const postfix_null_token_index = pos.*;
    if (expr_operator.matchPostfixNullTest(tokens, pos)) |op| {
        try expr_generated_validate.validateGeneratedPostfixNullPredicateExpression(generated_expression_ast, tokens, postfix_null_token_index, op);
        field_transferred = true;
        return .{
            .name = "",
            .field = field,
            .op = op,
            .value_json = null,
        };
    }

    if (parser.peekKeywordTag(tokens, pos.*, .in) or parser.peekKeywordTag(tokens, pos.*, .not)) return error.UnsupportedSqlShape;
    if (parser.peekKeywordTag(tokens, pos.*, .between)) return error.UnsupportedSqlShape;
    const op_token_index = pos.*;
    const op = try expr_operator.parseComparisonOp(tokens, pos);
    try expr_generated_validate.validateGeneratedRelationalPredicateExpression(generated_expression_ast, tokens, op_token_index, op);
    if (parser.peekKeywordTag(tokens, pos.*, .any) or parser.peekKeywordTag(tokens, pos.*, .some)) return error.UnsupportedSqlShape;
    const value_json = try value_mod.parseSqlColumnValueAlloc(alloc, tokens, pos, params, column, realtime_ns);
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    field_transferred = true;
    value_transferred = true;
    return .{
        .name = "",
        .field = field,
        .op = op,
        .value_json = value_json,
    };
}

fn expressionStartKeywordToken(token: Token) bool {
    return token.matchesKeywordTag(.abs) or
        token.matchesKeywordTag(.array_append) or
        token.matchesKeywordTag(.array_cat) or
        token.matchesKeywordTag(.array_prepend) or
        token.matchesKeywordTag(.array_remove) or
        token.matchesKeywordTag(.array_replace) or
        token.matchesKeywordTag(.array_to_string) or
        token.matchesKeywordTag(.ascii) or
        token.matchesKeywordTag(.bit_length) or
        token.matchesKeywordTag(.case) or
        token.matchesKeywordTag(.cast) or
        token.matchesKeywordTag(.chr) or
        token.matchesKeywordTag(.coalesce) or
        token.matchesKeywordTag(.concat) or
        token.matchesKeywordTag(.concat_ws) or
        token.matchesKeywordTag(.convert_from) or
        token.matchesKeywordTag(.current_date) or
        token.matchesKeywordTag(.current_timestamp) or
        token.matchesKeywordTag(.false) or
        token.matchesKeywordTag(.length) or
        token.matchesKeywordTag(.lower) or
        token.matchesKeywordTag(.now) or
        token.matchesKeywordTag(.null) or
        token.matchesKeywordTag(.nullif) or
        token.matchesKeywordTag(.octet_length) or
        token.matchesKeywordTag(.replace) or
        token.matchesKeywordTag(.round) or
        token.matchesKeywordTag(.string_to_array) or
        token.matchesKeywordTag(.trim) or
        token.matchesKeywordTag(.true) or
        token.matchesKeywordTag(.upper);
}

pub fn expressionCanStartAt(tokens: []const Token, index: usize) bool {
    if (index >= tokens.len) return false;
    const token = tokens[index];
    if (token.kind == .minus) return true;
    if (token.kind == .number or token.kind == .string or token.kind == .placeholder) return true;
    if (token.kind != .identifier) return false;
    if (expr_token.functionCallStartsAtTokenIf(tokens, index, expr_token.sqlTokenIsArrayLengthFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, index, expr_token.sqlTokenIsArrayPositionFunction) or
        expressionStartKeywordToken(token) or
        expr_token.functionCallStartsAtTag(tokens, index, .gen_random_uuid) or
        expr_token.functionCallStartsAtTag(tokens, index, .uuid_generate_v4) or
        expr_token.functionCallStartsAtTag(tokens, index, .floor) or
        expr_token.functionCallStartsAtTag(tokens, index, .ceil) or
        expr_token.functionCallStartsAtTag(tokens, index, .sqrt) or
        expr_token.functionCallStartsAtTag(tokens, index, .sign) or
        expr_token.functionCallStartsAtTag(tokens, index, .mod) or
        expr_token.functionCallStartsAtTag(tokens, index, .power) or
        expr_token.sqlTokenIsOverlayFunction(token) or
        expr_token.functionCallStartsAtTag(tokens, index, .trunc) or
        expr_token.sqlTokenIsTrimVariantFunction(token) or
        expr_token.sqlTokenIsPadFunction(token) or
        expr_token.sqlTokenIsRepeatFunction(token) or
        expr_token.sqlTokenIsReverseFunction(token) or
        expr_token.sqlTokenIsInitcapFunction(token) or
        expr_token.sqlTokenIsMd5Function(token) or
        expr_token.sqlTokenIsStartsWithFunction(token) or
        expr_token.sqlTokenIsEndsWithFunction(token) or
        expr_token.sqlTokenIsDateTruncFunction(token) or
        expr_token.sqlTokenIsDateBinFunction(token) or
        expr_token.sqlTokenIsDatePartFunction(token) or
        (expr_token.sqlTokenIsJsonExtractPathFunction(token) and index + 1 < tokens.len and tokens[index + 1].kind == .lparen) or
        (expr_token.sqlTokenIsJsonTypeofFunction(token) and index + 1 < tokens.len and tokens[index + 1].kind == .lparen) or
        (expr_token.sqlTokenIsJsonArrayLengthFunction(token) and index + 1 < tokens.len and tokens[index + 1].kind == .lparen) or
        (expr_token.sqlTokenIsJsonBuildObjectFunction(token) and index + 1 < tokens.len and tokens[index + 1].kind == .lparen) or
        (token.matchesKeywordTag(.to_jsonb) and index + 1 < tokens.len and tokens[index + 1].kind == .lparen) or
        expr_token.sqlTokenIsRegexpMatchFunction(token) or
        expr_token.sqlTokenIsRegexpCountFunction(token) or
        expr_token.sqlTokenIsRegexpSubstrFunction(token) or
        expr_token.sqlTokenIsRegexpInstrFunction(token) or
        expr_token.sqlTokenIsTranslateFunction(token))
    {
        return true;
    }
    if (expr_operator.jsonExtractMembershipPredicateCanStartAt(tokens, index) or
        expr_operator.jsonExtractNullSafeDistinctPredicateCanStartAt(tokens, index) or
        expr_operator.jsonExtractNullTestPredicateCanStartAt(tokens, index))
    {
        return true;
    }
    return index + 1 < tokens.len and switch (tokens[index + 1].kind) {
        .plus, .minus, .star, .slash, .percent => true,
        else => false,
    };
}

pub fn canParseBareBooleanWhereExpression(tokens: []const Token, pos: usize, schema: runtime_schema.TableSchema) bool {
    if (!booleanExpressionCanStartAt(tokens, pos, schema)) return false;

    var depth: usize = 0;
    var i = pos;
    var saw_boolean_syntax = false;
    var saw_token = false;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .semicolon, .comma => if (depth == 0) break,
            .rparen => {
                if (depth == 0) break;
                depth -= 1;
            },
            .lparen => {
                depth += 1;
                saw_token = true;
            },
            .eq, .neq, .gt, .gte, .lt, .lte, .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json, .at_contains, .range_overlap, .question, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => return false,
            .identifier => {
                if (depth == 0 and expr_token.sqlWhereTailClauseKeywordToken(token)) break;
                if (expr_token.sqlKeywordStartsScalarPredicate(token.text)) return false;
                if (token.matchesKeywordTag(.@"and") or
                    token.matchesKeywordTag(.@"or") or
                    token.matchesKeywordTag(.not))
                {
                    saw_boolean_syntax = true;
                }
                saw_token = true;
            },
            else => saw_token = true,
        }
    }
    if (!saw_token) return false;
    return saw_boolean_syntax or singleBooleanExpressionCanStartAt(tokens, pos, schema);
}

pub fn parseBareBooleanWhereExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    type_context: expr_type.RowExpressionTypeContext,
    expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
    options: BareBooleanWhereExpressionParserOptions,
) !void {
    const start = pos.*;
    const expression = try expr_row_parse.parseBooleanRowExpressionAlloc(alloc, tokens, pos, type_context, options.boolean_hooks);
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeExpression(alloc, expression);
    try type_context.validateBooleanRowExpression(expression);
    try expr_generated_validate.validateGeneratedRowExpressionIdentityStrict(tokens, start, pos.*, expression, options.generated_expression_ast);
    if (expression.kind == .value and std.mem.eql(u8, expression.value_json, "true")) {
        freeExpression(alloc, expression);
        expression_transferred = true;
        return;
    }

    const value_json = try alloc.dupe(u8, "true");
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);
    const rhs = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
    var rhs_transferred = false;
    errdefer if (!rhs_transferred) alloc.free(rhs);
    rhs[0] = .{
        .kind = .value,
        .value_json = value_json,
    };

    try expression_predicates.append(alloc, .{
        .lhs = expression,
        .op = .eq,
        .rhs = rhs,
    });
    expression_transferred = true;
    value_transferred = true;
    rhs_transferred = true;
}

pub fn booleanExpressionCanStartAt(tokens: []const Token, index: usize, schema: runtime_schema.TableSchema) bool {
    if (index >= tokens.len) return false;
    if (tokens[index].kind == .lparen) {
        const inner = parser.predicateStartIndexAfterOpenParens(tokens, index);
        return booleanExpressionCanStartAt(tokens, inner, schema);
    }
    return singleBooleanExpressionCanStartAt(tokens, index, schema);
}

fn singleBooleanExpressionCanStartAt(tokens: []const Token, index: usize, schema: runtime_schema.TableSchema) bool {
    if (index >= tokens.len) return false;
    const token = tokens[index];
    if (token.kind != .identifier) return false;
    return token.matchesKeywordTag(.not) or
        token.matchesKeywordTag(.true) or
        token.matchesKeywordTag(.false) or
        token.matchesKeywordTag(.case) or
        token.matchesKeywordTag(.cast) or
        token.matchesKeywordTag(.coalesce) or
        token.matchesKeywordTag(.nullif) or
        expr_token.sqlTokenIsRegexpMatchFunction(token) or
        expr_token.sqlTokenIsStartsWithFunction(token) or
        binder.relationalColumnForField(schema, token.text, null) != null;
}

pub fn textPatternSetPredicateCanStartAt(tokens: []const Token, index: usize) bool {
    if (index >= tokens.len) return false;
    if (tokens[index].kind != .identifier and !expressionCanStartAt(tokens, index)) return false;
    var depth: usize = 0;
    var i = index;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
            },
            .semicolon, .comma => if (depth == 0) return false,
            .identifier => if (depth == 0) {
                if (token.matchesKeywordTag(.like) or
                    token.matchesKeywordTag(.ilike))
                {
                    return expr_token.tokenAtIsAnySomeOrAll(tokens, i + 1);
                }
                if (token.matchesKeywordTag(.not) and i + 2 < tokens.len and
                    (tokens[i + 1].matchesKeywordTag(.like) or
                        tokens[i + 1].matchesKeywordTag(.ilike)))
                {
                    return expr_token.tokenAtIsAnySomeOrAll(tokens, i + 2);
                }
                if (expr_token.rowExpressionBoundaryKeywordToken(token)) return false;
            },
            else => {},
        }
    }
    return false;
}

pub fn expressionNullSafeDistinctPredicateCanStartAt(tokens: []const Token, index: usize) bool {
    if (!expressionCanStartAt(tokens, index)) return false;
    var depth: usize = 0;
    var i = index;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
            },
            .identifier => if (depth == 0 and token.matchesKeywordTag(.is)) {
                var distinct_index = i + 1;
                if (distinct_index < tokens.len and tokens[distinct_index].matchesKeywordTag(.not)) {
                    distinct_index += 1;
                }
                return distinct_index + 1 < tokens.len and
                    tokens[distinct_index].matchesKeywordTag(.distinct) and
                    tokens[distinct_index + 1].matchesKeywordTag(.from);
            } else if (depth == 0 and expr_token.rowExpressionBoundaryKeywordToken(token)) {
                return false;
            },
            .semicolon, .comma => if (depth == 0) return false,
            else => {},
        }
    }
    return false;
}

pub fn canParseExpressionNotWhere(tokens: []const Token, pos: usize) bool {
    if (!parser.peekKeywordTag(tokens, pos, .not) or pos + 2 >= tokens.len or tokens[pos + 1].kind != .lparen) return false;
    const inner = parser.predicateStartIndexAfterOpenParens(tokens, pos + 1);
    return expressionCanStartAt(tokens, inner) or
        expr_operator.jsonKeySetExpressionCanStartAt(tokens, inner) or
        expr_operator.jsonExtractExpressionPredicateCanStartAt(tokens, inner) or
        expr_operator.jsonExtractNullTestPredicateCanStartAt(tokens, inner);
}

pub fn canParseAccessNotWhere(tokens: []const Token, pos: usize) bool {
    if (!parser.peekKeywordTag(tokens, pos, .not)) return false;
    var i = pos + 1;
    while (i < tokens.len and tokens[i].kind == .lparen) : (i += 1) {}
    if (i >= tokens.len) return false;
    var depth: usize = 0;
    while (i < tokens.len) : (i += 1) {
        const token = tokens[i];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => if (depth == 0) {
                return false;
            } else {
                depth -= 1;
            },
            .arrow_text, .arrow_json, .path_arrow_text, .path_arrow_json, .at_contains, .range_overlap, .question => return true,
            .identifier => {
                if (token.matchesKeywordTag(.like) or
                    token.matchesKeywordTag(.ilike))
                {
                    return true;
                }
                if (i + 2 < tokens.len and
                    (tokens[i + 1].kind == .eq or tokens[i + 1].kind == .neq) and
                    tokens[i + 2].matchesKeywordTag(.array))
                {
                    return true;
                }
            },
            else => {},
        }
    }
    return false;
}

pub fn canParseExpressionWhereCondition(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
) !bool {
    if (value_mod.peekStandaloneSqlBooleanLiteral(tokens, pos) != null) return true;
    if (defer_row_expression_field_validation and parser.peekKind(tokens, pos, .identifier) and pos + 1 < tokens.len) {
        switch (tokens[pos + 1].kind) {
            .eq, .neq, .gt, .gte, .lt, .lte => {
                if (binder.relationalColumnForField(schema, tokens[pos].text, null) != null) return false;
                return true;
            },
            else => if (tokens[pos + 1].matchesKeywordTag(.is) or
                tokens[pos + 1].matchesKeywordTag(.not) or
                tokens[pos + 1].matchesKeywordTag(.in) or
                tokens[pos + 1].matchesKeywordTag(.between))
            {
                if (binder.relationalColumnForField(schema, tokens[pos].text, null) != null) return false;
                return true;
            },
        }
    }
    if (rowExpressionHasTopLevelPipeConcat(tokens, pos)) return true;
    if (parser.peekKind(tokens, pos, .minus)) return true;
    if (parser.peekKeyword(tokens, pos, "lower") or parser.peekKeyword(tokens, pos, "upper")) {
        return !(try expr_generated.generatedExpressionCallHasGeneratedColumn(
            alloc,
            tokens,
            pos,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        ));
    }
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsInitcapFunction)) return true;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsMd5Function)) {
        return !(try expr_generated.generatedExpressionCallHasGeneratedColumn(
            alloc,
            tokens,
            pos,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        ));
    }
    if (parser.peekKeyword(tokens, pos, "concat") or parser.peekKeyword(tokens, pos, "concat_ws")) {
        return !(try expr_generated.generatedExpressionCallHasGeneratedColumn(
            alloc,
            tokens,
            pos,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        ));
    }
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonExtractPathFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonTypeofFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonArrayLengthFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsJsonBuildObjectFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayLengthFunction) or
        expr_token.functionCallStartsAtTokenIf(tokens, pos, expr_token.sqlTokenIsArrayPositionFunction) or
        parser.peekKeyword(tokens, pos, "array_append") or
        parser.peekKeyword(tokens, pos, "array_prepend") or
        parser.peekKeyword(tokens, pos, "array_cat") or
        parser.peekKeyword(tokens, pos, "array_remove") or
        parser.peekKeyword(tokens, pos, "array_replace") or
        parser.peekKeyword(tokens, pos, "array_to_string") or
        parser.peekKeyword(tokens, pos, "case") or
        parser.peekKeyword(tokens, pos, "cast") or
        parser.peekKeyword(tokens, pos, "coalesce") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction) or
        parser.peekKeyword(tokens, pos, "nullif") or
        expr_token.peekTextLengthFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsAsciiFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsChrFunction) or
        expr_token.peekSubstringFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction) or
        expr_token.peekSplitPartFunctionKeyword(tokens, pos) or
        expr_token.peekStrposFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction) or
        parser.peekKeyword(tokens, pos, "position") or
        parser.peekKeyword(tokens, pos, "abs") or
        parser.peekKeyword(tokens, pos, "round") or
        expr_token.peekFunctionCallTag(tokens, pos, .trunc) or
        expr_token.peekFunctionCallTag(tokens, pos, .floor) or
        expr_token.peekFunctionCallTag(tokens, pos, .ceil) or
        expr_token.peekFunctionCallTag(tokens, pos, .sqrt) or
        expr_token.peekFunctionCallTag(tokens, pos, .sign) or
        expr_token.peekFunctionCallTag(tokens, pos, .mod) or
        expr_token.peekFunctionCallTag(tokens, pos, .power) or
        parser.peekKeyword(tokens, pos, "greatest") or
        parser.peekKeyword(tokens, pos, "least")) return true;
    if (expressionNullSafeDistinctPredicateCanStartAt(tokens, pos)) return true;
    if (textPatternSetPredicateCanStartAt(tokens, pos)) return true;
    if (parser.peekKeyword(tokens, pos, "trim")) return true;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTrimVariantFunction)) return true;
    if (parser.peekKeyword(tokens, pos, "replace")) return true;
    if (parser.peekKeyword(tokens, pos, "regexp_replace")) return true;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction)) return true;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction)) return true;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction)) return true;
    if (expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction)) return true;
    if (parser.peekKeyword(tokens, pos, "concat_ws")) return true;
    if (expr_operator.jsonExtractNullTestPredicateCanStartAt(tokens, pos)) return true;
    if (expr_operator.jsonExtractNullSafeDistinctPredicateCanStartAt(tokens, pos)) return true;
    if (expr_operator.jsonExtractMembershipPredicateCanStartAt(tokens, pos)) return true;
    if (expr_operator.jsonKeySetExpressionCanStartAt(tokens, pos)) return true;
    if (parser.peekKind(tokens, pos, .identifier) and
        !parser.peekKeyword(tokens, pos, "null") and
        !parser.peekKeyword(tokens, pos, "true") and
        !parser.peekKeyword(tokens, pos, "false") and
        pos + 1 < tokens.len)
    {
        return switch (tokens[pos + 1].kind) {
            .plus, .minus, .star, .slash, .percent, .pipe_concat, .regex_match, .regex_imatch, .regex_not_match, .regex_not_imatch => true,
            else => false,
        };
    }
    if (parenthesizedBooleanIsPredicateCanStartAt(tokens, pos, schema)) return true;
    return false;
}

fn parenthesizedBooleanIsPredicateCanStartAt(
    tokens: []const Token,
    index: usize,
    schema: runtime_schema.TableSchema,
) bool {
    if (index >= tokens.len or tokens[index].kind != .lparen) return false;
    const inner = parser.predicateStartIndexAfterOpenParens(tokens, index);
    if (!booleanExpressionCanStartAt(tokens, inner, schema)) return false;
    const close = parser.findMatchingRParenIndex(tokens, index) orelse return false;
    if (close + 2 >= tokens.len) return false;
    if (!tokens[close + 1].matchesKeywordTag(.is)) {
        return false;
    }
    var value_index = close + 2;
    if (tokens[value_index].matchesKeywordTag(.not)) {
        value_index += 1;
    }
    if (value_index >= tokens.len or tokens[value_index].kind != .identifier) return false;
    return tokens[value_index].matchesKeywordTag(.true) or
        tokens[value_index].matchesKeywordTag(.false) or
        tokens[value_index].matchesKeywordTag(.unknown);
}

pub fn expressionPredicateCanStartAt(tokens: []const Token, index: usize) bool {
    if (expressionCanStartAt(tokens, index) or
        textPatternSetPredicateCanStartAt(tokens, index) or
        expr_operator.jsonKeySetExpressionCanStartAt(tokens, index) or
        expr_operator.jsonExtractExpressionPredicateCanStartAt(tokens, index) or
        expr_operator.jsonExtractNullTestPredicateCanStartAt(tokens, index) or
        expr_operator.jsonExtractNullSafeDistinctPredicateCanStartAt(tokens, index) or
        expr_operator.jsonExtractMembershipPredicateCanStartAt(tokens, index))
    {
        return true;
    }
    if (index + 1 >= tokens.len or tokens[index].kind != .identifier) return false;
    const next = tokens[index + 1];
    return switch (next.kind) {
        .eq, .neq, .gt, .gte, .lt, .lte => true,
        .identifier => next.matchesKeywordTag(.is) or
            next.matchesKeywordTag(.in) or
            next.matchesKeywordTag(.not) or
            next.matchesKeywordTag(.between) or
            next.matchesKeywordTag(.like) or
            next.matchesKeywordTag(.ilike),
        else => false,
    };
}

pub fn nextIsUnsupportedQueryKeyword(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len or tokens[pos].kind != .identifier) return false;
    const token = tokens[pos];
    return token.matchesKeywordTag(.join) or
        token.matchesKeywordTag(.left) or
        token.matchesKeywordTag(.inner) or
        token.matchesKeywordTag(.group) or
        token.matchesKeywordTag(.with) or
        token.matchesKeywordTag(.over) or
        token.matchesKeywordTag(.lateral);
}

test "sql adapter expression keyword predicates classify function and tail tokens" {
    const tagged_expression_starts = [_]Token{
        .{ .kind = .identifier, .text = "CONCAT_WS", .keyword = .concat_ws },
        .{ .kind = .identifier, .text = "STRING_TO_ARRAY", .keyword = .string_to_array },
        .{ .kind = .identifier, .text = "CURRENT_TIMESTAMP", .keyword = .current_timestamp },
        .{ .kind = .identifier, .text = "REPLACE", .keyword = .replace },
    };
    for (tagged_expression_starts) |start| {
        try std.testing.expect(expressionStartKeywordToken(start));
        try std.testing.expect(expressionCanStartAt(&.{start}, 0));
    }
    const token_helper_expression_starts = [_]Token{
        .{ .kind = .identifier, .text = "MD5", .keyword = .md5 },
    };
    for (token_helper_expression_starts) |start| {
        try std.testing.expect(!expressionStartKeywordToken(start));
        try std.testing.expect(expressionCanStartAt(&.{start}, 0));
    }
    const quoted_expression_name = Token{ .kind = .identifier, .text = "concat_ws", .source_start = 0, .source_end = 11 };
    try std.testing.expect(!expressionStartKeywordToken(quoted_expression_name));

    const unsupported_tail_tokens = [_]Token{.{ .kind = .identifier, .text = "LATERAL", .keyword = .lateral }};
    try std.testing.expect(nextIsUnsupportedQueryKeyword(unsupported_tail_tokens[0..], 0));

    const top_level_window_tokens = [_]Token{
        .{ .kind = .identifier, .text = "SELECT", .keyword = .select },
        .{ .kind = .identifier, .text = "WINDOW", .keyword = .window },
    };
    try std.testing.expectEqual(@as(?usize, 1), topLevelWindowClauseStart(top_level_window_tokens[0..], 0));
    const quoted_window_tokens = [_]Token{
        .{ .kind = .identifier, .text = "window", .source_start = 0, .source_end = 8 },
    };
    try std.testing.expect(topLevelWindowClauseStart(quoted_window_tokens[0..], 0) == null);
    const value_any_tokens = [_]Token{
        .{ .kind = .identifier, .text = "TRUE", .keyword = .true },
        .{ .kind = .eq, .text = "=" },
        .{ .kind = .identifier, .text = "ANY", .keyword = .any },
        .{ .kind = .lparen, .text = "(" },
        .{ .kind = .identifier, .text = "flags" },
    };
    try std.testing.expect(valueEqualsAnyArrayPredicateCanStart(value_any_tokens[0..], 0));
    const quoted_value_any_tokens = [_]Token{
        .{ .kind = .identifier, .text = "true", .source_start = 0, .source_end = 6 },
        .{ .kind = .eq, .text = "=" },
        .{ .kind = .identifier, .text = "any", .source_start = 9, .source_end = 14 },
        .{ .kind = .lparen, .text = "(" },
        .{ .kind = .identifier, .text = "flags" },
    };
    try std.testing.expect(!valueEqualsAnyArrayPredicateCanStart(quoted_value_any_tokens[0..], 0));

    const length_tokens = [_]Token{
        .{ .kind = .identifier, .text = "char_length" },
        .{ .kind = .lparen, .text = "(" },
    };
    var length_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.length, try expr_token.parseTextLengthFunctionCallStart(length_tokens[0..], &length_pos));
    try std.testing.expectEqual(@as(usize, 2), length_pos);

    const abs_tokens = [_]Token{
        .{ .kind = .identifier, .text = "abs" },
        .{ .kind = .lparen, .text = "(" },
    };
    var abs_pos: usize = 0;
    try expr_token.parseFixedUnaryFunctionCallStart(abs_tokens[0..], &abs_pos, .abs);
    try std.testing.expectEqual(@as(usize, 2), abs_pos);

    const mod_tokens = [_]Token{
        .{ .kind = .identifier, .text = "mod" },
        .{ .kind = .lparen, .text = "(" },
    };
    var mod_pos: usize = 0;
    try expr_token.parseFixedBinaryFunctionCallStart(mod_tokens[0..], &mod_pos, .mod);
    try std.testing.expectEqual(@as(usize, 2), mod_pos);

    const greatest_tokens = [_]Token{
        .{ .kind = .identifier, .text = "greatest" },
        .{ .kind = .lparen, .text = "(" },
    };
    var greatest_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.greatest, try expr_token.parseGreatestLeastFunctionCallStart(greatest_tokens[0..], &greatest_pos));
    try std.testing.expectEqual(@as(usize, 2), greatest_pos);
    try std.testing.expect(expr_token.peekGreatestLeastFunctionCall(greatest_tokens[0..], 0));

    const case_fold_start_tokens = [_]Token{
        .{ .kind = .identifier, .text = "LTRIM", .keyword = .ltrim },
        .{ .kind = .lparen, .text = "(" },
    };
    var case_fold_start_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.ltrim, try expr_token.parseCaseFoldFunctionCallStart(case_fold_start_tokens[0..], &case_fold_start_pos));
    try std.testing.expectEqual(@as(usize, 2), case_fold_start_pos);
    const quoted_case_fold_start_tokens = [_]Token{
        .{ .kind = .identifier, .text = "ltrim", .source_start = 0, .source_end = 7 },
        .{ .kind = .lparen, .text = "(" },
    };
    var quoted_case_fold_start_pos: usize = 0;
    try std.testing.expectError(error.UnsupportedSqlShape, expr_token.parseCaseFoldFunctionCallStart(quoted_case_fold_start_tokens[0..], &quoted_case_fold_start_pos));

    const left_right_tokens = [_]Token{.{ .kind = .identifier, .text = "RIGHT", .keyword = .right }};
    var left_right_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.right, expr_token.matchLeftRightFunctionKind(left_right_tokens[0..], &left_right_pos).?);
    try std.testing.expectEqual(@as(usize, 1), left_right_pos);
    const quoted_left_right_tokens = [_]Token{.{ .kind = .identifier, .text = "right", .source_start = 0, .source_end = 7 }};
    var quoted_left_right_pos: usize = 0;
    try std.testing.expect(expr_token.matchLeftRightFunctionKind(quoted_left_right_tokens[0..], &quoted_left_right_pos) == null);

    const pad_tokens = [_]Token{.{ .kind = .identifier, .text = "RPAD", .keyword = .rpad }};
    var pad_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.rpad, expr_token.matchPadFunctionKind(pad_tokens[0..], &pad_pos).?);
    try std.testing.expectEqual(@as(usize, 1), pad_pos);
    const trim_variant_tokens = [_]Token{.{ .kind = .identifier, .text = "BTRIM", .keyword = .btrim }};
    var trim_variant_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.trim, expr_token.matchTrimVariantFunctionKind(trim_variant_tokens[0..], &trim_variant_pos).?);
    try std.testing.expectEqual(@as(usize, 1), trim_variant_pos);

    const case_fold_tokens = [_]Token{
