test "sql adapter lower expr validates generated read source alias payloads" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForLowerExprTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT u.id FROM usage_records AS u WHERE u.status = 'open'",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", lowered.table_name);

    var malformed_alias = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT u.id FROM usage_records AS u WHERE u.status = 'open'",
    );
    defer malformed_alias.deinit(alloc);
    try corruptGeneratedReadSourceAliasRange(&malformed_alias);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedQueryPlanWithFunctionBindingsForLowerExprTestAlloc(
        alloc,
        &malformed_alias,
        schema,
        &.{},
        .{},
    ));

    var malformed_table = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'open'",
    );
    defer malformed_table.deinit(alloc);
    try corruptGeneratedReadSourceTableRange(&malformed_table);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedQueryPlanWithFunctionBindingsForLowerExprTestAlloc(
        alloc,
        &malformed_table,
        schema,
        &.{},
        .{},
    ));

    var malformed_projection_alias = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT id AS usage_id FROM usage_records WHERE status = 'open' ORDER BY usage_id",
    );
    defer malformed_projection_alias.deinit(alloc);
    if (malformed_projection_alias.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.projection_items.alias_items.len == 0 or read.projection_items.alias_name_items.len == 0) return error.TestUnexpectedResult;
                const alias_name = read.projection_items.alias_name_items[0] orelse return error.TestUnexpectedResult;
                read.projection_items.alias_items[0] = alias_name;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedQueryPlanWithFunctionBindingsForLowerExprTestAlloc(
        alloc,
        &malformed_projection_alias,
        schema,
        &.{},
        .{},
    ));
}

fn lowerParsedQueryPlanWithFunctionBindingsForLowerExprTestAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    schema: runtime_schema.TableSchema,
    params: []const value_mod.SqlValue,
    function_bindings: expr_row_parse.SqlFunctionBindings,
) !plan_mod.LoweredQueryPlan {
    const parser_context = @import("parser_context.zig");

    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    const tokens = parsed_sql.items();
    const cte_adapter_shape = parser.tokensStartWithKeywordTag(tokens, .with);

    var parser_state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .schema = schema,
        .params = params,
        .function_bindings = function_bindings,
        .generated_read_ast = if (cte_adapter_shape) try generatedCteReadAstForParsedSql(parsed_sql) else try generatedQueryPlanReadAstForParsedSql(parsed_sql),
    };
    var lowered = parseQueryPlanAlloc(
        alloc,
        tokens,
        &parser_state.pos,
        params,
        parser_state.generated_read_ast,
        parser_context.ParserState.ContextAccessors.cteSelectParserHooks(&parser_state),
        parser_context.ParserState.ContextAccessors.queryPlanParserHooks(&parser_state),
