test "sql adapter lower expr lowers recursive cte stream contract" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"parent_id":{"type":"keyword"},"depth":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForLowerExprTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);

    var recursive = try lowerRecursiveCtePlanForLowerExprTestAlloc(
        alloc,
        "WITH RECURSIVE walk(id, depth) AS (SELECT id, depth FROM nodes WHERE parent_id = 'root' UNION ALL SELECT nodes.id, walk.depth + 1 FROM nodes JOIN walk ON nodes.parent_id = walk.id) SELECT id FROM walk",
        schema,
        &.{},
    );
    defer recursive.deinit(alloc);

    try std.testing.expectEqualStrings("walk", recursive.cte_name);
    try std.testing.expectEqual(plan_mod.SelectSetOperation.union_all, recursive.operation);
    try std.testing.expect(recursive.recursive_member_references_cte);
    try std.testing.expectEqual(@as(?u32, db_mod.types.default_relational_rows_cte_max_rows), recursive.max_rows);
    try std.testing.expectEqual(@as(?u64, db_mod.types.default_relational_rows_cte_max_bytes), recursive.max_bytes);
    try std.testing.expectEqual(@as(?u64, db_mod.types.default_relational_rows_cte_spill_after_bytes), recursive.spill_after_bytes);
    try std.testing.expectEqualStrings("nodes", recursive.anchor.table_name);
    try std.testing.expectEqualStrings("parent_id", recursive.anchor.plan.query.predicates[0].field);
    try std.testing.expectEqualStrings("id", recursive.output_columns[0].name);
    try std.testing.expectEqualStrings("id", recursive.output_columns[0].path);
    try std.testing.expectEqualStrings("depth", recursive.output_columns[1].name);
    try std.testing.expectEqualStrings("depth", recursive.output_columns[1].path);
    try std.testing.expectEqual(@as(usize, 1), recursive.final_query.select.len);
    try std.testing.expectEqualStrings("id", recursive.final_query.select[0]);

    const recursive_member_join = switch (recursive.recursive_member) {
        .join => |join| join,
    };
    try std.testing.expectEqualStrings("nodes", recursive_member_join.left_table_name);
    try std.testing.expectEqualStrings("walk", recursive_member_join.right_table_name);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinType.inner, recursive_member_join.join_type);
    try std.testing.expectEqualStrings("parent_id", recursive_member_join.on[0].left_field);
    try std.testing.expectEqualStrings("id", recursive_member_join.on[0].right_field);
    try std.testing.expectEqualStrings("id", recursive_member_join.projections[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, recursive_member_join.projections[1].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionFieldSource.source, recursive_member_join.projections[1].expression.operands[0].field_source);
    try std.testing.expectEqualStrings("depth", recursive_member_join.projections[1].expression.operands[0].field);

    var ordered_recursive = try lowerRecursiveCtePlanForLowerExprTestAlloc(
        alloc,
        "WITH RECURSIVE walk(id, depth) AS (SELECT id, depth FROM nodes WHERE parent_id = 'root' UNION ALL SELECT nodes.id, walk.depth + 1 FROM nodes JOIN walk ON nodes.parent_id = walk.id) SELECT id FROM walk ORDER BY id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer ordered_recursive.deinit(alloc);
    try std.testing.expectEqualStrings("walk", ordered_recursive.cte_name);
    try std.testing.expectEqual(@as(usize, 1), ordered_recursive.final_query.select.len);
    try std.testing.expectEqualStrings("id", ordered_recursive.final_query.select[0]);
    try std.testing.expectEqual(@as(usize, 1), ordered_recursive.final_query.order_by.len);
    try std.testing.expectEqualStrings("id", ordered_recursive.final_query.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 5), ordered_recursive.final_query.limit.?);

    var malformed_generated_anchor = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE walk(id, depth) AS (SELECT id, depth FROM nodes WHERE parent_id = 'root' UNION ALL SELECT nodes.id, walk.depth + 1 FROM nodes JOIN walk ON nodes.parent_id = walk.id) SELECT id FROM walk",
    );
    defer malformed_generated_anchor.deinit(alloc);
    if (malformed_generated_anchor.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.cte_items.len == 0) return error.TestUnexpectedResult;
                const first_projection = read.cte_items[0].body_projection_items.expression_items[0];
                read.cte_items[0].body_where_expression.tokens = first_projection;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedRecursiveCtePlanForLowerExprTestAlloc(
        alloc,
        &malformed_generated_anchor,
        schema,
        &.{},
    ));

    var malformed_generated_recursive_operation = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE walk(id, depth) AS (SELECT id, depth FROM nodes WHERE parent_id = 'root' UNION ALL SELECT nodes.id, walk.depth + 1 FROM nodes JOIN walk ON nodes.parent_id = walk.id) SELECT id FROM walk",
    );
    defer malformed_generated_recursive_operation.deinit(alloc);
    if (malformed_generated_recursive_operation.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.cte_items.len == 0 or read.cte_items[0].body_set_operation.kind == null) return error.TestUnexpectedResult;
                read.cte_items[0].body_set_operation.kind = .except;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedRecursiveCtePlanForLowerExprTestAlloc(
        alloc,
        &malformed_generated_recursive_operation,
        schema,
        &.{},
    ));

    var malformed_generated_recursive_all_range = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE walk(id, depth) AS (SELECT id, depth FROM nodes WHERE parent_id = 'root' UNION ALL SELECT nodes.id, walk.depth + 1 FROM nodes JOIN walk ON nodes.parent_id = walk.id) SELECT id FROM walk",
    );
    defer malformed_generated_recursive_all_range.deinit(alloc);
    if (malformed_generated_recursive_all_range.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.cte_items.len == 0 or
                    read.cte_items[0].body_set_operation.all_tokens == null or
                    read.cte_items[0].body_set_operation.operator_tokens == null)
                {
                    return error.TestUnexpectedResult;
                }
                read.cte_items[0].body_set_operation.all_tokens = read.cte_items[0].body_set_operation.operator_tokens;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedRecursiveCtePlanForLowerExprTestAlloc(
        alloc,
        &malformed_generated_recursive_all_range,
        schema,
        &.{},
    ));

    var malformed_generated_recursive_member_range = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE walk(id, depth) AS (SELECT id, depth FROM nodes WHERE parent_id = 'root' UNION ALL SELECT nodes.id, walk.depth + 1 FROM nodes JOIN walk ON nodes.parent_id = walk.id) SELECT id FROM walk",
    );
    defer malformed_generated_recursive_member_range.deinit(alloc);
    if (malformed_generated_recursive_member_range.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.cte_items.len == 0 or read.cte_items[0].body_set_operation.right_query_tokens == null or read.cte_items[0].body_set_operation.operator_tokens == null) return error.TestUnexpectedResult;
                read.cte_items[0].body_set_operation.right_query_tokens.?.start = read.cte_items[0].body_set_operation.operator_tokens.?.start;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedRecursiveCtePlanForLowerExprTestAlloc(
        alloc,
        &malformed_generated_recursive_member_range,
        schema,
        &.{},
    ));

    var malformed_generated_recursive_member_join = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE walk(id, depth) AS (SELECT id, depth FROM nodes WHERE parent_id = 'root' UNION ALL SELECT nodes.id, walk.depth + 1 FROM nodes JOIN walk ON nodes.parent_id = walk.id) SELECT id FROM walk",
    );
    defer malformed_generated_recursive_member_join.deinit(alloc);
    if (malformed_generated_recursive_member_join.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.cte_items.len == 0 or read.cte_items[0].body_set_operation.right_join_items.len != 1) return error.TestUnexpectedResult;
                read.cte_items[0].body_set_operation.right_join_items[0].right_table_tokens = null;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedRecursiveCtePlanForLowerExprTestAlloc(
        alloc,
        &malformed_generated_recursive_member_join,
        schema,
        &.{},
    ));

    var malformed_generated_recursive_member_projection = try tokenized.ParsedSql.initAlloc(
