test "sql adapter lower expr treats direct graph table functions as relation sources" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"body":{"type":"text"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"datetime"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForLowerExprTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);

    var query = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT id, score FROM antfly.graph_match(table_name => 'usage_records', index => 'docs_edge_graph', start => 'doc:root', pattern => '(a)-[:cites]->(b)', return => 'b') AS gm WHERE graph_name = 'graph_match' ORDER BY score DESC LIMIT 5",
        schema,
        &.{},
    );
    defer query.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", query.table_name);
    try std.testing.expectEqual(@as(usize, 1), query.plan.ctes.len);
    try std.testing.expectEqualStrings("gm", query.plan.ctes[0].name);
    try std.testing.expect(query.plan.ctes[0].table_function != null);
    try std.testing.expectEqualStrings("gm", query.plan.query.source_cte);

    var neighbors_query = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT id, score FROM antfly.graph_neighbors(table_name => 'usage_records', index => 'docs_edge_graph', start => 'doc:root', direction => 'out') AS neighbors WHERE graph_name = 'neighbors' ORDER BY score DESC LIMIT 5",
        schema,
        &.{},
    );
    defer neighbors_query.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", neighbors_query.table_name);
    try std.testing.expectEqual(@as(usize, 1), neighbors_query.plan.ctes.len);
    try std.testing.expectEqualStrings("neighbors", neighbors_query.plan.ctes[0].name);
    switch (neighbors_query.plan.ctes[0].table_function orelse return error.TestUnexpectedResult) {
        .graph_query => |graph_query| {
            try std.testing.expectEqualStrings("usage_records", graph_query.table_name);
            try std.testing.expectEqualStrings("neighbors", graph_query.query.name);
            try std.testing.expectEqual(@as(@TypeOf(graph_query.query.query.query_type), .neighbors), graph_query.query.query.query_type);
            try std.testing.expectEqual(@as(u32, 1), graph_query.query.query.params.max_depth);
        },
        else => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqualStrings("neighbors", neighbors_query.plan.query.source_cte);

    var malformed_graph_source = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT id, score FROM antfly.graph_neighbors(table_name => 'usage_records', index => 'docs_edge_graph', start => 'doc:root', direction => 'out') AS neighbors WHERE graph_name = 'neighbors' ORDER BY score DESC LIMIT 5",
    );
    defer malformed_graph_source.deinit(alloc);
    try corruptGeneratedReadFirstGraphFunctionSourceRange(&malformed_graph_source);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedQueryPlanWithFunctionBindingsForLowerExprTestAlloc(
        alloc,
        &malformed_graph_source,
        schema,
        &.{},
        .{},
    ));

    var malformed_graph_source_count = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT id, score FROM antfly.graph_neighbors(table_name => 'usage_records', index => 'docs_edge_graph', start => 'doc:root', direction => 'out') AS neighbors WHERE graph_name = 'neighbors' ORDER BY score DESC LIMIT 5",
    );
    defer malformed_graph_source_count.deinit(alloc);
    if (malformed_graph_source_count.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| read.source_antfly_function_count += 1,
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedQueryPlanWithFunctionBindingsForLowerExprTestAlloc(
        alloc,
        &malformed_graph_source_count,
        schema,
        &.{},
        .{},
    ));

    var malformed_graph_source_argument_gap = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT id, score FROM antfly.graph_neighbors(table_name => 'usage_records', index => 'docs_edge_graph', start => 'doc:root', direction => 'out') AS neighbors WHERE graph_name = 'neighbors' ORDER BY score DESC LIMIT 5",
    );
    defer malformed_graph_source_argument_gap.deinit(alloc);
    var gap_original_argument_items: []generated_parser.GeneratedSqlNamedArgumentAst = &.{};
    var gap_original_argument_count: usize = 0;
    var gap_mutated_item: ?*generated_parser.GeneratedSqlAntflyTableFunctionAst = null;
    if (malformed_graph_source_argument_gap.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.source_antfly_function_items.len == 0 or
                    read.source_antfly_function_items[0].argument_items.len < 2)
                {
                    return error.TestUnexpectedResult;
                }
                gap_mutated_item = &read.source_antfly_function_items[0];
                gap_original_argument_items = read.source_antfly_function_items[0].argument_items;
                gap_original_argument_count = read.source_antfly_function_items[0].argument_count;
                read.source_antfly_function_items[0].argument_items =
                    read.source_antfly_function_items[0].argument_items[1..];
                read.source_antfly_function_items[0].argument_count =
                    read.source_antfly_function_items[0].argument_items.len;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    defer if (gap_mutated_item) |item| {
        item.argument_items = gap_original_argument_items;
        item.argument_count = gap_original_argument_count;
    };
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedQueryPlanWithFunctionBindingsForLowerExprTestAlloc(
        alloc,
        &malformed_graph_source_argument_gap,
        schema,
        &.{},
        .{},
    ));

    var malformed_graph_source_argument = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT id, score FROM antfly.graph_neighbors(table_name => 'usage_records', index => 'docs_edge_graph', start => 'doc:root', direction => 'out') AS neighbors WHERE graph_name = 'neighbors' ORDER BY score DESC LIMIT 5",
    );
    defer malformed_graph_source_argument.deinit(alloc);
    if (malformed_graph_source_argument.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.source_antfly_function_items.len == 0 or
                    read.source_antfly_function_items[0].argument_items.len == 0 or
                    read.projection_items.items.len == 0)
                {
                    return error.TestUnexpectedResult;
                }
                read.source_antfly_function_items[0].argument_items[0].value_tokens = read.projection_items.items[0];
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedQueryPlanWithFunctionBindingsForLowerExprTestAlloc(
        alloc,
